// Generated from the reviewed question bank. Edit the source JSON, not this file.
export default [{"id":"cie-1-001","topic":"science","level":1,"type":"choice","q":"¿Cómo respiran los tiburones bajo el agua?","why":"Las branquias sacan el oxígeno que hay en el agua. Los delfines sí usan pulmones y suben a respirar aire.","hint":"Piensa en cómo respiran los peces.","tags":["sharks","ocean"],"opts":["Con branquias","Con pulmones","Con la nariz"],"a":0},{"id":"cie-1-002","topic":"science","level":1,"type":"choice","q":"Los dinosaurios nacían de huevos.","why":"Los dinosaurios ponían huevos, igual que las aves de hoy, que son sus parientes.","hint":"Piensa en cómo nace una gallina.","tags":["dinosaurs"],"opts":["Verdadero","Falso"],"a":0},{"id":"cie-1-003","topic":"science","level":1,"type":"order","q":"Ordena estos planetas, del más cercano al Sol al más lejano.","why":"Primero está nuestro planeta, luego Marte y después Júpiter, un gigante que queda mucho más lejos del Sol.","hint":"Empieza por el planeta donde vives.","tags":["space"],"opts":["Tierra","Marte","Júpiter"]},{"id":"cie-1-004","topic":"science","level":1,"type":"choice","q":"¿Cuál de estos animales marinos es un mamífero?","why":"Los delfines respiran aire y alimentan a sus crías con leche. Los tiburones y los pulpos no.","hint":"Los mamíferos toman leche cuando son bebés.","tags":["ocean","animals"],"opts":["El pulpo","El delfín","El tiburón"],"a":1},{"id":"cie-1-005","topic":"science","level":1,"type":"choice","q":"El corazón es un músculo que bombea sangre por todo tu cuerpo.","why":"Cada latido empuja la sangre a todas partes. Es un músculo que trabaja día y noche.","hint":"Ponte la mano en el pecho y siente los latidos.","tags":["body"],"opts":["Verdadero","Falso"],"a":0},{"id":"cie-1-006","topic":"science","level":1,"type":"choice","q":"¿Qué parte de una planta absorbe el agua del suelo?","why":"Las raíces beben el agua que hay en la tierra. Las hojas, en cambio, atrapan la luz del Sol.","hint":"Es la parte que crece bajo la tierra.","tags":[],"opts":["Las hojas","Las flores","Las raíces"],"a":2},{"id":"cie-1-007","topic":"science","level":1,"type":"choice","q":"Un jugador lanza una pelota de béisbol hacia arriba. ¿Qué fuerza la hace caer?","why":"La gravedad jala todo hacia el centro de la Tierra. El viento puede mover la pelota, pero no siempre la hace caer.","hint":"Es la fuerza que te mantiene pegado al suelo.","tags":["baseball"],"opts":["El viento","La gravedad","El sonido"],"a":1},{"id":"cie-1-008","topic":"science","level":1,"type":"choice","q":"El Sol es un planeta.","why":"El Sol es una estrella. Los planetas, como la Tierra, no producen su propia luz.","hint":"Piensa en lo que brilla solo, como las estrellas de noche.","tags":["space"],"opts":["Verdadero","Falso"],"a":1},{"id":"cie-1-009","topic":"science","level":1,"type":"choice","q":"¿Cuál de estos animales marinos tiene ocho brazos?","why":"El pulpo tiene ocho brazos con ventosas. Los delfines y las tortugas marinas nadan con aletas.","hint":"Imagina cada animal y cuenta cuántos brazos tiene.","tags":["ocean","animals"],"opts":["El pulpo","El delfín","La tortuga marina"],"a":0},{"id":"cie-1-010","topic":"science","level":1,"type":"order","q":"Ordena cómo crece una mariposa, de primero a último.","why":"Del huevo sale una oruga que come y crece. Luego se encierra en una crisálida y sale convertida en mariposa.","hint":"Una oruga no vuela; una mariposa sí.","tags":["animals"],"opts":["Huevo","Oruga","Crisálida","Mariposa"]},{"id":"cie-2-001","topic":"science","level":2,"type":"choice","q":"¿Cuál de estos tiburones es enorme, pero se alimenta filtrando plancton diminuto?","why":"Abre su enorme boca y filtra plancton. El tiburón blanco, en cambio, usa sus dientes para atrapar presas.","hint":"Pregúntate cuál de ellos no necesita dientes grandes para comer.","tags":["sharks","ocean"],"opts":["El tiburón blanco","El tiburón martillo","El tiburón ballena"],"a":2},{"id":"cie-2-002","topic":"science","level":2,"type":"choice","q":"El Tyrannosaurus rex vivió en la misma época que las primeras personas.","why":"Los dinosaurios (menos las aves) desaparecieron hace unos 66 millones de años. Las personas aparecieron muchísimo después.","hint":"Piensa en cuánto tiempo hace que no hay dinosaurios.","tags":["dinosaurs"],"opts":["Verdadero","Falso"],"a":1},{"id":"cie-2-003","topic":"science","level":2,"type":"order","q":"Ordena estos animales marinos del más pequeño al más grande.","why":"Una sardina cabe en tu mano. El tiburón blanco mide varios metros, pero la ballena azul es muchísimo más grande.","hint":"Piensa en cuál cabe en tu mano.","tags":["ocean","sharks"],"opts":["Sardina","Tiburón blanco","Ballena azul"]},{"id":"cie-2-004","topic":"science","level":2,"type":"choice","q":"¿Cuál de estos cambios se puede deshacer enfriando?","why":"Al enfriar el agua, vuelve a ser hielo. Un pan tostado o un huevo cocinado no vuelven a ser como antes.","hint":"Piensa en cuál puedes volver a poner en el congelador.","tags":[],"opts":["Un pan que se tostó","Un hielo que se derritió","Un huevo que se cocinó"],"a":1},{"id":"cie-2-005","topic":"science","level":2,"type":"choice","q":"Los huesos de tu cuerpo están vivos.","why":"Los huesos son tejido vivo: crecen y se reparan solos cuando se rompen.","hint":"Piensa en qué pasa cuando se cura un hueso roto.","tags":["body"],"opts":["Verdadero","Falso"],"a":0},{"id":"cie-2-006","topic":"science","level":2,"type":"choice","q":"Cuando el bate golpea una pelota de béisbol, ¿qué cambia en la pelota?","why":"Un golpe es un empujón fuerte que cambia cómo se mueve la pelota. Su peso y su tamaño siguen igual.","hint":"Piensa en cómo se mueve la pelota antes y después.","tags":["baseball"],"opts":["Su dirección y su rapidez","Su peso y su color","Su tamaño y su material"],"a":0},{"id":"cie-2-007","topic":"science","level":2,"type":"choice","q":"¿Qué planeta se conoce como 'el planeta rojo'?","why":"El suelo de Marte tiene óxido de hierro, como el hierro oxidado, y por eso se ve rojizo.","hint":"Piensa en el color del polvo en ese planeta.","tags":["space"],"opts":["Venus","Júpiter","Marte"],"a":2},{"id":"cie-2-008","topic":"science","level":2,"type":"choice","q":"Un imán puede atraer una cuchara de madera.","why":"Los imanes atraen el hierro y algunos otros metales, pero no la madera.","hint":"Piensa de qué material son las cosas que se pegan a un imán.","tags":["machines"],"opts":["Verdadero","Falso"],"a":1},{"id":"cie-2-009","topic":"science","level":2,"type":"choice","q":"¿Cuál de estos animales es un reptil?","why":"Los reptiles tienen escamas o caparazón y respiran aire. La rana es un anfibio y el delfín es un mamífero.","hint":"Los reptiles respiran aire y tienen la piel seca.","tags":["ocean","animals"],"opts":["La rana","La tortuga marina","El delfín"],"a":1},{"id":"cie-2-010","topic":"science","level":2,"type":"order","q":"Ordena cómo crece una planta con flores, de primero a último.","why":"De la semilla sale un brote, crece la planta, da flores y los frutos guardan semillas nuevas.","hint":"Todo empieza con algo pequeño bajo la tierra.","tags":[],"opts":["Semilla","Brote","Planta con flores","Fruto con semillas nuevas"]},{"id":"cie-3-001","topic":"science","level":3,"type":"choice","q":"¿De qué está hecho el esqueleto de un tiburón?","why":"El cartílago es más liviano y flexible que el hueso. Tú tienes cartílago en la nariz y en las orejas.","hint":"Toca la punta de tu nariz: ¿se dobla?","tags":["sharks"],"opts":["Cartílago flexible","Hueso duro","Concha de calcio","Escamas de piel"],"a":0},{"id":"cie-3-002","topic":"science","level":3,"type":"choice","q":"Algunos dinosaurios tenían plumas.","why":"Se han encontrado fósiles de dinosaurios con plumas. Las aves de hoy descienden de ellos.","hint":"Piensa en qué animales vivos se parecen a los dinosaurios.","tags":["dinosaurs"],"opts":["Verdadero","Falso"],"a":0},{"id":"cie-3-003","topic":"science","level":3,"type":"order","q":"Ordena las capas de la Tierra, de la superficie al centro.","why":"La corteza es la capa delgada donde vivimos. Más abajo está el manto y, en el centro, el núcleo.","hint":"Piensa en las capas de una cebolla, de afuera hacia adentro.","tags":[],"opts":["Corteza","Manto","Núcleo externo","Núcleo interno"]},{"id":"cie-3-004","topic":"science","level":3,"type":"choice","q":"¿Qué animal marino debe subir a la superficie para respirar aire?","why":"Las ballenas son mamíferos y respiran aire con pulmones. Los peces y los pulpos usan branquias.","hint":"Piensa en el chorro de agua que sale de su cabeza.","tags":["ocean","animals"],"opts":["El pulpo","La ballena","La raya","El caballito de mar"],"a":1},{"id":"cie-3-005","topic":"science","level":3,"type":"choice","q":"¿Qué instrumento usan los científicos para medir cuánta lluvia cayó?","why":"El pluviómetro recoge el agua de lluvia en un tubo con marcas. El termómetro mide la temperatura.","hint":"La palabra 'pluvial' tiene que ver con la lluvia.","tags":["weather"],"opts":["Termómetro","Brújula","Pluviómetro","Cronómetro"],"a":2},{"id":"cie-3-006","topic":"science","level":3,"type":"choice","q":"Cuando corres, tu corazón late más despacio.","why":"Al correr, tus músculos necesitan más oxígeno. Por eso el corazón late más rápido y lleva más sangre.","hint":"Piensa en lo que sientes en el pecho después de correr.","tags":["body"],"opts":["Verdadero","Falso"],"a":1},{"id":"cie-3-007","topic":"science","level":3,"type":"choice","q":"Una pelota de béisbol rueda por pasto largo y se detiene antes que sobre pasto corto. ¿Qué fuerza la frena más?","why":"El pasto largo roza más la pelota y le quita rapidez. La gravedad la jala hacia abajo, pero no la frena.","hint":"Es la fuerza que aparece cuando dos superficies se rozan.","tags":["baseball"],"opts":["El magnetismo","La gravedad","La electricidad","La fricción"],"a":3},{"id":"cie-3-008","topic":"science","level":3,"type":"order","q":"Ordena el recorrido del agua, de primero a último.","why":"El Sol calienta el agua y la convierte en vapor. Arriba el vapor se enfría, forma nubes y después llueve.","hint":"Empieza por lo que hace el Sol con el agua.","tags":["weather"],"opts":["El agua se evapora","El vapor forma nubes","La lluvia cae al suelo"]},{"id":"cie-3-009","topic":"science","level":3,"type":"number","q":"Un insecto tiene 6 patas. ¿Cuántas patas tienen 4 insectos en total?","why":"Cuatro grupos de seis patas son 24 patas. Las arañas tienen 8 patas y no son insectos.","hint":"Piensa en cuatro grupos de seis.","tags":["animals"],"a":24},{"id":"cie-3-010","topic":"science","level":3,"type":"choice","q":"¿Por qué vemos las fases de la Luna?","why":"El Sol siempre ilumina la mitad de la Luna; nosotros vemos más o menos de esa mitad. La sombra de la Tierra causa los eclipses.","hint":"Piensa en cómo cambia lo que ves de una pelota iluminada si te mueves.","tags":["space"],"opts":["La sombra de la Tierra la va tapando","Vemos distintas partes de su lado iluminado","La Luna se encoge y luego crece","Las nubes la van cubriendo cada noche"],"a":1},{"id":"cie-4-001","topic":"science","level":4,"type":"choice","q":"Los tiburones tienen unos poros en el hocico llamados ampollas de Lorenzini. ¿Para qué les sirven?","why":"Detectan los diminutos campos eléctricos que producen los animales escondidos. Respirar es trabajo de las branquias.","hint":"Es un sentido extra que nosotros no tenemos.","tags":["sharks","ocean"],"opts":["Para respirar mientras duermen","Para oír sonidos muy lejanos","Para detectar la electricidad de las presas","Para ver en la oscuridad"],"a":2,"fun":true},{"id":"cie-4-002","topic":"science","level":4,"type":"order","q":"Ordena los periodos de la era de los dinosaurios, del más antiguo al más reciente.","why":"Primero vino el Triásico, luego el Jurásico y al final el Cretácico, cuando vivió el Tyrannosaurus rex.","hint":"El Tyrannosaurus rex vivió casi al final.","tags":["dinosaurs"],"opts":["Triásico","Jurásico","Cretácico"]},{"id":"cie-4-003","topic":"science","level":4,"type":"choice","q":"El sonido viaja más rápido en el agua que en el aire.","why":"Las partículas del agua están más juntas y pasan la vibración con más rapidez. Por eso las ballenas se oyen desde lejos.","hint":"Piensa en lo que se oye cuando metes la cabeza bajo el agua.","tags":["ocean"],"opts":["Verdadero","Falso"],"a":0},{"id":"cie-4-004","topic":"science","level":4,"type":"choice","q":"¿Qué causa el día y la noche en la Tierra?","why":"La Tierra da una vuelta sobre sí misma cada 24 horas. El lado que mira al Sol tiene día.","hint":"Piensa en un trompo que gira.","tags":["space"],"opts":["La Tierra gira sobre sí misma","El Sol da vueltas alrededor de la Tierra","La Luna tapa al Sol cada día","La Tierra se acerca y aleja del Sol"],"a":0},{"id":"cie-4-005","topic":"science","level":4,"type":"choice","q":"Una pelota de béisbol vuela por el aire después del golpe. ¿Qué energía tiene por estar en movimiento?","why":"Todo lo que se mueve tiene energía de movimiento, también llamada cinética. Mientras más rápido va, más tiene.","hint":"Piensa en lo que tiene un objeto que se mueve.","tags":["baseball"],"opts":["Energía de la luz","Energía del sonido","Energía de los alimentos","Energía de movimiento"],"a":3},{"id":"cie-4-006","topic":"science","level":4,"type":"choice","q":"Un pulpo tiene tres corazones.","why":"Dos corazones envían sangre a las branquias y el tercero la manda al resto del cuerpo.","hint":"Los pulpos son muy distintos a nosotros por dentro.","tags":["ocean","animals"],"opts":["Verdadero","Falso"],"a":0,"fun":true},{"id":"cie-4-007","topic":"science","level":4,"type":"order","q":"Ordena el camino de un bocado de comida por tu cuerpo.","why":"Masticas en la boca, el esófago baja la comida, el estómago la mezcla y el intestino delgado absorbe los nutrientes.","hint":"Empieza por donde entra la comida.","tags":["body"],"opts":["Boca","Esófago","Estómago","Intestino delgado"]},{"id":"cie-4-008","topic":"science","level":4,"type":"choice","q":"Un río arrastra tierra y piedritas de un lugar a otro. ¿Cómo se llama este proceso?","why":"La erosión ocurre cuando el agua, el viento o el hielo desgastan y arrastran la tierra. La evaporación solo convierte agua en vapor.","hint":"Piensa en cómo los ríos van cambiando el paisaje.","tags":[],"opts":["Erosión","Evaporación","Condensación","Hibernación"],"a":0},{"id":"cie-4-009","topic":"science","level":4,"type":"choice","q":"Para subir una caja a la misma altura, una rampa más larga necesita más fuerza que una más corta.","why":"Una rampa larga reparte el esfuerzo en más distancia. Necesitas menos fuerza, pero debes empujar más lejos.","hint":"Piensa en subir una loma por un camino largo o por uno empinado.","tags":["machines"],"opts":["Verdadero","Falso"],"a":1},{"id":"cie-4-010","topic":"science","level":4,"type":"choice","q":"Para saber si la luz ayuda a crecer a una planta, pones una al sol y otra en un clóset oscuro. ¿Qué debe ser igual en ambas?","why":"En una prueba justa solo cambias una cosa: la luz. Todo lo demás, como el agua, debe ser igual.","hint":"Solo debes cambiar una cosa a la vez.","tags":[],"opts":["La cantidad de luz","El lugar donde está cada planta","La cantidad de agua","Nada: pueden recibir cosas distintas"],"a":2},{"id":"cie-5-001","topic":"science","level":5,"type":"choice","q":"Todos los tiburones deben nadar sin parar para poder respirar.","why":"El tiburón nodriza bombea agua por sus branquias y descansa quieto en el fondo. Otros, como el blanco, sí deben nadar.","hint":"La palabra 'todos' es fuerte: busca una excepción.","tags":["sharks"],"opts":["Verdadero","Falso"],"a":1},{"id":"cie-5-002","topic":"science","level":5,"type":"choice","q":"¿En qué tipo de roca es más probable encontrar un fósil de dinosaurio?","why":"Los huesos se entierran bajo capas de sedimento que se endurecen. El calor del magma destruiría un fósil.","hint":"Piensa en capas de arena y barro que se endurecen.","tags":["dinosaurs"],"opts":["Ígnea","Sedimentaria","Metamórfica","En todas por igual"],"a":1},{"id":"cie-5-003","topic":"science","level":5,"type":"order","q":"Ordena estos planetas por tamaño, del más pequeño al más grande.","why":"Mercurio y Marte son pequeños y la Tierra es mayor. Saturno y Júpiter son gigantes, y Júpiter es el más grande.","hint":"Los gigantes gaseosos son los más grandes.","tags":["space"],"opts":["Mercurio","Marte","Tierra","Saturno","Júpiter"]},{"id":"cie-5-004","topic":"science","level":5,"type":"choice","q":"En la playa, durante el día suele soplar la brisa del mar hacia la tierra. ¿Por qué?","why":"La arena se calienta más rápido que el agua. Su aire sube y el aire fresco del mar entra a ocupar su lugar.","hint":"Fíjate en qué se pone más caliente al sol: la arena o el agua.","tags":["weather","ocean"],"opts":["Las olas empujan el aire hacia la costa","La Luna jala el aire del mar","El mar se calienta antes que la arena","El aire caliente sobre la tierra sube"],"a":3},{"id":"cie-5-005","topic":"science","level":5,"type":"choice","q":"Mercurio está más cerca del Sol, pero Venus es más caliente en su superficie.","why":"La atmósfera espesa de Venus atrapa el calor como una cobija gruesa. Mercurio casi no tiene atmósfera.","hint":"Piensa en qué hace una atmósfera gruesa con el calor.","tags":["space"],"opts":["Verdadero","Falso"],"a":0,"fun":true},{"id":"cie-5-006","topic":"science","level":5,"type":"order","q":"Ordena las zonas del océano, desde la superficie hasta el fondo.","why":"Cada zona es más profunda y oscura que la anterior, hasta llegar al abismo, donde no llega nada de luz.","hint":"Piensa en hasta dónde llega la luz del Sol.","tags":["ocean"],"opts":["Zona de luz solar","Zona crepuscular","Zona de medianoche","El abismo"]},{"id":"cie-5-007","topic":"science","level":5,"type":"choice","q":"¿Por qué el cielo se ve azul durante el día?","why":"La luz del Sol mezcla todos los colores. El aire esparce la azul en todas direcciones, y la vemos en todo el cielo.","hint":"La luz blanca está hecha de todos los colores del arcoíris.","tags":[],"opts":["El aire dispersa más la luz azul","El cielo refleja el color de los océanos","Las moléculas del aire son de color azul","El Sol emite solamente luz de color azul"],"a":0},{"id":"cie-5-008","topic":"science","level":5,"type":"choice","q":"Lanzas una pelota de béisbol hacia arriba. ¿En qué momento su rapidez es cero, aunque sea solo un instante?","why":"La gravedad la frena mientras sube, hasta que se detiene un instante arriba. Después empieza a caer.","hint":"Piensa en el momento en que cambia de subir a bajar.","tags":["baseball"],"opts":["Justo al salir de tu mano","A mitad de camino al subir","Nunca llega a ser cero","En el punto más alto"],"a":3},{"id":"cie-5-009","topic":"science","level":5,"type":"number","q":"A las 6 a. m., un termómetro marca 4 grados bajo cero (-4 °C). Al mediodía sube 9 grados. ¿Cuántos °C marca al mediodía?","why":"Desde -4 subes 4 grados para llegar a 0 y 5 más: llegas a 5 °C.","hint":"Cuenta hacia arriba desde -4, pasando por el cero.","tags":["weather"],"a":5},{"id":"cie-5-010","topic":"science","level":5,"type":"choice","q":"¿Qué hacen los glóbulos rojos de la sangre?","why":"Los glóbulos rojos transportan oxígeno. Los glóbulos blancos combaten microbios y las plaquetas ayudan a cerrar las heridas.","hint":"Piensa en el trabajo de transporte de la sangre.","tags":["body"],"opts":["Combaten los microbios","Ayudan a que la sangre se coagule","Llevan oxígeno a todo el cuerpo","Digieren los alimentos"],"a":2},{"id":"cie-6-001","topic":"science","level":6,"type":"choice","q":"¿Con cuál de estos animales actuales tiene un parentesco más cercano el Tyrannosaurus rex?","why":"Las aves descienden de dinosaurios terópodos, el grupo del T. rex. Los cocodrilos y las lagartijas son parientes más lejanos.","hint":"Piensa en qué animales de hoy descienden de los dinosaurios.","tags":["dinosaurs","animals"],"opts":["Con un cocodrilo","Con una gallina","Con una lagartija","Con una tortuga"],"a":1,"fun":true},{"id":"cie-6-002","topic":"science","level":6,"type":"choice","q":"Sin aire, un martillo y una pluma caen a la misma rapidez.","why":"Sin aire no hay resistencia. En la Luna, un astronauta soltó un martillo y una pluma y tocaron el suelo a la vez.","hint":"Piensa en qué frena a una pluma cuando cae.","tags":["space"],"opts":["Verdadero","Falso"],"a":0,"fun":true},{"id":"cie-6-003","topic":"science","level":6,"type":"choice","q":"Quito está casi sobre el ecuador, pero sus noches son frescas. ¿Cuál es la razón principal?","why":"En las montañas altas el aire es más frío, incluso sobre el ecuador.","hint":"Piensa en qué pasa con el aire cuando subes una montaña.","tags":["weather"],"opts":["El Sol brilla menos allí","Está rodeada de selva","Está a gran altura sobre el mar","Está cerca de una corriente fría"],"a":2},{"id":"cie-6-004","topic":"science","level":6,"type":"order","q":"Ordena esta cadena alimentaria del mar, empezando por quien produce su propio alimento.","why":"El fitoplancton hace su alimento con luz solar. El zooplancton se lo come, la sardina come zooplancton y el tiburón come sardinas.","hint":"La energía empieza en lo que usa la luz del Sol.","tags":["ocean","sharks"],"opts":["Fitoplancton","Zooplancton","Sardina","Tiburón"]},{"id":"cie-6-005","topic":"science","level":6,"type":"choice","q":"Los músculos solo pueden jalar, no empujar. Entonces, ¿cómo estiras el codo después de doblarlo?","why":"Los músculos trabajan en pares: el bíceps dobla el codo y el tríceps lo estira.","hint":"Un músculo jala hacia un lado y otro jala hacia el contrario.","tags":["body"],"opts":["El bíceps también puede empujar el hueso","Otro músculo jala en sentido contrario","Los huesos del brazo se estiran solos","La sangre empuja el brazo hacia afuera"],"a":1},{"id":"cie-6-006","topic":"science","level":6,"type":"choice","q":"Los tiburones y los delfines tienen cuerpos de forma parecida, aunque no son parientes cercanos. ¿Por qué?","why":"Animales de grupos distintos pueden desarrollar formas parecidas si viven de modo parecido. El delfín es mamífero y respira con pulmones.","hint":"Piensa en qué forma sirve para moverse bien en el agua.","tags":["sharks","ocean"],"opts":["Los delfines descienden de los tiburones","Los dos son peces cartilaginosos","Los dos respiran con branquias","Esa forma les ayuda a nadar rápido"],"a":3},{"id":"cie-6-007","topic":"science","level":6,"type":"choice","q":"Como se venden más helados cuando hay más encuentros con tiburones, los helados atraen a los tiburones.","why":"Ambas cosas aumentan en verano porque hay más gente en la playa. Que dos cosas ocurran juntas no prueba que una cause la otra.","hint":"Pregúntate qué otra cosa podría explicar las dos.","tags":["sharks"],"opts":["Verdadero","Falso"],"a":1},{"id":"cie-6-008","topic":"science","level":6,"type":"number","q":"Un satélite tarda 90 minutos en dar una vuelta completa a la Tierra. ¿Cuántas vueltas completas da en 6 horas?","why":"6 horas son 360 minutos, y 360 ÷ 90 = 4. Primero hay que usar la misma unidad.","hint":"Convierte las horas a minutos primero.","tags":["space"],"a":4},{"id":"cie-6-009","topic":"science","level":6,"type":"choice","q":"La luz del Sol tarda unos 8 minutos en llegar a la Tierra. Si el Sol desapareciera de repente, ¿cuándo dejaríamos de ver su luz?","why":"La luz que ya salió sigue viajando 8 minutos. Vemos el Sol como era hace 8 minutos.","hint":"La luz viaja muy rápido, pero no es instantánea.","tags":["space"],"opts":["Unos 8 minutos después","En ese mismo instante","Unas 8 horas después","Al día siguiente"],"a":0},{"id":"cie-6-010","topic":"science","level":6,"type":"choice","q":"Un cubo de hielo flota en un vaso con agua. ¿Cuál es la mejor explicación?","why":"Al congelarse, el agua ocupa más espacio y se vuelve menos densa, por eso flota. Así flotan los icebergs.","hint":"Compara cuánta masa cabe en el mismo espacio.","tags":["ocean"],"opts":["El hielo pesa menos que todo el vaso","Todo lo frío flota en el agua","Las burbujas de aire dentro lo sostienen","El hielo es menos denso que el agua"],"a":3},{"id":"mun-1-001","topic":"world","level":1,"type":"choice","q":"La Antártida es un continente muy frío, cubierto de hielo.","why":"La Antártida está en el polo sur y casi toda está cubierta de hielo. Allí viven pingüinos y focas.","hint":"Piensa en dónde queda el polo sur.","tags":["maps","animals"],"opts":["Verdadero","Falso"],"a":0},{"id":"mun-1-002","topic":"world","level":1,"type":"choice","q":"¿En qué continente está Ecuador?","why":"Ecuador está en el noroeste de América del Sur, junto al océano Pacífico.","hint":"Piensa en el continente donde está la selva del Amazonas.","tags":["maps"],"opts":["África","Asia","América del Sur"],"a":2},{"id":"mun-1-003","topic":"world","level":1,"type":"choice","q":"California y Ecuador tienen costa en el mismo océano. ¿Cuál es?","why":"Los dos están en la costa oeste de América, frente al océano Pacífico.","hint":"Mira la costa oeste de América en un mapa.","tags":["ocean","maps"],"opts":["El Pacífico","El Atlántico","El Índico"],"a":0},{"id":"mun-1-004","topic":"world","level":1,"type":"order","q":"Ordena de lo más pequeño a lo más grande.","why":"Tu casa está dentro de tu ciudad, tu ciudad dentro de un continente y los continentes están en la Tierra.","hint":"Cada lugar cabe dentro del siguiente.","tags":["maps"],"opts":["Tu casa","Tu ciudad","Un continente","La Tierra"]},{"id":"mun-1-005","topic":"world","level":1,"type":"choice","q":"¿Cuál de estas cosas es una necesidad?","why":"Una necesidad es algo que debes tener para vivir. Un videojuego es algo que quieres, pero puedes vivir sin él.","hint":"Pregúntate: ¿puedo vivir sin esto?","tags":[],"opts":["Un videojuego","Una bicicleta nueva","Agua para beber"],"a":2},{"id":"mun-1-006","topic":"world","level":1,"type":"choice","q":"La mayor parte de la superficie de la Tierra es tierra firme, no agua.","why":"Más de dos tercios de la Tierra están cubiertos por océanos. Por eso se le llama el planeta azul.","hint":"Piensa en cuánto azul ves en un globo terráqueo.","tags":["ocean","maps"],"opts":["Verdadero","Falso"],"a":1},{"id":"mun-1-007","topic":"world","level":1,"type":"choice","q":"En un mapa, ¿qué dibujo te dice dónde queda el norte?","why":"La rosa de los vientos marca el norte, el sur, el este y el oeste. La leyenda explica los símbolos.","hint":"Su nombre parece el de una flor.","tags":["maps"],"opts":["El título","La rosa de los vientos","La leyenda"],"a":1},{"id":"mun-1-008","topic":"world","level":1,"type":"choice","q":"¿Qué animal gigante es famoso en las islas Galápagos?","why":"El nombre Galápagos viene de 'galápago', una palabra antigua del español para tortuga.","hint":"Piensa en un animal lento con caparazón.","tags":["animals","ocean"],"opts":["La tortuga gigante","El elefante","El oso polar"],"a":0,"fun":true},{"id":"mun-1-009","topic":"world","level":1,"type":"choice","q":"En un desierto llueve casi todos los días.","why":"Un desierto recibe muy poca lluvia. Las selvas tropicales son las que reciben muchísima.","hint":"Piensa en un lugar con cactus y arena.","tags":["weather"],"opts":["Verdadero","Falso"],"a":1},{"id":"mun-1-010","topic":"world","level":1,"type":"choice","q":"Una isla es un pedazo de tierra rodeado de…","why":"Las islas están rodeadas de agua por todos lados, como las islas de Hawái o las Bahamas.","hint":"Piensa en cómo llegas a Hawái.","tags":["ocean","maps"],"opts":["Montañas","Desierto","Agua"],"a":2},{"id":"mun-2-001","topic":"world","level":2,"type":"choice","q":"¿Cuál de estos nombres es un continente y no un océano?","why":"África es una gran masa de tierra. El Pacífico y el Índico son océanos, extensiones enormes de agua salada.","hint":"Busca el nombre que es tierra y no agua.","tags":["maps"],"opts":["África","Pacífico","Índico"],"a":0},{"id":"mun-2-002","topic":"world","level":2,"type":"order","q":"Un bateador pega un jonrón. Ordena las bases que pisa, desde que sale del home.","why":"Los corredores recorren el cuadro en sentido contrario a las agujas del reloj, hasta volver al home.","hint":"Gira a la izquierda en cada base.","tags":["baseball","maps"],"opts":["Primera base","Segunda base","Tercera base","Home otra vez"]},{"id":"mun-2-003","topic":"world","level":2,"type":"choice","q":"Las islas de Hawái se formaron por volcanes que crecieron desde el fondo del océano.","why":"La lava se fue acumulando capa tras capa bajo el agua hasta llegar a la superficie y formar islas.","hint":"Piensa en lo que sale de un volcán.","tags":["ocean"],"opts":["Verdadero","Falso"],"a":0},{"id":"mun-2-004","topic":"world","level":2,"type":"choice","q":"Miras hacia el norte y das un cuarto de vuelta a la derecha. ¿Hacia dónde miras ahora?","why":"Con el norte al frente, el este queda a tu derecha y el oeste a tu izquierda.","hint":"Dibuja la rosa de los vientos y gira con el dedo.","tags":["maps"],"opts":["Hacia el oeste","Hacia el este","Hacia el sur"],"a":1},{"id":"mun-2-005","topic":"world","level":2,"type":"choice","q":"¿Dónde hace más calor durante todo el año?","why":"Cerca del ecuador los rayos del Sol llegan más directos. El país Ecuador se llama así por esa línea.","hint":"Un país de América del Sur lleva el nombre de esta línea.","tags":["maps","weather"],"opts":["Cerca del ecuador","Cerca del polo norte","Cerca del polo sur"],"a":0},{"id":"mun-2-006","topic":"world","level":2,"type":"choice","q":"Cuando amanece, el Sol sale por el oeste.","why":"El Sol sale por el este y se oculta por el oeste, porque la Tierra gira hacia el este.","hint":"En español, el lugar donde sale el Sol se llama oriente.","tags":["space","maps"],"opts":["Verdadero","Falso"],"a":1},{"id":"mun-2-007","topic":"world","level":2,"type":"choice","q":"En Galápagos viven iguanas que nadan en el mar. ¿Qué comen bajo el agua?","why":"Las iguanas marinas se sumergen para comer algas pegadas a las rocas. Solo viven en las islas Galápagos.","hint":"Piensa en lo que crece pegado a las rocas bajo el agua.","tags":["ocean","animals"],"opts":["Peces pequeños","Algas","Cangrejos"],"a":1},{"id":"mun-2-008","topic":"world","level":2,"type":"order","q":"Ordena de lo más antiguo a lo más nuevo.","why":"Los dinosaurios vivieron hace millones de años. Las pirámides tienen miles de años y los celulares son muy recientes.","hint":"Pregúntate qué existía antes de que hubiera personas.","tags":["dinosaurs"],"opts":["Los dinosaurios","Las pirámides de Egipto","Los teléfonos celulares"]},{"id":"mun-2-009","topic":"world","level":2,"type":"choice","q":"Machu Picchu, la antigua ciudad de piedra de los incas, está en las montañas de…","why":"Los Andes cruzan América del Sur, incluso Ecuador. Los Alpes están en Europa y el Himalaya, en Asia.","hint":"Esta cordillera también pasa por Ecuador.","tags":["maps"],"opts":["Los Alpes","El Himalaya","Los Andes"],"a":2},{"id":"mun-2-010","topic":"world","level":2,"type":"choice","q":"¿Cuál de estas cosas es un deseo y no una necesidad?","why":"Un deseo es algo que quieres, pero puedes vivir sin él. Un hogar y la ropa de abrigo son necesidades.","hint":"Un deseo es algo bonito de tener, pero no indispensable.","tags":["food"],"opts":["Un helado de chocolate","Un lugar donde dormir","Ropa para el frío"],"a":0},{"id":"mun-3-001","topic":"world","level":3,"type":"number","q":"Un puesto compra pelotas de béisbol a $3 cada una y las vende a $5 cada una. ¿Cuántos dólares de ganancia obtiene al vender 4 pelotas?","why":"Gana $2 por pelota: 5 - 3 = 2. Con 4 pelotas, 4 × 2 = $8.","hint":"Primero calcula cuánto gana por una sola pelota.","tags":["baseball","money"],"a":8},{"id":"mun-3-002","topic":"world","level":3,"type":"choice","q":"¿Para qué sirve la escala de un mapa?","why":"La escala compara la distancia en el mapa con la distancia real. El norte lo muestra la rosa de los vientos.","hint":"Piensa en '1 cm del mapa = cuántos km reales'.","tags":["maps"],"opts":["Para saber dónde queda el norte","Para calcular distancias reales","Para saber qué significan los símbolos","Para saber cuándo se hizo el mapa"],"a":1},{"id":"mun-3-003","topic":"world","level":3,"type":"choice","q":"En la Antártida viven osos polares.","why":"Los osos polares viven en el Ártico, cerca del polo norte. En la Antártida viven pingüinos y focas.","hint":"El Ártico y la Antártida están en polos opuestos.","tags":["animals","maps"],"opts":["Verdadero","Falso"],"a":1},{"id":"mun-3-004","topic":"world","level":3,"type":"choice","q":"Las Bahamas son islas de aguas cristalinas. ¿En qué océano están?","why":"Las Bahamas están en el océano Atlántico, al este de Florida. El Pacífico queda al otro lado de América.","hint":"Piensa en qué océano baña la costa este de Estados Unidos.","tags":["ocean","maps"],"opts":["Atlántico","Pacífico","Índico","Ártico"],"a":0},{"id":"mun-3-005","topic":"world","level":3,"type":"choice","q":"Ahorrar dinero significa…","why":"Ahorrar es guardar dinero hoy para comprar algo más adelante. Gastar es usarlo ahora mismo.","hint":"Piensa en lo que se guarda en una alcancía.","tags":["money"],"opts":["Gastar todo el dinero hoy mismo","Prestar todo tu dinero a un amigo","Guardar parte del dinero para después","Cambiar billetes por monedas pequeñas"],"a":2},{"id":"mun-3-006","topic":"world","level":3,"type":"order","q":"Ordena estos cuatro océanos del más pequeño al más grande.","why":"El Ártico es el más pequeño de estos cuatro y el Pacífico, el más grande de todo el planeta.","hint":"Empieza por el océano que está cerca del polo norte.","tags":["ocean","maps"],"opts":["Ártico","Índico","Atlántico","Pacífico"]},{"id":"mun-3-007","topic":"world","level":3,"type":"choice","q":"¿Qué lugar es cálido, muy lluvioso y está lleno de plantas todo el año?","why":"En la selva tropical hace calor y llueve casi todos los días. La tundra es fría y el desierto, muy seco.","hint":"Piensa en la selva del Amazonas.","tags":["weather","animals"],"opts":["Un desierto","Una selva tropical","La tundra","Una pradera seca"],"a":1},{"id":"mun-3-008","topic":"world","level":3,"type":"choice","q":"En el noroeste del Pacífico, los salmones nadan desde el mar hasta los ríos para poner sus huevos.","why":"Muchos salmones nacen en un río, viven años en el océano y regresan a su río para reproducirse.","hint":"Piensa en peces que nadan contra la corriente de un río.","tags":["ocean","animals"],"opts":["Verdadero","Falso"],"a":0},{"id":"mun-3-009","topic":"world","level":3,"type":"choice","q":"Hace siglos, los marineros se guiaban con un instrumento de aguja que apunta al norte. ¿Cómo se llama?","why":"La aguja magnética de la brújula se alinea con el campo magnético de la Tierra y apunta hacia el norte.","hint":"Su aguja se mueve sola, sin que la toques.","tags":["maps"],"opts":["Termómetro","Telescopio","Brújula","Reloj de sol"],"a":2},{"id":"mun-3-010","topic":"world","level":3,"type":"choice","q":"Además del español, en los Andes de Ecuador se habla una lengua de los pueblos originarios. ¿Cuál?","why":"El kichwa es una lengua de los pueblos originarios de los Andes y se sigue hablando hoy.","hint":"Es una lengua de las montañas andinas.","tags":["maps"],"opts":["El kichwa","El maorí","El suajili","El japonés"],"a":0},{"id":"mun-4-001","topic":"world","level":4,"type":"choice","q":"Cerca de las islas Galápagos se pueden ver grandes grupos de tiburones martillo.","why":"Cerca de las islas Darwin y Wolf, en ciertas épocas se reúnen grupos de cientos de tiburones martillo.","hint":"Piensa en un archipiélago famoso por su vida marina.","tags":["sharks","ocean"],"opts":["Verdadero","Falso"],"a":0,"fun":true},{"id":"mun-4-002","topic":"world","level":4,"type":"choice","q":"Cuando es verano en el hemisferio norte, ¿qué estación hay en el hemisferio sur?","why":"La Tierra está inclinada: cuando el hemisferio norte recibe más luz solar directa, el sur recibe menos.","hint":"Cuando un hemisferio se inclina hacia el Sol, el otro se aleja.","tags":["weather","maps"],"opts":["Verano","Primavera","Otoño","Invierno"],"a":3},{"id":"mun-4-003","topic":"world","level":4,"type":"choice","q":"Quedan pocas entradas para un partido de béisbol muy esperado y mucha gente quiere ir. ¿Qué suele pasar con el precio?","why":"Cuando algo escasea y mucha gente lo quiere, el precio suele subir. Se llama oferta y demanda.","hint":"Piensa en lo que pasa cuando hay pocas y muchos las quieren.","tags":["baseball","money"],"opts":["Suele bajar","Suele subir","No cambia nunca","Baja solo para los niños"],"a":1},{"id":"mun-4-004","topic":"world","level":4,"type":"order","q":"Ordena el recorrido de un río, desde su nacimiento hasta el final.","why":"El agua baja de las montañas, junta más agua y se vuelve más ancha hasta llegar al mar.","hint":"Piensa en hacia dónde fluye siempre el agua.","tags":["ocean"],"opts":["Nace en un manantial de la montaña","Baja como arroyo","Se ensancha como río","Desemboca en el mar"]},{"id":"mun-4-005","topic":"world","level":4,"type":"number","q":"En un mapa, 1 cm representa 5 km. Dos ciudades están a 6 cm en el mapa. ¿Cuántos km hay entre ellas?","why":"Cada centímetro vale 5 km, así que 6 cm son 6 × 5 = 30 km.","hint":"Multiplica los centímetros por lo que vale cada uno.","tags":["maps"],"a":30},{"id":"mun-4-006","topic":"world","level":4,"type":"choice","q":"Una península es un pedazo de tierra rodeado de agua por todos sus lados.","why":"Eso describe una isla. Una península está unida al continente por un lado y rodeada de agua por los demás.","hint":"Piensa en la diferencia entre una isla y Baja California.","tags":["maps"],"opts":["Verdadero","Falso"],"a":1},{"id":"mun-4-007","topic":"world","level":4,"type":"choice","q":"¿Cómo se llama la zona climática del planeta donde hace calor casi todo el año?","why":"La zona tropical es la más cálida y queda en el centro del planeta. La templada y la polar están más lejos.","hint":"Piensa en las selvas y las playas más calurosas.","tags":["weather","maps"],"opts":["La zona templada","La zona polar","La zona ártica","La zona tropical"],"a":3},{"id":"mun-4-008","topic":"world","level":4,"type":"choice","q":"Los incas construyeron una gran red de caminos de piedra que cruzaba los Andes.","why":"El Qhapaq Ñan, o camino inca, atravesaba montañas de varios países de América del Sur, incluido Ecuador.","hint":"Piensa en cómo conectaban los incas sus ciudades en las montañas.","tags":["maps"],"opts":["Verdadero","Falso"],"a":0},{"id":"mun-4-009","topic":"world","level":4,"type":"choice","q":"El monumento de la Mitad del Mundo, cerca de Quito, se construyó para señalar una línea imaginaria. ¿Cuál?","why":"El ecuador está a 0° de latitud y divide la Tierra en hemisferio norte y hemisferio sur.","hint":"Piensa en el nombre del país donde está el monumento.","tags":["maps"],"opts":["El trópico de Cáncer","El trópico de Capricornio","El ecuador","El círculo polar ártico"],"a":2},{"id":"mun-4-010","topic":"world","level":4,"type":"choice","q":"Una familia hace un presupuesto. ¿Qué es un presupuesto?","why":"Un presupuesto reparte el dinero entre gastos y ahorros. Una lista de deseos no dice cuánto dinero hay.","hint":"Un presupuesto ayuda a decidir antes de gastar.","tags":["money"],"opts":["Un plan para gastar y ahorrar","Una lista de todo lo que quieres comprar","El dinero que sobra a fin de mes","El precio más bajo de un producto"],"a":0},{"id":"mun-5-001","topic":"world","level":5,"type":"choice","q":"La Gran Muralla China se puede ver a simple vista desde la Luna.","why":"Los astronautas dicen que no se ve a simple vista desde la Luna. Es larguísima, pero muy angosta.","hint":"Piensa en lo lejos que está la Luna.","tags":["space","maps"],"opts":["Verdadero","Falso"],"a":1,"fun":true},{"id":"mun-5-002","topic":"world","level":5,"type":"choice","q":"Cuando son las 3:00 p. m. en Los Ángeles, son las 6:00 p. m. en Nueva York. Si en Nueva York son las 9:00 p. m., ¿qué hora es en Los Ángeles?","why":"Los Ángeles va 3 horas detrás de Nueva York. Entonces, a las 9:00 p. m. allá, aquí son las 6:00 p. m.","hint":"Resta tres horas: Los Ángeles queda más al oeste.","tags":["maps"],"opts":["12:00 a. m.","9:00 p. m.","6:00 p. m.","3:00 p. m."],"a":2},{"id":"mun-5-003","topic":"world","level":5,"type":"choice","q":"¿Qué tipo de mapa usarías para ver las montañas, los ríos y los desiertos de un lugar?","why":"Un mapa físico muestra el relieve: montañas, ríos y desiertos. Un mapa de carreteras muestra rutas, no el terreno.","hint":"Piensa en el aspecto natural de la Tierra.","tags":["maps"],"opts":["Un mapa de carreteras","Un mapa del tiempo","Un mapa de husos horarios","Un mapa físico"],"a":3},{"id":"mun-5-004","topic":"world","level":5,"type":"order","q":"Ordena estas ciudades de la más cercana al ecuador a la más lejana.","why":"Quito está casi sobre el ecuador (0°). Los Ángeles queda a unos 34° norte, Seattle a unos 48° y Anchorage a unos 61°.","hint":"Piensa en cuál está más al norte en un mapa.","tags":["maps"],"opts":["Quito","Los Ángeles","Seattle","Anchorage"]},{"id":"mun-5-005","topic":"world","level":5,"type":"number","q":"Una tienda compra cada camiseta en $8 y la vende en $12. Vende 5 camisetas y paga $15 de alquiler. ¿Cuántos dólares de ganancia le quedan?","why":"Gana 12 - 8 = $4 por camiseta; con 5 son $20. Al pagar $15 de alquiler le quedan $5.","hint":"Calcula primero la ganancia de las 5 camisetas.","tags":["money"],"a":5},{"id":"mun-5-006","topic":"world","level":5,"type":"choice","q":"Los navegantes polinesios cruzaron miles de kilómetros de océano en canoas hasta llegar a Hawái. ¿Cómo se orientaban?","why":"Leían el cielo y el mar: estrellas, oleaje, vientos y vuelo de las aves. No usaban brújula ni mapas escritos.","hint":"Piensa en lo que se ve en el cielo de noche y en el mar.","tags":["ocean","maps"],"opts":["Con una brújula magnética","Con las estrellas y el oleaje","Con mapas dibujados en papel","Con luces de faros en las islas"],"a":1},{"id":"mun-5-007","topic":"world","level":5,"type":"choice","q":"La Antártida es técnicamente un desierto, aunque esté cubierta de hielo.","why":"Un desierto se define por recibir muy poca lluvia o nieve, no por el calor. En la Antártida cae muy poca.","hint":"Piensa en cuánta nieve cae allí cada año.","tags":["maps","weather"],"opts":["Verdadero","Falso"],"a":0,"fun":true},{"id":"mun-5-008","topic":"world","level":5,"type":"choice","q":"La isla Isabela, en Galápagos, está cruzada por el ecuador, así que parte de ella está en cada hemisferio.","why":"El ecuador cruza la isla por los volcanes Wolf y Ecuador. Un trozo está en el hemisferio norte y el resto en el sur.","hint":"Piensa en la línea que divide el hemisferio norte del sur.","tags":["maps","ocean"],"opts":["Verdadero","Falso"],"a":0,"fun":true},{"id":"mun-5-009","topic":"world","level":5,"type":"choice","q":"Con $10 puedes comprar una pelota de béisbol o un libro, pero no los dos. A lo que renuncias al elegir se le llama…","why":"Elegir una cosa significa renunciar a otra. El valor de lo que dejas de tener se llama costo de oportunidad.","hint":"Piensa en lo que pierdes al elegir una opción.","tags":["baseball","money"],"opts":["Costo de oportunidad","Ganancia","Ahorro","Impuesto"],"a":0},{"id":"mun-5-010","topic":"world","level":5,"type":"order","q":"Ordena estos hechos, del más antiguo al más reciente.","why":"Pirámides: hace unos 4 500 años. Imprenta: hacia 1450. Primer vuelo de los Wright: 1903. Luna: 1969.","hint":"Piensa en lo que necesita más tecnología.","tags":["space"],"opts":["Se construyen las pirámides de Egipto","Gutenberg usa su imprenta en Europa","Los hermanos Wright hacen su primer vuelo","Personas caminan sobre la Luna"]},{"id":"mun-6-001","topic":"world","level":6,"type":"number","q":"La Tierra da una vuelta completa de 360° en 24 horas. En promedio, ¿cuántos grados de longitud tiene cada huso horario?","why":"360 ÷ 24 = 15. Cada hora de diferencia equivale a unos 15 grados de longitud.","hint":"Divide los grados de una vuelta entre las horas de un día.","tags":["space","maps"],"a":15},{"id":"mun-6-002","topic":"world","level":6,"type":"choice","q":"¿Qué línea imaginaria se usa como 0° de longitud?","why":"El meridiano de Greenwich es el 0° de longitud. El ecuador es el 0° de latitud, otra medida distinta.","hint":"La longitud se mide de este a oeste, no de norte a sur.","tags":["maps"],"opts":["El ecuador","El trópico de Capricornio","El meridiano de Greenwich","La línea de cambio de fecha"],"a":2},{"id":"mun-6-003","topic":"world","level":6,"type":"choice","q":"Las estaciones del año ocurren porque la Tierra se acerca y se aleja del Sol.","why":"Se deben a la inclinación del eje terrestre. Incluso estamos más cerca del Sol en enero, en pleno invierno del norte.","hint":"Piensa en por qué hay verano en un hemisferio e invierno en el otro.","tags":["space","weather"],"opts":["Verdadero","Falso"],"a":1,"fun":true},{"id":"mun-6-004","topic":"world","level":6,"type":"order","q":"Ordena estas ciudades de oeste a este.","why":"Honolulu está en el Pacífico, al oeste de todas. Quito queda un poco al oeste de Nueva York y Londres está cerca del meridiano 0°.","hint":"Imagina un mapamundi: el Pacífico queda a la izquierda.","tags":["maps"],"opts":["Honolulu","Los Ángeles","Quito","Nueva York","Londres"]},{"id":"mun-6-005","topic":"world","level":6,"type":"number","q":"Un banco paga $5 de interés al año por cada $100 ahorrados. Si ahorras $200 durante un año, ¿cuántos dólares tendrás al final?","why":"Por cada $100 ganas $5, así que por $200 ganas $10. Tu ahorro pasa de $200 a $210.","hint":"Calcula primero el interés de los $200.","tags":["money"],"a":210},{"id":"mun-6-006","topic":"world","level":6,"type":"choice","q":"El Niño es un cambio en el océano Pacífico. ¿Qué pasa con el agua cerca de las costas de Ecuador y Perú cuando ocurre?","why":"Durante El Niño el agua superficial se calienta, y eso cambia la lluvia y la pesca en muchos lugares del mundo.","hint":"Piensa en qué cambia en la temperatura del agua.","tags":["ocean","weather"],"opts":["Se congela en la superficie","Se vuelve mucho más salada","Se hace menos profunda","Se calienta más de lo normal"],"a":3},{"id":"mun-6-007","topic":"world","level":6,"type":"choice","q":"Una brújula apunta siempre al polo norte geográfico, el punto más al norte de la Tierra.","why":"La brújula apunta al norte magnético, que está cerca del polo norte geográfico, pero no es el mismo lugar.","hint":"Piensa en qué atrae la aguja de una brújula.","tags":["maps"],"opts":["Verdadero","Falso"],"a":1},{"id":"mun-6-008","topic":"world","level":6,"type":"choice","q":"¿Cuál de estas palabras del español viene del quechua, la lengua de los Andes?","why":"Papa viene del quechua. Naranja, azúcar y zanahoria llegaron del árabe, otra lengua que enriqueció al español.","hint":"Piensa en dónde nació cada alimento.","tags":["food"],"opts":["Papa","Naranja","Azúcar","Zanahoria"],"a":0,"fun":true},{"id":"mun-6-009","topic":"world","level":6,"type":"choice","q":"Las islas Galápagos están sobre el ecuador, pero allí vive un pingüino. ¿Qué hace posible que viva en un lugar tan cálido?","why":"Las corrientes frías de Humboldt y Cromwell enfrían el agua y traen peces. Sin ellas, los pingüinos no sobrevivirían allí.","hint":"Piensa en qué enfría el mar, no la tierra.","tags":["ocean","animals"],"opts":["La nieve que cubre las islas","Las corrientes frías del océano","El hielo que llega desde la Antártida","Los vientos helados del polo norte"],"a":1},{"id":"mun-6-010","topic":"world","level":6,"type":"order","q":"Ordena estas construcciones de la más antigua a la más reciente.","why":"Giza: hace unos 4 500 años. Coliseo: hacia el año 80. Machu Picchu: hacia 1450. Torre Eiffel: 1889.","hint":"Separa las de la Antigüedad de las de la época moderna.","tags":["maps"],"opts":["Pirámides de Giza","Coliseo de Roma","Machu Picchu","Torre Eiffel"]},{"id":"lec-1-001","topic":"reading","level":1,"type":"choice","q":"¿Cuál es el contrario de 'caliente'?","why":"Caliente y frío son opuestos, como el fuego y el hielo.","hint":"Piensa en un helado.","tags":[],"opts":["lento","alto","frío"],"a":2},{"id":"lec-1-002","topic":"reading","level":1,"type":"choice","q":"El dinosaurio era enorme: sus patas parecían columnas. ¿Qué significa 'enorme'?","why":"Si las patas parecen columnas, el animal es gigante. 'Enorme' quiere decir muy grande.","hint":"Las columnas son gruesas y altas.","tags":["dinosaurs"],"opts":["Muy grande","Muy rápido","Muy viejo"],"a":0},{"id":"lec-1-003","topic":"reading","level":1,"type":"choice","q":"La estrella de mar y las estrellas del cielo son lo mismo.","why":"La estrella de mar es un animal del océano; las del cielo son soles muy lejanos.","hint":"Piensa dónde vive cada una.","tags":["ocean","space"],"opts":["Verdadero","Falso"],"a":1,"fun":true},{"id":"lec-1-004","topic":"reading","level":1,"type":"choice","q":"El corredor del equipo es muy veloz. ¿Qué significa 'veloz'?","why":"'Veloz' y 'rápido' significan casi lo mismo: se mueve con mucha velocidad.","hint":"Imagina al corredor llegando a la base.","tags":["baseball"],"opts":["Cansado","Rápido","Alto"],"a":1},{"id":"lec-1-005","topic":"reading","level":1,"type":"choice","q":"Sofía abrió el paraguas y se puso las botas de lluvia. ¿Qué tiempo hacía?","why":"El paraguas y las botas de lluvia se usan cuando llueve.","hint":"Mira lo que se puso Sofía.","tags":["weather"],"opts":["Hacía mucho sol","Llovía","Era de noche"],"a":1},{"id":"lec-1-006","topic":"reading","level":1,"type":"order","q":"Ordena la historia de Ana y la semilla.","why":"Las palabras primero, después, luego y al final marcan el orden.","hint":"Busca las palabras que marcan el orden.","tags":[],"opts":["Primero, Ana compró una semilla.","Después, la plantó en la tierra.","Luego, la regó todos los días.","Al final, salió una flor."]},{"id":"lec-1-007","topic":"reading","level":1,"type":"choice","q":"Tomás perdió su guante de béisbol y se sentó en el suelo con la cabeza baja. ¿Cómo se sentía?","why":"Sentarse en el suelo con la cabeza baja son pistas de tristeza.","hint":"Fíjate en cómo tiene la cabeza.","tags":["baseball"],"opts":["Contento","Triste","Sorprendido"],"a":1},{"id":"lec-1-008","topic":"reading","level":1,"type":"choice","q":"El bate, la pelota y el guante son cosas de un deporte. ¿De cuál?","why":"El bate, la pelota y el guante se usan en el béisbol.","hint":"Piensa en un estadio con bases.","tags":["baseball"],"opts":["Béisbol","Natación","Ciclismo"],"a":0},{"id":"lec-1-009","topic":"reading","level":1,"type":"number","q":"'El pulpo, el delfín y la tortuga nadan en el mar.' ¿Cuántos animales aparecen en la oración?","why":"Los animales son el pulpo, el delfín y la tortuga. El mar no es un animal.","hint":"Cuenta solo los animales.","tags":["ocean"],"a":3},{"id":"lec-1-010","topic":"reading","level":1,"type":"choice","q":"Los pulpos tienen ocho brazos. Con ellos agarran comida y caminan por el fondo del mar. ¿De qué trata el texto?","why":"Todo el texto habla del pulpo y de sus brazos.","hint":"¿Qué animal se repite en todo el texto?","tags":["ocean"],"opts":["De cómo se construye un barco","De los peces que viven en ríos","Del pulpo"],"a":2},{"id":"lec-2-001","topic":"reading","level":2,"type":"choice","q":"El tiburón nadaba silencioso entre las rocas. ¿Qué significa 'silencioso'?","why":"Silencioso viene de silencio: no se oye ningún ruido.","hint":"Mira la palabra 'silencio' dentro.","tags":["sharks"],"opts":["Con mucha hambre","Muy rápido","Sin hacer ruido"],"a":2},{"id":"lec-2-002","topic":"reading","level":2,"type":"choice","q":"El jugador ____ a toda velocidad hacia la base. ¿Qué verbo encaja mejor?","why":"'A toda velocidad' pide un verbo de rapidez: corrió. Pasear y gatear son lentos.","hint":"Busca el verbo más veloz.","tags":["baseball"],"opts":["corrió","paseó despacio","gateó sin prisa"],"a":0},{"id":"lec-2-003","topic":"reading","level":2,"type":"choice","q":"'Alegre' y 'triste' significan casi lo mismo.","why":"Son antónimos: alegre es contento y triste es lo contrario.","hint":"Piensa en la cara de cada uno.","tags":[],"opts":["Verdadero","Falso"],"a":1},{"id":"lec-2-004","topic":"reading","level":2,"type":"choice","q":"¿Cuál es el contrario de 'despegar', cuando hablamos de un cohete?","why":"El cohete despega para subir y aterriza para bajar y posarse.","hint":"Piensa en cómo termina un viaje.","tags":["space"],"opts":["Sobrevolar","Orbitar","Aterrizar"],"a":2},{"id":"lec-2-005","topic":"reading","level":2,"type":"choice","q":"Lucas guardó sus guantes en la mochila y bostezó. Mamá apagó la luz de su cuarto. ¿Qué iba a hacer Lucas?","why":"Bostezar y apagar la luz son pistas de que es hora de dormir.","hint":"¿Qué se hace cuando se apaga la luz?","tags":[],"opts":["Dormir","Jugar béisbol","Desayunar"],"a":0},{"id":"lec-2-006","topic":"reading","level":2,"type":"order","q":"Ordena estos animales del más pequeño al más grande.","why":"Un ratón cabe en la mano; la ballena azul es más grande que cualquier elefante.","hint":"Empieza por el que cabe en tu mano.","tags":["animals","ocean"],"opts":["ratón","perro","elefante","ballena azul"],"fun":true},{"id":"lec-2-007","topic":"reading","level":2,"type":"choice","q":"El primer día de clases, Pablo no soltaba la mano de su mamá. ¿Cómo se sentía?","why":"No soltar la mano de mamá muestra nervios ante algo nuevo.","hint":"Piensa en lo que sientes con algo nuevo.","tags":[],"opts":["Aburrido","Nervioso","Orgulloso"],"a":1},{"id":"lec-2-008","topic":"reading","level":2,"type":"choice","q":"El buzo explora el fondo del mar. ¿Qué hace un 'buzo'?","why":"Un buzo es una persona que baja y trabaja bajo el agua.","hint":"Piensa en dónde está el fondo del mar.","tags":["ocean"],"opts":["Vuela en cohete","Nada bajo el agua","Maneja un barco grande"],"a":1},{"id":"lec-2-009","topic":"reading","level":2,"type":"number","q":"'Hay tres tiburones y dos delfines en la bahía.' ¿Cuántos animales hay en total?","why":"Tres tiburones más dos delfines son cinco animales en la bahía.","hint":"Suma los dos grupos.","tags":["sharks","ocean"],"a":5},{"id":"lec-2-010","topic":"reading","level":2,"type":"choice","q":"Hoy no hubo práctica de béisbol porque llovió toda la tarde. ¿Por qué no hubo práctica?","why":"La palabra 'porque' señala la causa: llovió toda la tarde.","hint":"Busca la palabra 'porque'.","tags":["baseball","weather"],"opts":["Porque hacía calor","Porque se rompió el bate","Porque llovió"],"a":2},{"id":"lec-3-001","topic":"reading","level":3,"type":"choice","q":"La tortuga marina avanzaba despacio por la arena, con mucho cuidado. ¿Qué palabra significa lo mismo que 'despacio'?","why":"Despacio y lentamente significan que se hace con poca velocidad.","hint":"Piensa en cómo se mueve una tortuga.","tags":["ocean"],"opts":["lentamente","rápidamente","ruidosamente","alegremente"],"a":0},{"id":"lec-3-002","topic":"reading","level":3,"type":"choice","q":"El astrónomo ____ la Luna con su telescopio durante horas, con mucha atención. ¿Qué verbo encaja mejor?","why":"'Durante horas' y 'con atención' piden observar: mirar con cuidado.","hint":"Busca el verbo para mirar con mucha atención.","tags":["space"],"opts":["echó un vistazo a","vio de pasada","miró de reojo","observó"],"a":3},{"id":"lec-3-003","topic":"reading","level":3,"type":"choice","q":"Un fósil es la huella o el resto de un ser vivo muy antiguo, conservado en la roca.","why":"Los fósiles de dinosaurios se encuentran en rocas muy antiguas.","hint":"Piensa en los huesos de dinosaurio de un museo.","tags":["dinosaurs"],"opts":["Verdadero","Falso"],"a":0},{"id":"lec-3-004","topic":"reading","level":3,"type":"choice","q":"Los tiburones pierden dientes toda la vida, pero les crecen nuevos. Así siempre tienen dientes afilados para comer. ¿Cuál es la idea principal?","why":"La idea principal es lo que más se repite: los dientes que se renuevan.","hint":"¿De qué habla el texto en cada oración?","tags":["sharks"],"opts":["Los tiburones comen peces muy pequeños","Los dientes de los niños se caen","Los tiburones nadan muy rápido","Los tiburones renuevan sus dientes"],"a":3,"fun":true},{"id":"lec-3-005","topic":"reading","level":3,"type":"choice","q":"El lanzador tiró la pelota muy fuerte y el bateador la golpeó lejos. Todos gritaron: '¡Jonrón!'. ¿Qué pasó con la pelota?","why":"Un jonrón es cuando la pelota sale del campo por encima de la cerca.","hint":"¿Qué significa gritar 'jonrón'?","tags":["baseball"],"opts":["Salió volando del campo","Cayó en el guante del jardinero","Se quedó en la mano del lanzador","Rodó hasta la primera base"],"a":0},{"id":"lec-3-006","topic":"reading","level":3,"type":"order","q":"Ordena los momentos del día de la tortuga.","why":"Las pistas son: salió el sol, caminó, al llegar, por la noche.","hint":"Sigue el orden del día: mañana, tarde y noche.","tags":["ocean"],"opts":["El sol salió y despertó a la tortuga.","Caminó hacia el mar con pasos lentos.","Al llegar, se zambulló en las olas.","Por la noche, flotó tranquila y descansó."]},{"id":"lec-3-007","topic":"reading","level":3,"type":"choice","q":"Daniel falló el golpe y su equipo perdió. Apretó los puños, frunció el ceño y pateó el suelo. ¿Qué sentía?","why":"Puños apretados, ceño fruncido y patadas son pistas de enojo.","hint":"¿Qué emoción muestran los puños apretados?","tags":["baseball"],"opts":["Miedo","Alivio","Enojo","Aburrimiento"],"a":2},{"id":"lec-3-008","topic":"reading","level":3,"type":"choice","q":"Mi hermano duerme como un tronco. ¿Qué quiere decir esa expresión?","why":"Un tronco no se mueve; por eso 'dormir como un tronco' es dormir muy profundo.","hint":"Piensa en cuánto se mueve un tronco.","tags":[],"opts":["Duerme encima de un árbol","Duerme muy profundamente","Duerme muy poco","Duerme parado"],"a":1},{"id":"lec-3-009","topic":"reading","level":3,"type":"choice","q":"'El béisbol es el mejor deporte del mundo' es un hecho que se puede comprobar.","why":"'Mejor' depende de los gustos de cada persona. Es una opinión, no un hecho.","hint":"¿Todos piensan igual sobre el mejor deporte?","tags":["baseball"],"opts":["Verdadero","Falso"],"a":1},{"id":"lec-3-010","topic":"reading","level":3,"type":"choice","q":"El telescopio sirve para ver cosas lejanas, como las estrellas. ¿Qué significa 'tele-' en esta palabra?","why":"'Tele-' significa lejos. 'Micro-' es pequeño, 'hidro-' es agua y 'bio-' es vida.","hint":"Piensa para qué sirve un telescopio.","tags":["space"],"opts":["Pequeño","Lejos","Agua","Vida"],"a":1},{"id":"lec-4-001","topic":"reading","level":4,"type":"choice","q":"El buzo vio un banco de peces plateados. En esta oración, ¿qué es un 'banco'?","why":"En el mar, un banco es un grupo grande de peces que nadan juntos.","hint":"Fíjate en que el texto habla de peces.","tags":["ocean"],"opts":["Un lugar para guardar dinero","Un grupo de peces","Un asiento largo de madera","Una roca grande y plana"],"a":1},{"id":"lec-4-002","topic":"reading","level":4,"type":"choice","q":"La serpiente ____ por la arena sin levantar el cuerpo. ¿Qué verbo es el más preciso?","why":"Las serpientes se deslizan pegadas al suelo. Saltar, trotar y trepar no describen eso.","hint":"Piensa en cómo se mueve una serpiente.","tags":["animals"],"opts":["dio saltitos","trotó muy rápido","se deslizó","trepó con fuerza"],"a":2},{"id":"lec-4-003","topic":"reading","level":4,"type":"choice","q":"'Los tiburones dan miedo' es un hecho que se puede comprobar.","why":"Dar miedo depende de cada persona. Es una opinión, no un hecho.","hint":"¿Todas las personas sienten lo mismo?","tags":["sharks"],"opts":["Verdadero","Falso"],"a":1},{"id":"lec-4-004","topic":"reading","level":4,"type":"choice","q":"El sonido viaja muy bien por el agua. Por eso las ballenas azules emiten sonidos graves que otras ballenas oyen desde muy lejos. ¿Cuál es la causa de que se oigan de lejos?","why":"La causa viene antes de 'por eso': el sonido viaja bien por el agua.","hint":"Busca la causa antes de 'por eso'.","tags":["ocean"],"opts":["El agua del mar está muy caliente","Las ballenas tienen orejas enormes","Las ballenas cantan solo en tormentas","El sonido viaja bien por el agua"],"a":3},{"id":"lec-4-005","topic":"reading","level":4,"type":"choice","q":"'Hidro-' significa agua. ¿Qué es un 'hidroavión'?","why":"'Hidro-' viene de agua: el hidroavión se posa y despega del agua.","hint":"Une la raíz con la palabra 'avión'.","tags":["machines"],"opts":["Un avión hecho completamente de hielo","Un avión que vuela solamente de noche","Un avión que aterriza en agua","Un avión que no necesita motor"],"a":2},{"id":"lec-4-006","topic":"reading","level":4,"type":"order","q":"Ordena el nacimiento de una tortuga marina.","why":"Primero van los huevos, luego nacen, después caminan y al final nadan.","hint":"Piensa qué ocurre antes: ¿huevos o crías?","tags":["ocean"],"opts":["La mamá deja los huevos en la arena.","Después de semanas, los huevos se abren.","Las tortuguitas corren hacia el mar.","Allí empiezan a nadar."]},{"id":"lec-4-007","topic":"reading","level":4,"type":"choice","q":"Cuando dicen 'tengo mariposas en el estómago', ¿qué sienten?","why":"Es una expresión: los nervios o la emoción se sienten como aleteos en la barriga.","hint":"Piensa si hay mariposas de verdad.","tags":[],"opts":["Hambre de comer algo dulce","Nervios o emoción","Frío en todo el cuerpo","Sueño y ganas de dormir"],"a":1},{"id":"lec-4-008","topic":"reading","level":4,"type":"choice","q":"¿Cuál de estas frases es un HECHO?","why":"Un hecho se puede comprobar. 'Bonito', 'aburrido' y 'genial' son opiniones.","hint":"Un hecho se puede comprobar con pruebas.","tags":["space"],"opts":["La Tierra gira alrededor del Sol","La Luna es lo más bonito del cielo","Marte es el planeta más aburrido","Vivir en el espacio sería genial"],"a":0},{"id":"lec-4-009","topic":"reading","level":4,"type":"choice","q":"La palabra 'murciélago' tiene las cinco vocales: a, e, i, o, u.","why":"Mur-cié-la-go tiene u, i, e, a, o. Es una de las pocas palabras con todas las vocales.","hint":"Escribe la palabra y marca las vocales.","tags":["animals"],"opts":["Verdadero","Falso"],"a":0,"fun":true},{"id":"lec-4-010","topic":"reading","level":4,"type":"choice","q":"El cielo se puso muy gris, el viento sopló fuerte y los pájaros volaron a sus nidos. ¿Qué iba a pasar pronto?","why":"Cielo gris y viento fuerte son pistas de tormenta. Una sequía es falta de lluvia.","hint":"Piensa qué anuncian las nubes grises y el viento.","tags":["weather"],"opts":["Una tormenta","Un eclipse solar","Una gran sequía","Un amanecer rojo"],"a":0},{"id":"lec-5-001","topic":"reading","level":5,"type":"choice","q":"Todos hablaron del jonrón que ganó el partido en la última entrada: fue un golpe memorable. ¿Qué significa 'memorable'?","why":"Memorable viene de memoria: algo que vale la pena recordar.","hint":"Piensa en la palabra 'memoria'.","tags":["baseball"],"opts":["Digno de ser recordado","Muy suave y demasiado lento","Lleno de errores y fallas","Imposible de ver desde lejos"],"a":0},{"id":"lec-5-002","topic":"reading","level":5,"type":"choice","q":"En el desierto el agua es escasa. ¿Cuál es el antónimo de 'escasa'?","why":"Escasa significa poca. Su contrario es abundante: mucha. Las otras tres son sinónimos de escasa.","hint":"Busca el que significa mucha cantidad.","tags":[],"opts":["limitada","insuficiente","reducida","abundante"],"a":3},{"id":"lec-5-003","topic":"reading","level":5,"type":"choice","q":"La palabra 'astronauta' significa 'navegante de los océanos'.","why":"Astro es estrella y nauta, navegante. El astronauta es un navegante de las estrellas.","hint":"Fíjate en la raíz 'astro'.","tags":["space"],"opts":["Verdadero","Falso"],"a":1},{"id":"lec-5-004","topic":"reading","level":5,"type":"choice","q":"Ese bateador tiene ojo de águila: no se le escapa ninguna pelota. ¿Qué quiere decir esa expresión?","why":"'Ojo de águila' se dice de quien ve y se da cuenta de todo, como un águila.","hint":"Las águilas ven desde muy lejos.","tags":["baseball"],"opts":["Tiene un ojo lastimado","Es muy bravo y agresivo","Lleva lentes especiales","Observa y nota todo"],"a":3},{"id":"lec-5-005","topic":"reading","level":5,"type":"choice","q":"¿Qué enseña el refrán 'Camarón que se duerme, se lo lleva la corriente'?","why":"Es una metáfora: quien se descuida pierde su oportunidad, como el camarón dormido.","hint":"No habla de camarones de verdad.","tags":["ocean"],"opts":["Los camarones nadan mejor cuando oscurece del todo","Hay que estar atentos y aprovechar oportunidades","Hay que dormir mucho para tener más energía","Las corrientes del mar siempre son peligrosas"],"a":1},{"id":"lec-5-006","topic":"reading","level":5,"type":"order","q":"Ordena cómo se forma un fósil.","why":"Primero muere, luego lo cubre el barro, el barro se endurece y mucho después aparece.","hint":"Piensa en lo que ocurre antes de ser enterrado.","tags":["dinosaurs"],"opts":["Un dinosaurio muere cerca de un río.","El barro cubre sus huesos.","El barro se endurece y se vuelve roca.","Millones de años después, alguien encuentra el fósil."]},{"id":"lec-5-007","topic":"reading","level":5,"type":"choice","q":"Inés aplaudió y sonrió cuando dijeron el nombre de su amiga, pero se mordió el labio y bajó la mirada. ¿Qué sentía?","why":"Aplaudir y sonreír muestran alegría; morderse el labio y bajar la mirada, decepción.","hint":"Hay dos pistas distintas: lo que hace al principio y al final.","tags":[],"opts":["Muy enojada con su amiga por haber ganado","Contenta por su amiga y algo decepcionada","Aburrida y sin ninguna gana de aplaudir","Orgullosa de haber ganado ella misma el premio"],"a":1},{"id":"lec-5-008","topic":"reading","level":5,"type":"choice","q":"'Bio' significa vida y 'grafía', escritura. ¿Qué es una 'biografía'?","why":"Bio (vida) + grafía (escritura): la biografía cuenta la vida de una persona.","hint":"Une los significados de las dos partes.","tags":[],"opts":["Un libro de dibujos de animales","Un mapa que muestra el cuerpo","El relato de la vida de alguien","Una carta escrita a un amigo"],"a":2},{"id":"lec-5-009","topic":"reading","level":5,"type":"choice","q":"Los pulpos tienen tres corazones.","why":"Dos corazones envían sangre a las branquias y el tercero, al resto del cuerpo.","hint":"Piensa en el cuerpo tan raro de los pulpos.","tags":["ocean"],"opts":["Verdadero","Falso"],"a":0,"fun":true},{"id":"lec-5-010","topic":"reading","level":5,"type":"choice","q":"Un cometa se acerca al Sol y su hielo se calienta. Por eso se forma una cola brillante. ¿Cuál es la causa de la cola?","why":"La causa va antes de 'por eso': el hielo se calienta y forma la cola.","hint":"Busca la causa antes de 'por eso'.","tags":["space"],"opts":["La Luna empuja el cometa hacia afuera","Los cometas giran muy rápido sobre sí mismos","El hielo se calienta cerca del Sol","El cometa se enfría en el espacio"],"a":2},{"id":"lec-6-001","topic":"reading","level":6,"type":"choice","q":"Los científicos hicieron una hipótesis: el megalodón desapareció porque el mar se enfrió y su comida escaseó. ¿Qué es una hipótesis?","why":"Una hipótesis es una posible explicación que luego se prueba con evidencias.","hint":"Los científicos la prueban después.","tags":["sharks"],"opts":["Una explicación que se puede probar","Un dato que ya se comprobó hace años","Un dibujo científico del animal extinto","Una opinión que nunca se puede probar"],"a":0},{"id":"lec-6-002","topic":"reading","level":6,"type":"choice","q":"Algunas flores de cactus son efímeras: duran solo un día. ¿Qué palabra significa lo CONTRARIO de 'efímera'?","why":"Efímera es lo que dura poco; su contrario es duradera. Fugaz es sinónimo de efímera.","hint":"Busca la que significa 'dura mucho'.","tags":[],"opts":["Fugaz","Delicada","Duradera","Colorida"],"a":2},{"id":"lec-6-003","topic":"reading","level":6,"type":"choice","q":"'Hipopótamo' viene del griego y significa 'caballo de río'.","why":"Hippos es caballo y potamós, río. Los antiguos griegos lo llamaron así.","hint":"Piensa en dónde pasa el día este animal.","tags":["animals"],"opts":["Verdadero","Falso"],"a":0,"fun":true},{"id":"lec-6-004","topic":"reading","level":6,"type":"choice","q":"'A buen entendedor, pocas palabras bastan' significa que...","why":"Al que entiende pronto le bastan pocas palabras. No hace falta explicarle de más.","hint":"Fíjate en quién es el 'buen entendedor'.","tags":[],"opts":["Para convencer a alguien hay que repetir mucho","Entender bien cuesta muchas palabras difíciles","Quien entiende rápido no necesita más palabras","Los que hablan poco entienden menos cosas"],"a":2},{"id":"lec-6-005","topic":"reading","level":6,"type":"choice","q":"—¡Qué día tan perfecto! —suspiró Pablo, mientras la lluvia le mojaba el uniforme y suspendían el partido de béisbol. ¿Qué quiso decir Pablo?","why":"Es ironía: dice una cosa para dar a entender lo contrario, y la situación lo muestra.","hint":"Compara lo que dice con lo que le pasa.","tags":["baseball","weather"],"opts":["Que estaba feliz de que lloviera tanto","Que el partido sería mucho mejor mojado","Que no le importaba nada el partido","Lo contrario: el día era malo"],"a":3},{"id":"lec-6-006","topic":"reading","level":6,"type":"order","q":"Ordena estos vientos del más suave al más fuerte.","why":"Una brisa apenas mueve las hojas; el ventarrón es muy fuerte y el huracán es aún más.","hint":"Empieza por el que apenas mueve las hojas.","tags":["weather"],"opts":["brisa","viento","ventarrón","huracán"]},{"id":"lec-6-007","topic":"reading","level":6,"type":"choice","q":"Hallaron fósiles de peces en la cima de una montaña muy alta. ¿Qué se puede deducir?","why":"Los fósiles marinos en montañas indican que esa tierra estuvo cubierta por el mar y luego se elevó.","hint":"Piensa dónde vivían esos peces.","tags":["ocean"],"opts":["Que esa tierra estuvo bajo el mar","Que unos pescadores los dejaron allí","Que los peces antiguos vivían en tierra firme","Que son rocas con forma de pez"],"a":0,"fun":true},{"id":"lec-6-008","topic":"reading","level":6,"type":"choice","q":"¿Cuál de estas palabras expresa el miedo MÁS intenso?","why":"Pavor es un miedo muy fuerte. Inquietud y recelo son más suaves.","hint":"Ordena mentalmente de miedo leve a miedo enorme.","tags":[],"opts":["Inquietud","Recelo","Temor","Pavor"],"a":3},{"id":"lec-6-009","topic":"reading","level":6,"type":"choice","q":"Los tiburones ya nadaban en los mares antes de que existieran los dinosaurios.","why":"Los antepasados de los tiburones aparecieron hace unos 400 millones de años; los dinosaurios, hace unos 230.","hint":"Compara hace cuánto tiempo apareció cada uno.","tags":["sharks","dinosaurs"],"opts":["Verdadero","Falso"],"a":0,"fun":true},{"id":"lec-6-010","topic":"reading","level":6,"type":"choice","q":"Algunas plantas atrapan insectos. La planta carnívora cierra sus hojas como una trampa y así obtiene nutrientes que el suelo pobre no le da. ¿Cuál es la idea central?","why":"La idea central abarca todo el texto. 'Todas las plantas' exagera: dice 'algunas'.","hint":"Cuidado con las opciones que dicen 'todas'.","tags":[],"opts":["Los insectos prefieren vivir en suelos pobres","Algunas plantas cazan insectos para nutrirse","Las hojas se cierran cuando llega la noche","Todas las plantas necesitan comer insectos"],"a":1},{"id":"pal-1-001","topic":"words","level":1,"type":"choice","q":"¿Cuál es el plural de 'pez'?","why":"Si una palabra termina en z, la z cambia a c antes de -es: pez, peces.","hint":"Recuerda qué letra cambia cuando una palabra termina en z.","tags":["ocean"],"opts":["pezes","peses","peces"],"a":2},{"id":"pal-1-002","topic":"words","level":1,"type":"choice","q":"¿Qué artículo va con la palabra 'delfín'? ____ delfín nada en el mar.","why":"Delfín es masculino y está en singular: el delfín. 'La' y 'Las' son femeninos.","hint":"Es un solo delfín, y es masculino.","tags":["ocean"],"opts":["La","El","Las"],"a":1},{"id":"pal-1-003","topic":"words","level":1,"type":"choice","q":"'Bate' rima con 'pelota'.","why":"Bate termina en -ate y pelota termina en -ota. No suenan igual al final.","hint":"Compara los sonidos del final de cada palabra.","tags":["baseball"],"opts":["Verdadero","Falso"],"a":1},{"id":"pal-1-004","topic":"words","level":1,"type":"choice","q":"¿Cuál es el diminutivo de 'gato'?","why":"Los diminutivos terminan en -ito o -ita y dicen que algo es pequeño. 'Gatazo' es aumentativo.","hint":"Busca la palabra que nombra un gato pequeño.","tags":["animals"],"opts":["gatazo","gatito","gatuno"],"a":1},{"id":"pal-1-005","topic":"words","level":1,"type":"choice","q":"En 'ana juega béisbol en quito', ¿qué palabras llevan mayúscula?","why":"Los nombres propios, como Ana y Quito, llevan mayúscula. 'Béisbol' no es un nombre propio.","hint":"Mayúscula en los nombres de personas y lugares.","tags":["baseball"],"opts":["Ana y Quito","Solo Ana","Solo Quito","Béisbol y Quito"],"a":0},{"id":"pal-1-006","topic":"words","level":1,"type":"order","q":"Ordena las sílabas para formar el nombre de un animal del mar.","why":"Al unir ba-lle-na se forma 'ballena', un mamífero marino.","hint":"Es un animal enorme que sopla agua.","tags":["ocean"],"opts":["ba","lle","na"]},{"id":"pal-1-007","topic":"words","level":1,"type":"choice","q":"¿Cuál es la pregunta bien escrita?","why":"En español, las preguntas se abren con ¿ y se cierran con ?","hint":"Mira cómo empieza y cómo termina cada pregunta.","tags":[],"opts":["¿Cómo te llamas?","Cómo te llamas?","¿Cómo te llamas."],"a":0},{"id":"pal-1-008","topic":"words","level":1,"type":"choice","q":"¿Cuál palabra está bien escrita?","why":"Hormiga empieza con h muda y lleva g: hormiga.","hint":"Esta palabra empieza con una letra que no suena.","tags":["animals"],"opts":["hormiga","ormiga","hormija"],"a":0},{"id":"pal-1-009","topic":"words","level":1,"type":"number","q":"¿Cuántas sílabas tiene la palabra 'tiburón'?","why":"Se separa ti-bu-rón: tres sílabas, una por cada vocal.","hint":"Dila despacio y cuenta los golpes de voz.","tags":["sharks"],"a":3},{"id":"pal-1-010","topic":"words","level":1,"type":"choice","q":"¿Qué palabra rima con 'estrella'?","why":"Rimar es terminar con los mismos sonidos: es-tre-lla y bo-te-lla.","hint":"Fíjate en las últimas sílabas.","tags":["space"],"opts":["montaña","cometa","botella"],"a":2},{"id":"pal-2-001","topic":"words","level":2,"type":"choice","q":"Una ____ nos da leche. ¿Cómo se escribe el animal?","why":"'Vaca' es el animal que da leche. 'Baca' es el portaequipajes de un coche.","hint":"Piensa en el significado, no en el sonido.","tags":["animals"],"opts":["vaca","baca","vacca"],"a":0},{"id":"pal-2-002","topic":"words","level":2,"type":"choice","q":"Elige la forma correcta del pez cazador de dientes afilados.","why":"Tiburón se pronuncia más fuerte al final y termina en n, por eso lleva tilde.","hint":"Di la palabra: ¿en qué sílaba suena más fuerte?","tags":["sharks"],"opts":["tiburon","tiburón","tibúron"],"a":1},{"id":"pal-2-003","topic":"words","level":2,"type":"choice","q":"La palabra 'jirafa' se escribe con j.","why":"Jirafa se escribe con j: j-i-r-a-f-a.","hint":"Es un animal de cuello muy largo.","tags":["animals"],"opts":["Verdadero","Falso"],"a":0},{"id":"pal-2-004","topic":"words","level":2,"type":"choice","q":"¿Cuál es el plural de 'lápiz'?","why":"Si la palabra termina en z, cambia a c y añade -es: lápiz, lápices.","hint":"La z se transforma antes de -es.","tags":[],"opts":["lápizes","lápiz","lápices"],"a":2},{"id":"pal-2-005","topic":"words","level":2,"type":"choice","q":"Completa: Los dinosaurios ____ enormes.","why":"'Los dinosaurios' es plural, así que el verbo también debe ir en plural: eran.","hint":"El verbo debe concordar con 'los dinosaurios'.","tags":["dinosaurs"],"opts":["era","eres","eran"],"a":2},{"id":"pal-2-006","topic":"words","level":2,"type":"order","q":"Ordena alfabéticamente estos animales del mar.","why":"Orden alfabético: b, d, p, t. Se ordena por la primera letra.","hint":"Mira la primera letra de cada palabra.","tags":["ocean"],"opts":["ballena","delfín","pulpo","tiburón"]},{"id":"pal-2-007","topic":"words","level":2,"type":"choice","q":"¿Qué palabra rima con 'cohete'?","why":"Rimar es compartir los sonidos finales: cohete y juguete terminan en -ete.","hint":"Compara los últimos tres sonidos.","tags":["space"],"opts":["planeta","juguete","cometa"],"a":1},{"id":"pal-2-008","topic":"words","level":2,"type":"choice","q":"¿Cuál es el diminutivo de 'pelota'?","why":"El sufijo -ita indica pequeño. Pelotón y pelotera son otras palabras.","hint":"Busca el sufijo que significa pequeño.","tags":["baseball"],"opts":["pelotón","pelotita","pelotera"],"a":1},{"id":"pal-2-009","topic":"words","level":2,"type":"number","q":"¿Cuántas letras tiene la palabra 'delfín'?","why":"D-e-l-f-í-n: seis letras. La í con tilde sigue siendo una sola letra.","hint":"Deletrea la palabra y cuenta con los dedos.","tags":["ocean"],"a":6},{"id":"pal-2-010","topic":"words","level":2,"type":"choice","q":"¿Cuál exclamación está bien escrita?","why":"Las exclamaciones se abren con ¡ y se cierran con !","hint":"Mira el principio y el final de cada una.","tags":["baseball"],"opts":["¡Qué gran jonrón!","Qué gran jonrón!","¡Qué gran jonrón."],"a":0},{"id":"pal-3-001","topic":"words","level":3,"type":"choice","q":"Todos los días el tiburón ____ cerca de la costa. ¿Cuál es la forma correcta?","why":"Los verbos terminados en -aba llevan b y no llevan tilde: nadaba.","hint":"Recuerda la terminación del pasado de los verbos en -ar.","tags":["sharks"],"opts":["nadava","nadaba","nádaba","nadabá"],"a":1},{"id":"pal-3-002","topic":"words","level":3,"type":"choice","q":"¿Cómo se escribe un grupo de estrellas que forma un dibujo en el cielo?","why":"Las palabras terminadas en -ción llevan c y tilde en la o.","hint":"Piensa en la terminación -ción, que es una regla fija.","tags":["space"],"opts":["constelasión","constelación","constelacion","costelación"],"a":1},{"id":"pal-3-003","topic":"words","level":3,"type":"choice","q":"'Echo' es una forma del verbo hacer.","why":"Echo viene de echar (echo la pelota). La forma de hacer es 'hecho'.","hint":"Una de las dos lleva h.","tags":[],"opts":["Verdadero","Falso"],"a":1},{"id":"pal-3-004","topic":"words","level":3,"type":"choice","q":"____ muchos peces en el acuario. ¿Cuál palabra completa la oración?","why":"'Hay' (del verbo haber) dice que algo existe. 'Ahí' es un lugar y 'ay' expresa dolor o sorpresa.","hint":"¿Es existencia, lugar o queja?","tags":["ocean"],"opts":["Ahí","Ay","Hai","Hay"],"a":3},{"id":"pal-3-005","topic":"words","level":3,"type":"choice","q":"¿Cómo se escribe el movimiento de las olas del mar?","why":"Las palabras terminadas en -aje llevan j: oleaje, viaje, mensaje.","hint":"Recuerda el final: -aje.","tags":["ocean"],"opts":["oleage","oleáje","oleaxe","oleaje"],"a":3},{"id":"pal-3-006","topic":"words","level":3,"type":"order","q":"Ordena las sílabas para formar el nombre de quien viaja al espacio.","why":"As-tro-nau-ta: 'nau' tiene un diptongo, que cuenta como una sola sílaba.","hint":"Es quien viaja en cohete.","tags":["space"],"opts":["as","tro","nau","ta"]},{"id":"pal-3-007","topic":"words","level":3,"type":"choice","q":"Ayer el pelotero ____ la pelota muy lejos. ¿Qué forma del verbo lanzar encaja?","why":"'Ayer' indica pasado: lanzó. 'Lanza' es presente y 'lanzará', futuro.","hint":"Busca la palabra de tiempo: 'ayer'.","tags":["baseball"],"opts":["lanza","lanzará","lanzó","lanzaría"],"a":2},{"id":"pal-3-008","topic":"words","level":3,"type":"choice","q":"¿Cuál es el aumentativo de 'perro'?","why":"Los aumentativos como -azo o -ote indican algo grande. Perrito y perrillo son diminutivos.","hint":"Busca el sufijo que significa grande.","tags":["animals"],"opts":["perrazo","perrito","perrillo","perruno"],"a":0},{"id":"pal-3-009","topic":"words","level":3,"type":"number","q":"¿Cuántas sílabas tiene la palabra 'murciélago'?","why":"Mur-cié-la-go: 'ie' es un diptongo, así que 'cié' es una sola sílaba.","hint":"Las vocales juntas 'ie' suenan en un solo golpe.","tags":["animals"],"a":4},{"id":"pal-3-010","topic":"words","level":3,"type":"choice","q":"¿Cuál oración usa bien las comas?","why":"En una lista se separa con comas, pero no se pone coma antes de 'y'.","hint":"Separa cada animal con coma, menos el último.","tags":["ocean","sharks"],"opts":["Vi, tiburones delfines y ballenas.","Vi tiburones delfines, y ballenas.","Vi tiburones, delfines y ballenas.","Vi tiburones delfines y, ballenas."],"a":2},{"id":"pal-4-001","topic":"words","level":4,"type":"choice","q":"Un dinosaurio es un animal con columna vertebral, o sea, un ____. ¿Cómo se escribe?","why":"Vertebrado viene de vértebra. Las palabras de una misma familia conservan la v.","hint":"Piensa en la palabra 'vértebra'.","tags":["dinosaurs"],"opts":["bertebrado","vertebrado","vertevrado","vertébrado"],"a":1},{"id":"pal-4-002","topic":"words","level":4,"type":"choice","q":"Los dinosaurios nacían de un ____. ¿Cómo se escribe?","why":"Huevo empieza con hue- y lleva v. 'Hubo' es una forma del verbo haber.","hint":"Empieza con una letra muda.","tags":["dinosaurs"],"opts":["uevo","huebo","hubo","huevo"],"a":3},{"id":"pal-4-003","topic":"words","level":4,"type":"choice","q":"Todas las palabras agudas llevan tilde.","why":"Las agudas solo llevan tilde si terminan en n, s o vocal: canción sí, reloj no.","hint":"Compara 'canción' con 'reloj'.","tags":[],"opts":["Verdadero","Falso"],"a":1},{"id":"pal-4-004","topic":"words","level":4,"type":"choice","q":"¿Cuál palabra está bien acentuada?","why":"'Jonrón' es aguda (suena fuerte en -rón) y termina en n: lleva tilde.","hint":"Di la palabra: ¿en qué sílaba suena más fuerte?","tags":["baseball"],"opts":["jonron","jónron","jónrón","jonrón"],"a":3},{"id":"pal-4-005","topic":"words","level":4,"type":"choice","q":"____ qué descubrió hoy el buzo en el fondo del mar. ¿Cómo se escribe el inicio?","why":"'A ver' (preposición y verbo) expresa curiosidad. 'Haber' es el verbo de 'ha habido'.","hint":"Puedes cambiarlo por 'veamos'.","tags":["ocean"],"opts":["Haber","Ha ver","A ver","Aber"],"a":2},{"id":"pal-4-006","topic":"words","level":4,"type":"order","q":"Ordena alfabéticamente estos planetas.","why":"J, M, M, V. Entre Marte y Mercurio decide la segunda letra: a va antes que e.","hint":"Si la primera letra se repite, mira la segunda.","tags":["space"],"opts":["Júpiter","Marte","Mercurio","Venus"]},{"id":"pal-4-007","topic":"words","level":4,"type":"choice","q":"Mañana los astronautas ____ a la Luna. ¿Qué forma del verbo viajar encaja?","why":"'Mañana' indica futuro, así que el verbo va en futuro: viajarán.","hint":"Busca la palabra de tiempo: 'mañana'.","tags":["space"],"opts":["viajaron","viajaban","viajarán","han viajado"],"a":2},{"id":"pal-4-008","topic":"words","level":4,"type":"choice","q":"¿Qué palabra NO pertenece a la familia de 'mar'?","why":"Marino, marea y submarino vienen de 'mar'. Marfil viene del árabe y no se relaciona con el mar.","hint":"Pregúntate cuál no tiene nada que ver con el mar.","tags":["ocean"],"opts":["marfil","marino","marea","submarino"],"a":0,"fun":true},{"id":"pal-4-009","topic":"words","level":4,"type":"number","q":"¿Cuántas sílabas tiene la palabra 'constelación'?","why":"Cons-te-la-ción: 'ción' tiene un diptongo, así que es una sola sílaba.","hint":"Las vocales 'io' juntas suenan en un solo golpe.","tags":["space"],"a":4},{"id":"pal-4-010","topic":"words","level":4,"type":"choice","q":"En 'mañana viajamos a quito el miércoles', ¿qué palabras llevan mayúscula?","why":"Mayúscula al empezar y en nombres de ciudades. Los días de la semana van en minúscula.","hint":"¿Qué palabras son nombres propios o inician la oración?","tags":[],"opts":["Mañana y Quito","Mañana, Quito y Miércoles","Solo Quito","Quito y Miércoles"],"a":0},{"id":"pal-5-001","topic":"words","level":5,"type":"choice","q":"¿Cómo se escribe la ciencia que estudia las rocas y la historia de la Tierra?","why":"Geo- (tierra) y -logía (estudio) se escriben con g: geología, geografía, geometría.","hint":"Piensa en el prefijo que significa tierra.","tags":["space"],"opts":["jeología","geología","geolojía","jeolojía"],"a":1},{"id":"pal-5-002","topic":"words","level":5,"type":"choice","q":"¿Cuál oración usa bien la tilde diacrítica?","why":"'Tú' (pronombre) lleva tilde; 'tu' (posesivo) no: Tú tienes tu guante.","hint":"Un pronombre puede cambiarse por 'él' o 'ella'.","tags":["baseball"],"opts":["Tu tienes tu guante nuevo.","Tú tienes tu guante nuevo.","Tú tienes tú guante nuevo.","Tu tienes tú guante nuevo."],"a":1},{"id":"pal-5-003","topic":"words","level":5,"type":"choice","q":"En 'pingüino' la u lleva diéresis (ü) para que se pronuncie.","why":"Gue y gui suenan sin u (guitarra). Con ü se pronuncia: pingüino, cigüeña.","hint":"Compara 'guitarra' con 'pingüino'.","tags":["animals"],"opts":["Verdadero","Falso"],"a":0,"fun":true},{"id":"pal-5-004","topic":"words","level":5,"type":"choice","q":"Los ____ llevan agua dulce de las montañas hasta el mar. ¿Cuál palabra está bien escrita?","why":"La fuerza cae en la i (rí-os), así que se separa en dos sílabas y lleva tilde.","hint":"Di la palabra: ¿la fuerza cae en la i o en la o?","tags":[],"opts":["rios","riós","ríos","ríós"],"a":2},{"id":"pal-5-005","topic":"words","level":5,"type":"choice","q":"No era un tiburón, ____ una raya. ¿Cómo se escribe?","why":"'Sino' une una idea contraria después de una negación. 'Si no' expresa condición.","hint":"Hay una negación antes y una idea contraria después.","tags":["sharks","ocean"],"opts":["si no","sinó","sí no","sino"],"a":3},{"id":"pal-5-006","topic":"words","level":5,"type":"order","q":"Pon estas palabras en orden alfabético.","why":"Compara letra por letra: tib-, til-, tiz-, tor-.","hint":"Si dos palabras empiezan igual, mira la siguiente letra.","tags":["sharks"],"opts":["tiburón","tilde","tiza","tortuga"]},{"id":"pal-5-007","topic":"words","level":5,"type":"choice","q":"Ayer yo ____ un dibujo de un megalodón. ¿Qué forma del verbo hacer encaja?","why":"El pasado de 'hacer' es irregular: yo hice, tú hiciste, él hizo.","hint":"Conjuga 'hacer' con 'yo' en pasado.","tags":["sharks"],"opts":["hice","hací","hizo","hicé"],"a":0},{"id":"pal-5-008","topic":"words","level":5,"type":"choice","q":"¿Cuál de estos prefijos significa 'debajo de'?","why":"Sub- es debajo (submarino, subsuelo). Super- es encima, inter- es entre y trans- es a través.","hint":"Prueba cada prefijo con la palabra 'marino'.","tags":["ocean"],"opts":["sub-","super-","inter-","trans-"],"a":0},{"id":"pal-5-009","topic":"words","level":5,"type":"number","q":"¿Cuántas sílabas tiene la palabra 'electricidad'?","why":"E-lec-tri-ci-dad: cinco sílabas. En 'tri' hay tres letras pero una sola vocal.","hint":"Marca cada golpe de voz con un dedo.","tags":["machines"],"a":5},{"id":"pal-5-010","topic":"words","level":5,"type":"choice","q":"¿Cuál oración usa bien la coma del vocativo?","why":"El vocativo, la palabra con que llamamos a alguien, se separa con coma.","hint":"¿A quién le habla la oración?","tags":["baseball"],"opts":["Ana pásame el bate.","Ana pásame, el bate.","Ana, pásame, el bate.","Ana, pásame el bate."],"a":3},{"id":"pal-6-001","topic":"words","level":6,"type":"choice","q":"¿Cuál de estas palabras tiene un HIATO (dos vocales en sílabas distintas)?","why":"Po-e-ta tiene dos vocales abiertas juntas, que se separan. Puerta, cielo y causa tienen diptongo.","hint":"Un diptongo une una vocal abierta con una cerrada.","tags":[],"opts":["poeta","puerta","cielo","causa"],"a":0},{"id":"pal-6-002","topic":"words","level":6,"type":"choice","q":"Las palabras llanas llevan tilde cuando NO terminan en vocal, n ni s. ¿Cuál está bien escrita?","why":"Cráter es llana (CRÁ-ter) y termina en r: por eso lleva tilde.","hint":"Di la palabra: ¿en qué sílaba cae la fuerza?","tags":["space"],"opts":["crater","cratér","cráter","cráters"],"a":2},{"id":"pal-6-003","topic":"words","level":6,"type":"choice","q":"'Aun' sin tilde significa 'incluso' y 'aún' con tilde significa 'todavía'.","why":"Aún (todavía) lleva tilde: Aún no llegó. Aun (incluso) no: Aun así, lo intentó.","hint":"Prueba cambiarla por 'todavía' o por 'incluso'.","tags":[],"opts":["Verdadero","Falso"],"a":0},{"id":"pal-6-004","topic":"words","level":6,"type":"choice","q":"El barco navegaba ____ el puerto. ¿Cuál palabra completa la oración?","why":"'Hacia' indica dirección y no lleva tilde. 'Hacía' es del verbo hacer: hacía calor.","hint":"¿Indica dirección o es el verbo hacer?","tags":["ocean"],"opts":["hacía","hacia","asia","acia"],"a":1},{"id":"pal-6-005","topic":"words","level":6,"type":"choice","q":"¿Cómo se escribe el verbo que significa hacer una tela con hilos?","why":"Casi todos los verbos en -ger llevan g (proteger, escoger), pero tejer lleva j.","hint":"Casi todos los -ger llevan g; solo unos pocos son excepción.","tags":[],"opts":["teger","protejer","tejer","escojer"],"a":2},{"id":"pal-6-006","topic":"words","level":6,"type":"order","q":"Ordena estas cinco palabras por orden alfabético.","why":"Compara letra por letra: coh-, col-a, col-i, col-m, com-.","hint":"Si las primeras letras se repiten, compara las siguientes.","tags":["space"],"opts":["cohete","cola","colina","colmena","cometa"]},{"id":"pal-6-007","topic":"words","level":6,"type":"choice","q":"Si tuviera un telescopio, ____ los anillos de Saturno. ¿Qué forma del verbo ver encaja?","why":"Con 'si tuviera' (algo imaginado) se usa el condicional: vería.","hint":"Es algo que solo se imagina, no que ocurre.","tags":["space"],"opts":["veré","vería","he visto","veo"],"a":1},{"id":"pal-6-008","topic":"words","level":6,"type":"choice","q":"¿Cuál es el plural de 'paraguas'?","why":"Paraguas ya termina en -s y no es aguda: no cambia. Solo cambia el artículo.","hint":"Fíjate si cambia la palabra o solo el artículo.","tags":[],"opts":["los paraguases","las paraguas","los paragua","los paraguas"],"a":3},{"id":"pal-6-009","topic":"words","level":6,"type":"number","q":"¿Cuántas sílabas tiene la palabra 'paleontología'?","why":"Pa-le-on-to-lo-gí-a: 'e-o' y 'í-a' son hiatos; cada vocal queda en una sílaba distinta.","hint":"Dos vocales abiertas juntas, o una débil con tilde, se separan.","tags":["dinosaurs"],"a":7,"fun":true},{"id":"pal-6-010","topic":"words","level":6,"type":"choice","q":"Los científicos buscan el ____ de la extinción de los dinosaurios. ¿Cómo se escribe?","why":"Con 'el' delante es un sustantivo (la razón): 'el porqué', junto y con tilde.","hint":"Fíjate en la palabra 'el' que va delante.","tags":["dinosaurs"],"opts":["porqué","por qué","porque","por que"],"a":0},{"id":"log-es-1-001","topic":"logic","level":1,"type":"choice","q":"¿Qué sigue? 🦈 🦈 🐟 🦈 🦈 ❓","why":"El patrón es dos tiburones y un pez. Ya hay dos tiburones, así que sigue el pez.","hint":"Busca el grupo que se repite.","tags":["sharks","ocean"],"opts":["🐟","🦈","🐙"],"a":0},{"id":"log-es-1-002","topic":"logic","level":1,"type":"choice","q":"Tres de estos animales viven en el mar. ¿Cuál NO vive en el mar?","why":"El pulpo y la estrella de mar viven en el mar. La jirafa vive en la tierra.","hint":"Piensa dónde vive cada animal.","tags":["ocean"],"opts":["Pulpo","Jirafa","Estrella de mar"],"a":1},{"id":"log-es-1-003","topic":"logic","level":1,"type":"number","q":"🌙 ⭐ ⭐ 🌙 ⭐ ⭐ 🌙 ⭐ ⭐  ¿Cuántas ⭐ hay en la fila?","why":"Hay tres grupos de dos estrellas: 2 + 2 + 2 = 6. Las lunas no se cuentan.","hint":"Cuenta solo las estrellas, de dos en dos.","tags":["space"],"a":6},{"id":"log-es-1-004","topic":"logic","level":1,"type":"order","q":"Ordena estas pelotas de la más pequeña a la más grande.","why":"La de golf cabe en tu mano con espacio de sobra. La de béisbol es mayor, y la de básquetbol es la más grande.","hint":"Empieza con la que podrías esconder en el puño.","tags":["baseball"],"opts":["Pelota de golf","Pelota de béisbol","Pelota de básquetbol"]},{"id":"log-es-1-005","topic":"logic","level":1,"type":"choice","q":"¿Qué color sigue? 🟥 🟦 🟦 🟥 🟦 🟦 🟥 ❓","why":"El patrón es un rojo y dos azules. Después del rojo vienen dos azules, así que sigue un azul.","hint":"Fíjate cuántos azules van después de cada rojo.","tags":[],"opts":["🟦","🟥","🟩"],"a":0},{"id":"log-es-1-006","topic":"logic","level":1,"type":"choice","q":"Verdadero o falso: después de 🔺 🔺 🔵 🔺 🔺 🔵 sigue otro 🔵.","why":"El patrón es dos triángulos y un círculo. La fila terminó en círculo, así que sigue un triángulo.","hint":"Mira cómo terminó la fila.","tags":[],"opts":["Verdadero","Falso"],"a":1},{"id":"log-es-1-007","topic":"logic","level":1,"type":"number","q":"Cuenta de 5 en 5: 5, 10, ❓, 20. ¿Qué número falta?","why":"Cada número es 5 más que el anterior. Después de 10 sigue 15 y luego 20.","hint":"Suma 5 cada vez.","tags":[],"a":15},{"id":"log-es-1-008","topic":"logic","level":1,"type":"choice","q":"En un equipo de béisbol, Luna es más alta que Teo. Teo es más alto que Iván. ¿Quién es la persona más baja?","why":"Luna es la más alta, Teo queda en medio e Iván es el más bajo.","hint":"Ordénalos en una fila de alto a bajo.","tags":["baseball"],"opts":["Teo","Iván","Luna"],"a":1},{"id":"log-es-1-009","topic":"logic","level":1,"type":"choice","q":"🦖 🦖 🦈 🦖  ¿Qué lugar ocupa el intruso?","why":"Tres son dinosaurios y uno es tiburón. El tiburón está en el tercer lugar.","hint":"Busca el que es diferente y cuenta desde la izquierda.","tags":["dinosaurs","sharks"],"opts":["El 1.º","El 3.º","El 4.º"],"a":1},{"id":"log-es-1-010","topic":"logic","level":1,"type":"order","q":"Ordena lo que pasa con un cohete, del primer paso al último.","why":"Primero se cuenta hacia atrás, luego despega, viaja por el espacio y al final aterriza.","hint":"Piensa qué debe pasar antes de despegar.","tags":["space"],"opts":["Cuenta regresiva","Despegue","Viaje por el espacio","Aterrizaje"]},{"id":"log-es-1-011","topic":"logic","level":1,"type":"choice","q":"¿Qué número sigue? 2, 4, 2, 4, 2, ❓","why":"El patrón alterna 2 y 4. Como el último fue 2, sigue el 4.","hint":"Fíjate en el último número y en cuál le toca.","tags":[],"opts":["2","6","4"],"a":2},{"id":"log-es-1-012","topic":"logic","level":1,"type":"number","q":"En el mar hay 5 delfines. Llegan 3 delfines más. ¿Cuántos delfines hay ahora?","why":"5 y 3 más son 8: cuenta 6, 7, 8 desde el 5.","hint":"Empieza en 5 y cuenta 3 más.","tags":["ocean","animals"],"a":8},{"id":"log-es-2-001","topic":"logic","level":2,"type":"number","q":"Cuenta hacia atrás: 50, 45, 40, 35, ❓. ¿Qué número sigue?","why":"Cada número es 5 menos que el anterior. 35 menos 5 es 30.","hint":"Mira cuánto baja cada vez.","tags":[],"a":30},{"id":"log-es-2-002","topic":"logic","level":2,"type":"choice","q":"Un paleontólogo numera los huesos de un fósil: 7, 12, 17, 22, ❓. ¿Qué número sigue?","why":"Los números suben de 5 en 5. 22 más 5 es 27.","hint":"Resta dos números vecinos para ver el salto.","tags":["dinosaurs"],"opts":["27","26","29"],"a":0},{"id":"log-es-2-003","topic":"logic","level":2,"type":"choice","q":"El tiburón A muestra 28 dientes. El tiburón B muestra 82 dientes. ¿Cuál muestra MENOS dientes?","why":"28 tiene 2 decenas y 82 tiene 8 decenas. Menos decenas significa menos dientes.","hint":"Compara primero las decenas.","tags":["sharks"],"opts":["El tiburón A","Tienen la misma cantidad","El tiburón B"],"a":0},{"id":"log-es-2-004","topic":"logic","level":2,"type":"order","q":"Cuatro cohetes llevan estos números: 46, 64, 38 y 83. Ordénalos de mayor a menor.","why":"Compara las decenas: 8 es más que 6, 6 es más que 4 y 4 es más que 3. Entre 64 y 46 gana 64.","hint":"Busca primero el número más grande.","tags":["space"],"opts":["83","64","46","38"]},{"id":"log-es-2-005","topic":"logic","level":2,"type":"choice","q":"La caja azul tiene los números impares 3, 7 y 11. ¿Qué otro número va en la caja azul?","why":"Los impares terminan en 1, 3, 5, 7 o 9. El 15 termina en 5, así que es impar.","hint":"Fíjate en el último dígito.","tags":[],"opts":["14","15","18"],"a":1},{"id":"log-es-2-006","topic":"logic","level":2,"type":"choice","q":"Verdadero o falso: si cuentas de 2 en 2 (2, 4, 6, 8…), dirás el número 15.","why":"Contando de 2 en 2 solo dices números pares. El 15 es impar, así que nunca lo dices.","hint":"Piensa si 15 es par o impar.","tags":[],"opts":["Verdadero","Falso"],"a":1},{"id":"log-es-2-007","topic":"logic","level":2,"type":"number","q":"Los Tigres anotaron 8 carreras. Los Leones anotaron 3 menos que los Tigres. ¿Cuántas carreras anotaron los dos equipos juntos?","why":"Los Leones anotaron 8 − 3 = 5. Juntos suman 8 + 5 = 13 carreras.","hint":"Primero averigua cuántas anotaron los Leones.","tags":["baseball"],"a":13},{"id":"log-es-2-008","topic":"logic","level":2,"type":"choice","q":"Fila 1: ⭐ 🌙 ⭐. Fila 2: 🌙 ⭐ 🌙. Fila 3: ⭐ 🌙 ❓. ¿Qué va en el espacio vacío?","why":"Cada fila y cada columna alterna entre estrella y luna. Después de ⭐ 🌙 sigue ⭐.","hint":"Mira qué hay justo arriba del espacio vacío.","tags":["space"],"opts":["⭐","🌙","☀️"],"a":0},{"id":"log-es-2-009","topic":"logic","level":2,"type":"choice","q":"Contamos de 5 en 5: 5, 10, 15, 22, 25. ¿Qué número NO pertenece?","why":"Contando de 5 en 5 solo dices números que terminan en 0 o 5. El 22 termina en 2.","hint":"Revisa el último dígito de cada número.","tags":[],"opts":["10","25","22"],"a":2},{"id":"log-es-2-010","topic":"logic","level":2,"type":"order","q":"Ordena estos dinosaurios del más pequeño al más grande.","why":"El Compsognathus era como un pollo, el Velociraptor como un pavo. El Triceratops era enorme y el Braquiosaurio todavía más.","hint":"Piensa en cuál cabría en tus brazos.","tags":["dinosaurs"],"opts":["Compsognathus","Velociraptor","Triceratops","Braquiosaurio"],"fun":true},{"id":"log-es-2-011","topic":"logic","level":2,"type":"choice","q":"¿Qué número es MAYOR que 58 y MENOR que 61?","why":"59 viene después de 58 y antes de 60 y 61. El 57 y el 62 quedan fuera.","hint":"Cuenta desde 58 hacia arriba.","tags":[],"opts":["57","62","59"],"a":2},{"id":"log-es-2-012","topic":"logic","level":2,"type":"number","q":"Cada pulpo tiene 8 brazos. Hay 2 pulpos. ¿Cuántos brazos hay en total?","why":"8 + 8 = 16 brazos. Dos grupos de 8 hacen 16.","hint":"Suma los brazos de un pulpo con los del otro.","tags":["ocean","animals"],"a":16},{"id":"log-es-3-001","topic":"logic","level":3,"type":"choice","q":"Un robot en Marte recoge rocas: 3, 7, 11, 15. Si sigue el patrón, ¿cuántas rocas recoge el día 5?","why":"El patrón suma 4 cada día. 15 más 4 es 19.","hint":"Mira cuánto crece de un día al siguiente.","tags":["space"],"opts":["17","18","19","20"],"a":2},{"id":"log-es-3-002","topic":"logic","level":3,"type":"order","q":"Colmillo es más largo que Rayo. Tito es más corto que Rayo. Dientón es más largo que Colmillo. Ordena estos tiburones del más corto al más largo.","why":"Tito queda debajo de Rayo, Rayo debajo de Colmillo y Colmillo debajo de Dientón. Une las pistas.","hint":"Dibuja una línea y coloca un tiburón a la vez.","tags":["sharks"],"opts":["Tito","Rayo","Colmillo","Dientón"]},{"id":"log-es-3-003","topic":"logic","level":3,"type":"number","q":"Un pulpo guarda perlas en cajas: 5, 9, 13, 17 y así sigue. ¿Cuántas perlas hay en la caja 6?","why":"Cada caja tiene 4 perlas más. Después de 17 vienen 21 y luego 25.","hint":"Sigue sumando el mismo número, caja por caja.","tags":["ocean"],"a":25},{"id":"log-es-3-004","topic":"logic","level":3,"type":"choice","q":"Cada fila y cada columna tiene un 🚀, una 🪐 y un ☄️. Fila 1: 🚀 🪐 ☄️. Fila 2: ☄️ 🚀 🪐. Fila 3: 🪐 ❓ 🚀. ¿Qué va en ❓?","why":"La fila 3 ya tiene 🪐 y 🚀, así que falta ☄️. La columna 2 también lo pide.","hint":"¿Qué dibujo le falta a la fila 3?","tags":["space"],"opts":["🚀","🪐","⭐","☄️"],"a":3},{"id":"log-es-3-005","topic":"logic","level":3,"type":"number","q":"El patrón ⚾ 🧢 🧢 se repite una y otra vez. Entre los primeros 12 dibujos, ¿cuántos son 🧢?","why":"12 dibujos son 4 grupos de 3. Cada grupo tiene 2 gorras: 4 × 2 = 8.","hint":"Cuenta cuántos grupos completos caben.","tags":["baseball"],"a":8},{"id":"log-es-3-006","topic":"logic","level":3,"type":"choice","q":"En un desfile de dinosaurios, el Estegosaurio camina detrás del Triceratops. El T. rex camina delante del Triceratops. ¿Quién camina en medio?","why":"La fila es T. rex, Triceratops, Estegosaurio. El Triceratops queda entre los otros dos.","hint":"Pon los tres dinosaurios en una fila.","tags":["dinosaurs"],"opts":["T. rex","Estegosaurio","No se puede saber","Triceratops"],"a":3},{"id":"log-es-3-007","topic":"logic","level":3,"type":"choice","q":"Verdadero o falso: en el patrón 40, 35, 30, 25, el siguiente número es 15.","why":"Cada número baja 5. 25 menos 5 es 20, no 15.","hint":"Calcula cuánto baja cada número.","tags":[],"opts":["Verdadero","Falso"],"a":1},{"id":"log-es-3-008","topic":"logic","level":3,"type":"order","q":"Resuelve cada operación y ordena los resultados de menor a mayor.","why":"Los resultados son 11, 12, 14 y 16. Ordena las respuestas, no los primeros números.","hint":"Resuelve primero y compara después.","tags":[],"opts":["20 − 9","15 − 3","9 + 5","8 + 8"]},{"id":"log-es-3-009","topic":"logic","level":3,"type":"choice","q":"Contamos de 4 en 4: 4, 8, 12, 17, 20, 24. ¿Qué número es el error?","why":"Sumando 4 cada vez da 4, 8, 12, 16, 20, 24. El 17 debería ser 16.","hint":"Suma 4 a cada número y mira dónde falla.","tags":[],"opts":["17","8","20","24"],"a":0},{"id":"log-es-3-010","topic":"logic","level":3,"type":"number","q":"En una tabla, cada fila suma 20. Fila 1: 9, 6, 5. Fila 2: 8, ❓, 7. ¿Qué número es ❓?","why":"8 + 7 = 15. Para llegar a 20 faltan 5.","hint":"Primero suma los dos números que ves.","tags":[],"a":5},{"id":"log-es-3-011","topic":"logic","level":3,"type":"choice","q":"Tres de estos animales son mamíferos que respiran aire. ¿Cuál NO lo es?","why":"Delfines, ballenas y manatíes respiran aire. El tiburón ballena es un pez y respira con branquias.","hint":"Piensa cuáles son peces y cuáles no.","tags":["sharks","ocean"],"opts":["Delfín","Ballena jorobada","Manatí","Tiburón ballena"],"a":3,"fun":true},{"id":"log-es-3-012","topic":"logic","level":3,"type":"choice","q":"¿Qué número sigue? 1, 2, 4, 7, 11, ❓","why":"Los saltos crecen: +1, +2, +3, +4. El siguiente salto es +5, y 11 + 5 = 16.","hint":"Mira cuánto sube cada vez. ¿Es siempre igual?","tags":[],"opts":["15","16","17","18"],"a":1},{"id":"log-es-4-001","topic":"logic","level":4,"type":"number","q":"Número misterioso: es mayor que 40, menor que 60, y es múltiplo de 4 y también múltiplo de 6. ¿Cuál es?","why":"48 = 4 × 12 y 48 = 6 × 8. Entre 40 y 60 ningún otro número sirve para ambos.","hint":"Busca múltiplos de 6 y revisa cuáles también son de 4.","tags":[],"a":48},{"id":"log-es-4-002","topic":"logic","level":4,"type":"choice","q":"Lu vio 3 gaviotas en la playa y las 3 eran blancas. Dice: «Todas las gaviotas del mundo son blancas.» ¿Qué falla?","why":"Tres gaviotas no muestran cómo son todas. Puede haber otras de otro color.","hint":"¿Alcanzan 3 ejemplos para hablar de todas?","tags":["animals","ocean"],"opts":["Las gaviotas siempre son negras","Tres es un número imposible","Vio muy pocas para estar segura","No falla nada"],"a":2},{"id":"log-es-4-003","topic":"logic","level":4,"type":"number","q":"Un jugador de béisbol tiene un número de camiseta de dos dígitos. Sus dígitos suman 10 y el de las decenas es 4 más que el de las unidades. ¿Qué número es?","why":"Con 7 y 3: 7 + 3 = 10 y 7 es 4 más que 3. El número es 73.","hint":"Prueba parejas de dígitos que sumen 10.","tags":["baseball"],"a":73},{"id":"log-es-4-004","topic":"logic","level":4,"type":"choice","q":"Valeria, Mateo y Camila aman cosas distintas: tiburones, dinosaurios o planetas. Valeria no ama tiburones ni dinosaurios. Mateo no ama tiburones. ¿Quién ama los tiburones?","why":"Valeria ama los planetas. Mateo no ama tiburones, así que ama dinosaurios. A Camila le tocan los tiburones.","hint":"Empieza por quien tiene más pistas.","tags":["sharks","dinosaurs","space"],"opts":["Valeria","Mateo","Camila","No se puede saber"],"a":2},{"id":"log-es-4-005","topic":"logic","level":4,"type":"order","q":"Cuatro tortugas marinas corren. Nico llega último. Luz llega justo después de Ona. Mía llega antes que Ona. Ordénalas de la primera a la última.","why":"Nico es cuarto. Mía va antes que Ona, y Luz va justo después de Ona: Mía, Ona, Luz, Nico.","hint":"Coloca primero a la que tiene un lugar seguro.","tags":["ocean"],"opts":["Mía","Ona","Luz","Nico"]},{"id":"log-es-4-006","topic":"logic","level":4,"type":"number","q":"Un cangrejo camina de A a B solo hacia la derecha o hacia abajo. B está 1 paso a la derecha y 3 pasos hacia abajo. ¿Cuántos caminos cortos distintos puede tomar?","why":"El paso a la derecha puede ser el 1.º, 2.º, 3.º o 4.º. Hay 4 caminos.","hint":"¿En qué momento da el paso a la derecha?","tags":["ocean"],"a":4},{"id":"log-es-4-007","topic":"logic","level":4,"type":"choice","q":"Verdadero o falso: todos los jugadores del equipo Rojo usan casco. Pedro usa casco, así que juega en el equipo Rojo.","why":"Jugadores de otros equipos también usan casco. La regla va del equipo Rojo al casco, no al revés.","hint":"¿Solo el equipo Rojo usa casco?","tags":["baseball"],"opts":["Verdadero","Falso"],"a":1},{"id":"log-es-4-008","topic":"logic","level":4,"type":"choice","q":"¿Qué número cumple TODAS las pistas? Está entre 50 y 70. Es múltiplo de 5. Sus dígitos suman más de 10.","why":"Los múltiplos de 5 son 55, 60 y 65. Solo 6 + 5 = 11 suma más de 10.","hint":"Tacha números, una pista a la vez.","tags":[],"opts":["55","60","70","65"],"a":3},{"id":"log-es-4-009","topic":"logic","level":4,"type":"number","q":"Un cohete va de la Tierra a una estación y luego a la Luna. Hay 3 rutas hasta la estación y 4 desde ella hasta la Luna. ¿Cuántas rutas hay en total?","why":"Cada ruta de las 3 se combina con 4 rutas. 3 × 4 = 12.","hint":"Para cada primera ruta, cuenta las segundas.","tags":["space"],"a":12},{"id":"log-es-4-010","topic":"logic","level":4,"type":"choice","q":"Sofía dice: «7 + 5 = 13, porque 7 + 3 = 10 y 10 + 3 = 13.» ¿Dónde está su error?","why":"Para sumar 5 se usa 3 + 2. Entonces 7 + 3 = 10 y 10 + 2 = 12.","hint":"¿Cuánto falta después de sumar 3?","tags":[],"opts":["7 + 3 no es 10","Empezó con el número equivocado","No hay ningún error","Sumó 3 otra vez en lugar de 2"],"a":3},{"id":"log-es-4-011","topic":"logic","level":4,"type":"choice","q":"Hoy es martes. El cohete despega dentro de 12 días. ¿Qué día de la semana despega?","why":"Pasan 7 días y vuelve a ser martes. Faltan 5 días más: domingo.","hint":"Cuenta primero una semana completa.","tags":["space"],"opts":["Sábado","Domingo","Lunes","Viernes"],"a":1},{"id":"log-es-4-012","topic":"logic","level":4,"type":"number","q":"Hay 12 pelotas de béisbol repartidas en 3 cajas iguales. Luego se ponen 2 pelotas más en cada caja. ¿Cuántas pelotas hay ahora en cada caja?","why":"12 pelotas entre 3 cajas son 4 en cada una. Con 2 más, quedan 6.","hint":"Primero averigua cuántas había en cada caja.","tags":["baseball"],"a":6},{"id":"log-es-5-001","topic":"logic","level":5,"type":"choice","q":"Regla del entrenador: si hay tormenta, no hay práctica. Hoy SÍ hubo práctica. ¿Qué es seguro?","why":"Si hubiera habido tormenta, no habría práctica. Como hubo práctica, no hubo tormenta.","hint":"Prueba: ¿qué habría pasado con una tormenta?","tags":["baseball","weather"],"opts":["Hubo tormenta","No hubo tormenta","Hubo mucho sol","No se puede saber"],"a":1},{"id":"log-es-5-002","topic":"logic","level":5,"type":"number","q":"Una pelota de béisbol pesa lo mismo que 2 canicas grandes. Una canica grande pesa lo mismo que 3 canicas pequeñas. ¿Cuántas canicas pequeñas pesan lo mismo que 4 pelotas?","why":"Una pelota son 2 grandes, y cada grande son 3 pequeñas: 6 pequeñas. Cuatro pelotas: 4 × 6 = 24.","hint":"Convierte una pelota a canicas pequeñas primero.","tags":["baseball"],"a":24},{"id":"log-es-5-003","topic":"logic","level":5,"type":"choice","q":"Regla: si Lola termina la tarea, juega afuera. Lola está jugando afuera. ¿Terminó la tarea?","why":"La regla dice qué pasa si termina, no que sea la única razón para jugar afuera.","hint":"¿Puede haber otra razón para estar afuera?","tags":[],"opts":["No se puede saber","Sí, seguro","No, seguro que no","Terminó solo la mitad"],"a":0},{"id":"log-es-5-004","topic":"logic","level":5,"type":"order","q":"En una balanza, el meteorito A pesa menos que B. C pesa más que B. D pesa menos que A. Ordénalos del más liviano al más pesado.","why":"D es menor que A, A menor que B y B menor que C. Une las pistas en una sola fila.","hint":"Construye la fila con una pista a la vez.","tags":["space"],"opts":["D","A","B","C"]},{"id":"log-es-5-005","topic":"logic","level":5,"type":"choice","q":"¿Qué número sigue? 3, 6, 5, 10, 9, 18, ❓","why":"Los pasos se turnan: doblar y restar 1. El último paso fue doblar (9 a 18), así que ahora restamos 1: 17.","hint":"Dos pasos distintos se turnan.","tags":[],"opts":["16","17","19","36"],"a":1},{"id":"log-es-5-006","topic":"logic","level":5,"type":"number","q":"Pedro piensa un número, lo multiplica por 3 y luego le resta 4. Obtiene 17. ¿En qué número pensó?","why":"Deshaz los pasos al revés: 17 + 4 = 21, y 21 ÷ 3 = 7.","hint":"Deshaz el último paso primero.","tags":[],"a":7},{"id":"log-es-5-007","topic":"logic","level":5,"type":"choice","q":"Repetimos A B C A B C A B C… sin parar. ¿Qué letra queda en el lugar 20?","why":"El 18 termina en C porque es múltiplo de 3. Luego el 19 es A y el 20 es B.","hint":"Usa los múltiplos de 3 para acercarte al 20.","tags":[],"opts":["A","C","D","B"],"a":3},{"id":"log-es-5-008","topic":"logic","level":5,"type":"number","q":"En un club de 20 niños, 14 aman los tiburones y 9 aman el espacio. Todos aman al menos una de las dos cosas. ¿Cuántos aman SOLO los tiburones?","why":"14 + 9 = 23, que son 3 más que 20: esos 3 aman ambas. Solo tiburones: 14 − 3 = 11.","hint":"Averigua primero cuántos aman las dos cosas.","tags":["sharks","space"],"a":11},{"id":"log-es-5-009","topic":"logic","level":5,"type":"choice","q":"Verdadero o falso: en el patrón 2, 6, 4, 8, 6, 10 el siguiente número es 8.","why":"Los pasos se turnan: +4, −2, +4, −2, +4. Ahora toca −2: 10 − 2 = 8.","hint":"Fíjate en cómo cambian los números, uno por uno.","tags":[],"opts":["Verdadero","Falso"],"a":0},{"id":"log-es-5-010","topic":"logic","level":5,"type":"number","q":"Mía repartió sus cromos de dinosaurios: dio la mitad a Luis, luego 3 a Ana, y le quedaron 5. ¿Cuántos cromos tenía al principio?","why":"Al revés: 5 + 3 = 8 era lo que le quedó tras dar la mitad. Si 8 es la mitad, había 16.","hint":"Retrocede desde lo que le quedó.","tags":["dinosaurs"],"a":16},{"id":"log-es-5-011","topic":"logic","level":5,"type":"choice","q":"Un partido de béisbol empezó a la 1:50 p. m. y terminó a las 4:15 p. m. ¿Cuánto duró?","why":"De 1:50 a 2:00 son 10 min, hasta las 4:00 son 2 h, y hasta las 4:15 son 15 min más.","hint":"Salta de hora en hora, no de minuto en minuto.","tags":["baseball"],"opts":["2 h 15 min","2 h 35 min","3 h 25 min","2 h 25 min"],"a":3},{"id":"log-es-5-012","topic":"logic","level":5,"type":"number","q":"Tres conchas parecen iguales, pero una pesa más. Con una balanza de dos platillos, ¿cuántas veces debes pesar como mínimo para estar seguro de cuál es?","why":"Pesa dos conchas. Si una baja, es esa; si se equilibran, es la tercera. Basta una pesada.","hint":"¿Qué pasa si los dos platillos quedan parejos?","tags":["ocean"],"a":1,"fun":true},{"id":"log-es-6-001","topic":"logic","level":6,"type":"number","q":"Unas aletas y un snorkel cuestan $13 juntos. Las aletas cuestan $11 más que el snorkel. ¿Cuántos dólares cuesta el snorkel?","why":"Si el snorkel cuesta $1, las aletas cuestan $12: suman $13 y difieren en $11. Con $2 no funciona.","hint":"Prueba tu primera idea y comprueba las dos pistas.","tags":["ocean"],"a":1},{"id":"log-es-6-002","topic":"logic","level":6,"type":"choice","q":"Alma y Beto, dos tiburones de cuento, o siempre dicen la verdad o siempre mienten. Alma dice: «Beto miente.» Beto dice: «Los dos decimos la verdad.» ¿Quién dice la verdad?","why":"Si Beto dijera la verdad, Alma también, y entonces Beto mentiría. Imposible. Beto miente y Alma acierta.","hint":"Prueba suponer que Beto dice la verdad.","tags":["sharks"],"opts":["Los dos","Solo Beto","Ninguno de los dos","Solo Alma"],"a":3},{"id":"log-es-6-003","topic":"logic","level":6,"type":"number","q":"En un torneo de béisbol, 7 equipos juegan contra todos los demás exactamente una vez. ¿Cuántos partidos se juegan en total?","why":"Cada equipo juega 6 partidos: 7 × 6 = 42. Cada partido cuenta dos veces, así que 42 ÷ 2 = 21.","hint":"Cada partido involucra a dos equipos.","tags":["baseball"],"a":21},{"id":"log-es-6-004","topic":"logic","level":6,"type":"choice","q":"Tres cajas dicen «pelotas», «guantes» y «mezcla» (pelotas y guantes juntos). TODAS las etiquetas están mal. Sacas una pelota de la caja «mezcla». ¿Qué hay en la caja «guantes»?","why":"La caja «mezcla» tiene solo pelotas. La caja «guantes» no puede ser de guantes, así que es la mezcla.","hint":"Si la etiqueta está mal, ¿qué puede haber dentro?","tags":["baseball"],"opts":["Solo guantes","Solo pelotas","Una mezcla","No se puede saber"],"a":2,"fun":true},{"id":"log-es-6-005","topic":"logic","level":6,"type":"number","q":"En un dado normal, las caras opuestas suman 7. Ves tres caras: 1, 2 y 3. ¿Cuánto suman las tres caras que NO ves?","why":"Las caras ocultas son las opuestas: 6, 5 y 4. 6 + 5 + 4 = 15.","hint":"Halla la cara opuesta de cada número que ves.","tags":[],"a":15,"fun":true},{"id":"log-es-6-006","topic":"logic","level":6,"type":"order","q":"Cinco astronautas hacen fila para subir al cohete. Hugo va primero. Kai va último. Ian va justo detrás de Ela. Jade va antes que Ela. Ordénalos de primero a último.","why":"Hugo es 1.º y Kai 5.º. Jade debe ir antes que Ela, y Ian justo después: Jade, Ela, Ian.","hint":"Coloca primero los lugares seguros.","tags":["space"],"opts":["Hugo","Jade","Ela","Ian","Kai"]},{"id":"log-es-6-007","topic":"logic","level":6,"type":"choice","q":"Dos padres y dos hijos van a pescar. Cada persona pesca un pez, y en total pescan 3 peces. ¿Cuántas personas hay?","why":"Son abuelo, padre y nieto: el padre es padre e hijo a la vez. Así hay 2 padres y 2 hijos.","hint":"¿Puede una persona ser padre e hijo a la vez?","tags":["animals"],"opts":["2","3","4","5"],"a":1,"fun":true},{"id":"log-es-6-008","topic":"logic","level":6,"type":"number","q":"Un cangrejo sube una roca de 7 pasos. De día sube 3 pasos y de noche resbala 2. ¿En qué día llega a la cima?","why":"Cada día completo gana 1 paso. Tras 4 días está en el paso 4; el día 5 sube 3 y llega al 7.","hint":"Revisa qué pasa en el último día, sin resbalar.","tags":["ocean"],"a":5},{"id":"log-es-6-009","topic":"logic","level":6,"type":"choice","q":"Verdadero o falso: si hoy es domingo, dentro de 100 días será martes.","why":"100 días son 14 semanas completas más 2 días. Domingo más 2 días es martes.","hint":"Quita las semanas completas de 7 días.","tags":[],"opts":["Verdadero","Falso"],"a":0},{"id":"log-es-6-010","topic":"logic","level":6,"type":"number","q":"Tomás tiene el triple de la edad de su hermana Ana. Ana tiene 4 años. ¿Cuántos años tendrá Tomás cuando Ana tenga 10?","why":"Tomás tiene 12 y le lleva 8 años a Ana. Cuando ella tenga 10, él tendrá 18.","hint":"La diferencia de edad nunca cambia.","tags":[],"a":18},{"id":"log-es-6-011","topic":"logic","level":6,"type":"choice","q":"Un cubo de 3 × 3 × 3 cubitos se pinta de rojo por fuera y luego se separa en 27 cubitos. ¿Cuántos cubitos tienen exactamente 1 cara roja?","why":"Son los cubitos del centro de cada cara. El cubo tiene 6 caras, así que hay 6.","hint":"¿Cuáles tocan una sola cara del cubo?","tags":[],"opts":["6","8","12","24"],"a":0},{"id":"log-es-6-012","topic":"logic","level":6,"type":"choice","q":"¿Cuántos cuadrados de cualquier tamaño hay en una cuadrícula de 3 × 3 casillas, contando el grande?","why":"Hay 9 cuadrados pequeños, 4 de 2 × 2 y 1 grande: 9 + 4 + 1 = 14.","hint":"Cuenta por tamaños: pequeños, medianos y el grande.","tags":[],"opts":["9","13","14","16"],"a":2,"fun":true},{"id":"logB-1-001","topic":"logic","level":1,"type":"choice","q":"¿Qué sigue? 🐢 🐙 🦀 🐢 🐙 🦀 🐢 ❓","why":"El patrón se repite en grupos de tres: 🐢 🐙 🦀. Después de 🐢 siempre viene 🐙.","hint":"Busca el grupito que se repite.","tags":["ocean"],"opts":["🐙","🦀","🐢"],"a":0},{"id":"logB-1-002","topic":"logic","level":1,"type":"number","q":"Cada cangrejo tiene 2 pinzas. ¿Cuántas pinzas tienen 3 cangrejos?","why":"Suma las pinzas cangrejo por cangrejo: 2 + 2 + 2 = 6.","hint":"Suma las pinzas de un cangrejo a la vez.","tags":["ocean"],"a":6},{"id":"logB-1-003","topic":"logic","level":1,"type":"choice","q":"La Tierra, Marte y la Luna: ¿cuál NO es un planeta?","why":"La Luna da vueltas alrededor de la Tierra. Los planetas dan vueltas alrededor del Sol.","hint":"¿Cuál da vueltas alrededor de otro mundo?","tags":["space"],"opts":["La Luna","Marte","La Tierra"],"a":0},{"id":"logB-1-004","topic":"logic","level":1,"type":"order","q":"Ordena los números de los cohetes del menor al mayor.","why":"Al contar hacia arriba, el 2 va antes que el 5, luego el 7 y al final el 9.","hint":"Busca primero el número más pequeño.","tags":["space"],"opts":["2","5","7","9"]},{"id":"logB-1-005","topic":"logic","level":1,"type":"choice","q":"Verdadero o falso: en la cuenta regresiva 10, 9, 8, 7, el número que sigue es el 6.","why":"Contar hacia atrás es quitar uno cada vez, así que después del 7 viene el 6.","hint":"Quita uno cada vez.","tags":["space"],"opts":["Verdadero","Falso"],"a":0},{"id":"logB-1-006","topic":"logic","level":1,"type":"choice","q":"En la fila para entrar al submarino, Rosa va primera, Hugo segundo, Inés tercera y Dani cuarto. ¿Quién va justo detrás de Hugo?","why":"Justo detrás es el lugar que sigue. Después del segundo lugar viene el tercero, y ahí está Inés.","hint":"Busca a Hugo y mira un lugar más atrás.","tags":["ocean"],"opts":["Rosa","Dani","Inés"],"a":2},{"id":"logB-1-007","topic":"logic","level":1,"type":"choice","q":"Vivo en el mar. Tengo branquias, aletas y dientes afilados. ¿Qué soy?","why":"Las ballenas respiran aire y las gaviotas vuelan. Las branquias y las aletas son pistas de un pez como el tiburón.","hint":"¿Qué animal respira con branquias?","tags":["sharks","ocean"],"opts":["Una ballena","Un tiburón","Una gaviota"],"a":1},{"id":"logB-1-008","topic":"logic","level":1,"type":"number","q":"Cuenta de 3 en 3: 3, 6, 9, ❓. ¿Qué número sigue?","why":"Cada número es 3 más que el anterior. 9 + 3 = 12.","hint":"Suma 3 cada vez.","tags":[],"a":12},{"id":"logB-1-009","topic":"logic","level":1,"type":"choice","q":"¿Cuál es el número más grande: 27, 72 o 17?","why":"Mira primero las decenas. 7 decenas es más que 2 decenas o 1 decena.","hint":"Compara primero el dígito de las decenas.","tags":[],"opts":["17","27","72"],"a":2},{"id":"logB-1-010","topic":"logic","level":1,"type":"choice","q":"Verdadero o falso: 5 + 2 da el mismo resultado que 2 + 5.","why":"Puedes sumar en cualquier orden. De las dos maneras sale 7.","hint":"Prueba sumar de las dos formas.","tags":[],"opts":["Verdadero","Falso"],"a":0},{"id":"logB-1-011","topic":"logic","level":1,"type":"choice","q":"¿Qué sigue? 🧤 ⚾ 🧤 ⚾ 🧤 ❓","why":"El patrón es guante, pelota, guante, pelota. Después de un guante viene una pelota.","hint":"Di el patrón en voz alta.","tags":["baseball"],"opts":["🧢","⚾","🧤"],"a":1},{"id":"logB-1-012","topic":"logic","level":1,"type":"order","q":"Ordena las bases en el orden en que las toca un corredor, de la primera a la última.","why":"El corredor da la vuelta al diamante: primera, segunda, tercera y al final home.","hint":"Piensa por dónde sale y dónde termina un corredor.","tags":["baseball"],"opts":["Primera base","Segunda base","Tercera base","Home"]},{"id":"logB-1-013","topic":"logic","level":1,"type":"number","q":"Un tiburón ve 9 peces. 4 se van nadando. ¿Cuántos peces quedan?","why":"Quita 4 de 9. 9 − 4 = 5.","hint":"Cuenta hacia atrás 4 desde el 9.","tags":["sharks"],"a":5},{"id":"logB-1-014","topic":"logic","level":1,"type":"choice","q":"Estegosaurio, T. rex y ballena: ¿cuál NO es un dinosaurio?","why":"La ballena es un animal enorme del mar, pero es un mamífero, no un dinosaurio.","hint":"Piensa en cuál nunca caminó por la tierra con los dinosaurios.","tags":["dinosaurs"],"opts":["El estegosaurio","El T. rex","La ballena"],"a":2,"fun":true},{"id":"logB-1-015","topic":"logic","level":1,"type":"choice","q":"Si llueve, llevas paraguas. Está lloviendo. ¿Qué llevas?","why":"La regla dice que la lluvia significa paraguas, y como llueve, llevas el paraguas.","hint":"Usa la regla en el día de lluvia.","tags":["weather"],"opts":["Lentes de sol","Sandalias","Un paraguas"],"a":2},{"id":"logB-1-016","topic":"logic","level":1,"type":"choice","q":"Verdadero o falso: después del martes viene el jueves.","why":"En medio va el miércoles: martes, miércoles, jueves.","hint":"Di los días de la semana en orden.","tags":[],"opts":["Verdadero","Falso"],"a":1},{"id":"logB-1-017","topic":"logic","level":1,"type":"choice","q":"¿Qué fila sigue el MISMO patrón que 🔴 🔵 🔴 🔵?","why":"El patrón es A B A B. Solo la fila verde, amarillo, verde, amarillo lo cumple.","hint":"Compara cada dibujo con su lugar.","tags":[],"opts":["🟢 🟡 🟢 🟡","🟢 🟡 🟡 🟢","🟢 🟢 🟡 🟡"],"a":0},{"id":"logB-1-018","topic":"logic","level":1,"type":"number","q":"Un cohete tiene 10 asientos. Se sientan 6 astronautas. ¿Cuántos asientos quedan vacíos?","why":"10 − 6 = 4 asientos vacíos.","hint":"Cuenta desde el 6 hasta el 10.","tags":["space"],"a":4},{"id":"logB-1-019","topic":"logic","level":1,"type":"choice","q":"Bate, guante y tenedor: ¿cuál NO tiene que ver con el béisbol?","why":"El bate y el guante se usan para jugar béisbol. El tenedor es para comer.","hint":"Piensa en lo que ves en un juego de pelota.","tags":["baseball"],"opts":["El bate","El tenedor","El guante"],"a":1},{"id":"logB-1-020","topic":"logic","level":1,"type":"choice","q":"Tengo cara y dos manos, pero no puedo saludar. ¿Qué soy?","why":"Un reloj tiene cara y dos manecillas que señalan la hora, pero nunca saludan.","hint":"Piensa en cómo sabes la hora.","tags":[],"opts":["Un lápiz","Un reloj","Una almohada"],"a":1,"fun":true},{"id":"logB-2-001","topic":"logic","level":2,"type":"choice","q":"Un cohete suelta una pieza cada 4 minutos: 4, 8, 12, 16, ❓. ¿Qué número sigue?","why":"Cada número es 4 más que el anterior. 16 + 4 = 20.","hint":"Mira cuánto crece cada vez.","tags":["space"],"opts":["24","18","20"],"a":2},{"id":"logB-2-002","topic":"logic","level":2,"type":"number","q":"Un nido de dinosaurio tiene 5 huevos. ¿Cuántos huevos hay en 3 nidos?","why":"Suma los nidos: 5 + 5 + 5 = 15 huevos.","hint":"Suma 5 tres veces.","tags":["dinosaurs"],"a":15},{"id":"logB-2-003","topic":"logic","level":2,"type":"choice","q":"Piensa en el contorno de una pelota de béisbol. ¿Qué figura NO tiene esquinas?","why":"El círculo es redondo y no tiene esquinas. El cuadrado y el triángulo sí tienen.","hint":"Pasa el dedo alrededor de cada figura.","tags":["baseball"],"opts":["El círculo","El triángulo","El cuadrado"],"a":0},{"id":"logB-2-004","topic":"logic","level":2,"type":"order","q":"Ordena estos momentos de un día, empezando por la mañana.","why":"El Sol sale al amanecer, está alto al mediodía, se oculta al atardecer y el día termina a medianoche.","hint":"Sigue al Sol por el cielo.","tags":["space"],"opts":["Amanecer","Mediodía","Atardecer","Medianoche"]},{"id":"logB-2-005","topic":"logic","level":2,"type":"choice","q":"Verdadero o falso: 7 + 7 es mayor que 6 + 9.","why":"7 + 7 = 14, pero 6 + 9 = 15, así que 15 es mayor.","hint":"Calcula primero las dos sumas.","tags":[],"opts":["Verdadero","Falso"],"a":1},{"id":"logB-2-006","topic":"logic","level":2,"type":"choice","q":"Beto, Pía y Tina tienen cada uno una mascota distinta: un pez, un perro o un loro. La mascota de Beto tiene aletas. La de Pía tiene plumas. ¿Qué mascota tiene Tina?","why":"Las aletas son del pez de Beto. Las plumas son del loro de Pía. Solo queda el perro para Tina.","hint":"Asigna cada mascota a su dueño, una por una.","tags":["animals"],"opts":["Un pez","Un perro","Un loro"],"a":1},{"id":"logB-2-007","topic":"logic","level":2,"type":"choice","q":"Cuanto más sacas de mí, más grande me hago. ¿Qué soy?","why":"Cada palada de arena que sacas hace el hoyo más grande. La pila y el castillo se hacen más pequeños.","hint":"Imagina que cavas en la playa.","tags":["ocean"],"opts":["Una pila de arena","Un hoyo en la arena","Un castillo de arena"],"a":1,"fun":true},{"id":"logB-2-008","topic":"logic","level":2,"type":"number","q":"Soy 10 menos que 52. ¿Qué número soy?","why":"Restar 10 solo cambia las decenas: 52 se convierte en 42.","hint":"¿Qué dígito cambia al restar 10?","tags":[],"a":42},{"id":"logB-2-009","topic":"logic","level":2,"type":"choice","q":"Lanzador, receptor y arquero: ¿cuál NO es un puesto de un equipo de béisbol?","why":"El lanzador y el receptor trabajan juntos en el béisbol. Los arqueros cuidan la portería en otros deportes.","hint":"¿Quién cuida una portería?","tags":["baseball"],"opts":["Receptor","Arquero","Lanzador"],"a":1},{"id":"logB-2-010","topic":"logic","level":2,"type":"choice","q":"Verdadero o falso: todos los dinosaurios del parque comen plantas. Zeta es un dinosaurio del parque. Entonces Zeta come plantas.","why":"Si todos los dinosaurios del parque comen plantas, Zeta también tiene que comerlas.","hint":"Si es verdad para todos, es verdad para Zeta.","tags":["dinosaurs"],"opts":["Verdadero","Falso"],"a":0},{"id":"logB-2-011","topic":"logic","level":2,"type":"choice","q":"Un juego de béisbol empieza a las 2:00 y dura 3 horas. ¿A qué hora termina?","why":"Cuenta 3 horas desde las 2:00: las 3:00, las 4:00 y las 5:00.","hint":"Cuenta las horas una por una.","tags":["baseball"],"opts":["6:00","4:00","5:00"],"a":2},{"id":"logB-2-012","topic":"logic","level":2,"type":"number","q":"Un buzo ve 5 tiburones, 4 rayas y 3 tortugas. ¿Cuántos animales ve en total?","why":"5 + 4 = 9, y 9 + 3 = 12.","hint":"Suma dos números y luego suma el tercero.","tags":["sharks","ocean"],"a":12},{"id":"logB-2-013","topic":"logic","level":2,"type":"choice","q":"Si el lanzador tira 3 strikes, el bateador queda ponchado. Tito quedó ponchado. ¿Qué lanzó el lanzador?","why":"Tres strikes son un ponche. Con tres bolas el bateador seguiría jugando.","hint":"Usa la regla al revés.","tags":["baseball"],"opts":["Tres strikes","Tres bolas","Tres jonrones"],"a":0},{"id":"logB-2-014","topic":"logic","level":2,"type":"choice","q":"Un tiburón nada arriba de una tortuga. La tortuga nada arriba de un cangrejo. El cangrejo está arriba de una estrella de mar. ¿Qué animal está más abajo?","why":"De arriba hacia abajo van el tiburón, la tortuga, el cangrejo y la estrella de mar.","hint":"Ponlos en una columna, de arriba hacia abajo.","tags":["ocean"],"opts":["La estrella de mar","La tortuga","El cangrejo"],"a":0},{"id":"logB-2-015","topic":"logic","level":2,"type":"choice","q":"Verdadero o falso: el patrón 1, 2, 4, 8 suma siempre el mismo número.","why":"Suma 1, luego 2, luego 4. Los números se duplican, no crecen siempre lo mismo.","hint":"Mira cuánto crece cada paso.","tags":[],"opts":["Verdadero","Falso"],"a":1},{"id":"logB-2-016","topic":"logic","level":2,"type":"choice","q":"El patrón ⚾ 🧤 🧤 se repite sin parar. ¿Qué dibujo es el 7.º?","why":"La pelota ⚾ cae en los lugares 1, 4, 7 y así sigue. El lugar 7 es una ⚾.","hint":"Escribe el patrón hasta llegar al 7.","tags":["baseball"],"opts":["🧤","⚾","🧢"],"a":1},{"id":"logB-2-017","topic":"logic","level":2,"type":"number","q":"Un helado cuesta 3 dólares. Pía compra 2 helados y paga con un billete de 10 dólares. ¿Cuántos dólares le devuelven?","why":"2 helados cuestan 6 dólares. 10 − 6 = 4 dólares de vuelto.","hint":"Primero calcula cuánto cuesta todo.","tags":["money","food"],"a":4},{"id":"logB-2-018","topic":"logic","level":2,"type":"choice","q":"¿Qué pesa más: un kilo de piedras o un kilo de plumas?","why":"¡Un kilo es un kilo! Las plumas solo ocupan mucho más espacio.","hint":"Lee cuánto hay de cada cosa.","tags":[],"opts":["Las piedras","Las plumas","Pesan lo mismo"],"a":2,"fun":true},{"id":"logB-2-019","topic":"logic","level":2,"type":"choice","q":"Tomás, Ula y Vera usan gorras de béisbol de colores distintos: roja, azul o verde. Tomás usa la roja. Ula no usa la azul. ¿De qué color es la gorra de Vera?","why":"Tomás tiene la roja. Ula no puede tener la azul, así que tiene la verde. A Vera le queda la azul.","hint":"Empieza por el color que Ula no puede usar.","tags":["baseball"],"opts":["Roja","Verde","Azul"],"a":2},{"id":"logB-2-020","topic":"logic","level":2,"type":"number","q":"Hoy es lunes. El robot lunar aterriza el viernes. ¿Cuántos días faltan desde hoy?","why":"Cuenta hacia adelante: martes 1, miércoles 2, jueves 3, viernes 4.","hint":"Cuenta los días uno por uno.","tags":["space"],"a":4},{"id":"logB-3-001","topic":"logic","level":3,"type":"choice","q":"Una cuenta regresiva baja de 3 en 3: 30, 27, 24, 21, ❓. ¿Qué número sigue?","why":"Cada paso quita 3. 21 − 3 = 18.","hint":"Resta lo mismo en cada paso.","tags":["space"],"opts":["18","17","15","19"],"a":0},{"id":"logB-3-002","topic":"logic","level":3,"type":"number","q":"Un acuario tiene 3 filas de peceras con 6 peces en cada fila. ¿Cuántos peces hay en total?","why":"Tres filas de 6 son 6 + 6 + 6 = 18.","hint":"Suma las filas, o cuenta de 6 en 6.","tags":["ocean"],"a":18},{"id":"logB-3-003","topic":"logic","level":3,"type":"choice","q":"Verdadero o falso: al sumar un número par y un número impar, el resultado siempre es impar.","why":"Prueba con 2 + 3 = 5 y 4 + 7 = 11. El par se junta en parejas y el impar deja uno suelto.","hint":"Prueba con varios ejemplos.","tags":[],"opts":["Verdadero","Falso"],"a":0,"fun":true},{"id":"logB-3-004","topic":"logic","level":3,"type":"choice","q":"Ela, Fito y Gael quedaron primero, segundo y tercero en un concurso de dinosaurios. Ela le ganó a Fito. Gael le ganó a Ela. ¿Quién quedó en segundo lugar?","why":"Gael le ganó a Ela, y Ela le ganó a Fito. El orden es Gael, Ela, Fito.","hint":"Pon las pistas en una línea, del mejor al peor.","tags":["dinosaurs"],"opts":["Fito","Gael","Ela","No se puede saber"],"a":2},{"id":"logB-3-005","topic":"logic","level":3,"type":"order","q":"Cuatro tiburones bebé salen de una cueva. Ema sale antes que Fer. Gil sale después de Fer. Hugo sale antes que Ema. Ordénalos del primero al último.","why":"Hugo va antes que Ema, Ema antes que Fer y Fer antes que Gil.","hint":"Encuentra a quien sale antes que todos.","tags":["sharks","ocean"],"opts":["Hugo","Ema","Fer","Gil"]},{"id":"logB-3-006","topic":"logic","level":3,"type":"choice","q":"Contamos de 7 en 7: 7, 14, 21, 28, 35. ¿Cuál de estos números NO se dice al contar de 7 en 7?","why":"Después del 35 se dice 42 y luego 49. El 45 se salta.","hint":"Sigue contando de 7 en 7 hasta pasar cada número.","tags":[],"opts":["14","45","28","35"],"a":1},{"id":"logB-3-007","topic":"logic","level":3,"type":"number","q":"Un lanzador tira 14 lanzamientos en la primera entrada y 11 en la segunda. Puede tirar 40 en total. ¿Cuántos lanzamientos más puede tirar?","why":"14 + 11 = 25 lanzamientos hasta ahora. 40 − 25 = 15.","hint":"Suma lo que lanzó y réstalo de 40.","tags":["baseball"],"a":15},{"id":"logB-3-008","topic":"logic","level":3,"type":"choice","q":"Una tira de papel se dobla por la mitad tres veces seguidas. Al abrirla, ¿cuántas partes iguales ves?","why":"Cada doblez duplica las partes: 2, luego 4, luego 8.","hint":"Cada doblez parte cada trozo en dos.","tags":[],"opts":["4","6","3","8"],"a":3},{"id":"logB-3-009","topic":"logic","level":3,"type":"choice","q":"Si un astronauta termina su trabajo, sube a la nave. Si sube a la nave, se abrocha el cinturón. Zoe terminó su trabajo. ¿Qué hace?","why":"Terminar lleva a subir a la nave, y subir lleva a abrocharse el cinturón. Sigue la cadena paso a paso.","hint":"Sigue la cadena de «si» uno por uno.","tags":["space"],"opts":["Se queda fuera de la nave","Apaga las luces del cohete","Se abrocha el cinturón","Empieza el trabajo otra vez"],"a":2},{"id":"logB-3-010","topic":"logic","level":3,"type":"choice","q":"Verdadero o falso: todos los rectángulos son cuadrados.","why":"Un rectángulo puede tener lados largos y cortos. Solo el rectángulo con los 4 lados iguales es un cuadrado.","hint":"Dibuja un rectángulo largo y angosto.","tags":[],"opts":["Verdadero","Falso"],"a":1},{"id":"logB-3-011","topic":"logic","level":3,"type":"number","q":"Piensa un número, súmale 3 y luego duplica el resultado. Obtienes 18. ¿Qué número pensaste?","why":"Ve hacia atrás: la mitad de 18 es 9, y 9 − 3 = 6.","hint":"Deshaz los pasos en orden inverso.","tags":[],"a":6},{"id":"logB-3-012","topic":"logic","level":3,"type":"choice","q":"En una caja hay 4 pelotas de béisbol, 1 de tenis y 2 de golf. Sacas una sin mirar. ¿Cuál es más probable que saques?","why":"Hay más pelotas de béisbol que de cualquier otro tipo, así que es la más probable.","hint":"¿Cuál grupo tiene más pelotas?","tags":["baseball"],"opts":["Todas son igual de probables","Una de tenis","Una de golf","Una de béisbol"],"a":3},{"id":"logB-3-013","topic":"logic","level":3,"type":"choice","q":"Hoy es sábado. Un cometa se verá muy bien dentro de 10 días. ¿Qué día de la semana será?","why":"7 días después del sábado es otro sábado. Faltan 3 días más: domingo, lunes y martes.","hint":"Quita primero una semana completa.","tags":["space"],"opts":["Domingo","Martes","Miércoles","Lunes"],"a":1},{"id":"logB-3-014","topic":"logic","level":3,"type":"number","q":"Un cangrejo da 2 pasos hacia adelante y 1 paso hacia atrás, y repite esto 3 veces. ¿A cuántos pasos de donde empezó queda?","why":"Cada repetición lo deja 1 paso más adelante. Después de 3 repeticiones está a 3 pasos.","hint":"¿Cuánto avanza en cada repetición?","tags":["ocean"],"a":3},{"id":"logB-3-015","topic":"logic","level":3,"type":"choice","q":"Verdadero o falso: todos los T. rex tenían dientes afilados. Este animal tiene dientes afilados. Entonces es un T. rex.","why":"Muchos animales tienen dientes afilados, como los tiburones y los leones. Eso no basta para ser un T. rex.","hint":"¿Otro animal podría tener dientes afilados?","tags":["dinosaurs"],"opts":["Verdadero","Falso"],"a":1},{"id":"logB-3-016","topic":"logic","level":3,"type":"choice","q":"En una clave secreta, A = 1, B = 2, C = 3 y D = 4. Suma las letras de la palabra DADA. ¿Cuánto da?","why":"D vale 4 y A vale 1: 4 + 1 + 4 + 1 = 10.","hint":"Cambia cada letra por su número.","tags":[],"opts":["11","9","8","10"],"a":3,"fun":true},{"id":"logB-3-017","topic":"logic","level":3,"type":"number","q":"Zoe tiene 3 monedas de 25 centavos y 2 monedas de 10 centavos. ¿Cuántos centavos tiene en total?","why":"3 monedas de 25 son 75 centavos y 2 de 10 son 20. 75 + 20 = 95.","hint":"Suma primero las de 25 y luego las de 10.","tags":["money"],"a":95},{"id":"logB-3-018","topic":"logic","level":3,"type":"choice","q":"Saltando una letra cada vez: B, D, F, H, ❓. ¿Qué letra sigue?","why":"El patrón salta una letra: B (C), D (E), F (G), H (I) y llega a J.","hint":"Di el abecedario y salta una letra.","tags":[],"opts":["J","I","L","K"],"a":0},{"id":"logB-3-019","topic":"logic","level":3,"type":"order","q":"Cuatro naves despegan a las 8:15, 7:50, 8:05 y 7:35. Ordena las horas de la más temprana a la más tarde.","why":"Primero van las 7:35 y las 7:50, y después las 8:05 y las 8:15.","hint":"Compara primero la hora y luego los minutos.","tags":["space"],"opts":["7:35","7:50","8:05","8:15"]},{"id":"logB-3-020","topic":"logic","level":3,"type":"number","q":"Un acuario tiene 16 peces. La mitad son naranjas. De los naranjas, la mitad tiene manchas. ¿Cuántos peces naranjas tienen manchas?","why":"La mitad de 16 es 8 peces naranjas. La mitad de 8 es 4 con manchas.","hint":"Parte el grupo por la mitad dos veces.","tags":["ocean"],"a":4},{"id":"logB-4-001","topic":"logic","level":4,"type":"number","q":"Un submarino robot baja 4 metros cada minuto. ¿A cuántos metros de profundidad está después de 7 minutos?","why":"4 metros por minuto durante 7 minutos son 4 × 7 = 28 metros.","hint":"Cuenta de 4 en 4 siete veces.","tags":["ocean"],"a":28},{"id":"logB-4-002","topic":"logic","level":4,"type":"choice","q":"Cada noche un astrónomo cuenta el doble de estrellas que la noche anterior: 4, 8, 16, 32, ❓. ¿Qué número sigue?","why":"Cada número es el doble del anterior. El doble de 32 es 64. Sumar 16 otra vez daría 48.","hint":"Compara cada número con el anterior.","tags":["space"],"opts":["40","48","64","36"],"a":2},{"id":"logB-4-003","topic":"logic","level":4,"type":"choice","q":"Ari, Beni y Cleo juegan de campocorto, lanzador y receptor. Ari no es el lanzador. Beni no es lanzador ni receptor. ¿Quién es el receptor?","why":"Beni tiene que ser el campocorto. Ari no lanza, así que es el receptor y Cleo lanza.","hint":"Ubica primero a Beni.","tags":["baseball"],"opts":["No se puede saber","Cleo","Ari","Beni"],"a":2},{"id":"logB-4-004","topic":"logic","level":4,"type":"choice","q":"Verdadero o falso: todo múltiplo de 6 es también múltiplo de 3.","why":"6 es 3 + 3, así que cualquier número formado por grupos de 6 también se forma con grupos de 3.","hint":"Prueba con 12, 18 y 24.","tags":[],"opts":["Verdadero","Falso"],"a":0},{"id":"logB-4-005","topic":"logic","level":4,"type":"order","q":"Se miden cuatro dinosaurios bebé. Ordena sus longitudes de la más corta a la más larga.","why":"1 m son 100 cm. Entonces el orden es 70 cm, 100 cm, 130 cm y 200 cm.","hint":"Pasa todas las medidas a centímetros.","tags":["dinosaurs"],"opts":["70 cm","1 m","1 m 30 cm","2 m"]},{"id":"logB-4-006","topic":"logic","level":4,"type":"choice","q":"Tres de estos números son un número multiplicado por sí mismo (como 3 × 3 = 9). ¿Cuál NO lo es?","why":"16 = 4 × 4, 49 = 7 × 7 y 81 = 9 × 9. Ningún número multiplicado por sí mismo da 28.","hint":"Prueba 5 × 5 y 6 × 6.","tags":[],"opts":["49","16","81","28"],"a":3},{"id":"logB-4-007","topic":"logic","level":4,"type":"number","q":"En el estadio, un perro caliente cuesta 4 dólares y un refresco cuesta 2. Una familia compra 3 perros calientes y 3 refrescos. ¿Cuántos dólares pagan?","why":"3 perros calientes cuestan 12 dólares y 3 refrescos cuestan 6. 12 + 6 = 18.","hint":"Calcula cada tipo por separado y luego suma.","tags":["baseball","money"],"a":18},{"id":"logB-4-008","topic":"logic","level":4,"type":"choice","q":"Todas las ballenas respiran aire. Algunos animales del acuario son ballenas. ¿Qué frase TIENE que ser verdadera?","why":"Los animales del acuario que son ballenas respiran aire. De los demás no sabemos nada, así que solo «algunos» es seguro.","hint":"Sigue a las ballenas por las dos frases.","tags":["ocean"],"opts":["Algunos animales del acuario respiran aire","Todo animal que respira aire es una ballena","Ningún animal del acuario respira aire","Todos los animales del acuario respiran aire"],"a":0},{"id":"logB-4-009","topic":"logic","level":4,"type":"number","q":"El día 1, un equipo de excavación tiene una pila de 5 fósiles. Cada día la pila crece 4 fósiles. ¿Cuántos fósiles hay el día 6?","why":"El día 1 hay 5. Faltan 5 días más, que suman 5 × 4 = 20. Entonces 5 + 20 = 25.","hint":"Cuenta cuántos saltos de 4 hay.","tags":["dinosaurs"],"a":25},{"id":"logB-4-010","topic":"logic","level":4,"type":"choice","q":"Verdadero o falso: si hoy es martes, dentro de 21 días también será martes.","why":"21 días son exactamente 3 semanas, y los días de la semana se repiten cada 7 días.","hint":"¿Cuántas semanas hay en 21 días?","tags":[],"opts":["Verdadero","Falso"],"a":0},{"id":"logB-4-011","topic":"logic","level":4,"type":"choice","q":"Un barco apunta al este. Da un cuarto de vuelta a la izquierda y luego otro cuarto de vuelta a la izquierda. ¿Hacia dónde apunta ahora?","why":"Desde el este, un giro a la izquierda apunta al norte. Otro giro a la izquierda apunta al oeste.","hint":"Gira a la izquierda dos veces, paso a paso.","tags":["ocean","maps"],"opts":["Al norte","Al este","Al sur","Al oeste"],"a":3},{"id":"logB-4-012","topic":"logic","level":4,"type":"choice","q":"¿Qué par de números suma 30 y tiene una diferencia de 6?","why":"18 + 12 = 30 y 18 − 12 = 6. Los otros pares suman 30, pero sus diferencias son 0, 10 y 4.","hint":"Revisa la suma Y la diferencia.","tags":[],"opts":["15 y 15","18 y 12","17 y 13","20 y 10"],"a":1},{"id":"logB-4-013","topic":"logic","level":4,"type":"number","q":"Una cuerda de 15 metros se corta en trozos de 3 metros. ¿Cuántos cortes hay que hacer?","why":"15 ÷ 3 = 5 trozos. El último trozo no necesita corte, así que bastan 4 cortes.","hint":"Dibuja la cuerda y marca los cortes.","tags":[],"a":4,"fun":true},{"id":"logB-4-014","topic":"logic","level":4,"type":"choice","q":"Verdadero o falso: «Algunos dinosaurios comían plantas» quiere decir que TODOS los dinosaurios comían plantas.","why":"«Algunos» significa solo unos cuantos. Muchos dinosaurios, como el T. rex, comían carne.","hint":"¿«Algunos» es lo mismo que «todos»?","tags":["dinosaurs"],"opts":["Verdadero","Falso"],"a":1},{"id":"logB-4-015","topic":"logic","level":4,"type":"choice","q":"Una máquina espacial convierte el 1 en 4, el 2 en 7 y el 3 en 10. ¿En qué número convierte el 6?","why":"La regla es multiplicar por 3 y sumar 1. 6 × 3 = 18, y 18 + 1 = 19.","hint":"Mira qué le pasa al 1 para llegar al 4.","tags":["space"],"opts":["18","19","16","22"],"a":1},{"id":"logB-4-016","topic":"logic","level":4,"type":"choice","q":"Mía tiene el triple de conchas que Juan. Juntos tienen 24 conchas. ¿Cuántas conchas tiene Mía?","why":"Juan tiene 6 y Mía tiene 18. Suman 24, y 18 es el triple de 6.","hint":"Prueba con que Juan tiene 6 conchas.","tags":["ocean"],"opts":["18","12","16","8"],"a":0},{"id":"logB-4-017","topic":"logic","level":4,"type":"number","q":"En el béisbol, el turno de bateo de un equipo termina con 3 outs. Un equipo batea una vez en cada una de las 9 entradas. ¿Cuántos outs son en total?","why":"3 outs en cada una de 9 entradas son 3 × 9 = 27 outs.","hint":"Multiplica los outs por las entradas.","tags":["baseball"],"a":27,"fun":true},{"id":"logB-4-018","topic":"logic","level":4,"type":"choice","q":"Beto dice: «Pasado mañana será domingo.» ¿Qué día es hoy?","why":"Si pasado mañana es domingo, mañana es sábado, y hoy es viernes.","hint":"Ve hacia atrás desde el domingo.","tags":[],"opts":["Lunes","Jueves","Viernes","Sábado"],"a":2},{"id":"logB-4-019","topic":"logic","level":4,"type":"order","q":"Ordena estas cantidades de dinero de la menor a la mayor.","why":"Valen 10, 25, 30 y 100 centavos. Un dólar son 100 centavos.","hint":"Calcula cuántos centavos vale cada grupo.","tags":["money"],"opts":["2 monedas de 5 centavos","1 moneda de 25 centavos","3 monedas de 10 centavos","1 billete de 1 dólar"]},{"id":"logB-4-020","topic":"logic","level":4,"type":"choice","q":"Enero, marzo, mayo, ❓. ¿Qué mes sigue en este patrón?","why":"El patrón salta un mes cada vez. Después de mayo, se salta junio y sigue julio.","hint":"Mira cuántos meses salta cada vez.","tags":[],"opts":["Junio","Abril","Agosto","Julio"],"a":3},{"id":"logB-5-001","topic":"logic","level":5,"type":"number","q":"Dani gasta la mitad de su dinero en un tiburón de juguete. Luego gasta un tercio de lo que le queda en una merienda. Le quedan 4 dólares. ¿Con cuántos dólares empezó?","why":"Ve hacia atrás: 4 es dos tercios de lo que quedó, así que quedaban 6. Eso era la mitad de su dinero, o sea 12.","hint":"Deshaz primero la merienda y luego el juguete.","tags":["sharks","money"],"a":12},{"id":"logB-5-002","topic":"logic","level":5,"type":"choice","q":"Todos los peces del estanque son plateados. Ningún animal plateado del estanque come algas. ¿Qué frase TIENE que ser verdadera?","why":"Los peces son plateados, y los plateados no comen algas. Entonces ningún pez las come. Otros animales podrían no comerlas tampoco.","hint":"Une peces con plateados y plateados con algas.","tags":["ocean"],"opts":["Todos los peces del estanque comen algas","Todo lo que no come algas es pez","Todos los animales del estanque son plateados","Ningún pez del estanque come algas"],"a":3},{"id":"logB-5-003","topic":"logic","level":5,"type":"choice","q":"Verdadero o falso: todos los múltiplos de 10 son pares, así que todos los números pares son múltiplos de 10.","why":"La primera parte es cierta. Pero 4 es par y no es múltiplo de 10, así que la segunda parte falla.","hint":"Prueba con el número par 4.","tags":[],"opts":["Verdadero","Falso"],"a":1},{"id":"logB-5-004","topic":"logic","level":5,"type":"number","q":"El cohete A despega cada 6 días y el cohete B cada 9 días. Hoy despegan los dos. ¿Dentro de cuántos días volverán a despegar el mismo día?","why":"A despega los días 6, 12, 18 y B los días 9, 18. El primer día en las dos listas es el 18.","hint":"Escribe los días de despegue de cada cohete.","tags":["space"],"a":18},{"id":"logB-5-005","topic":"logic","level":5,"type":"order","q":"Cinco tortugas marinas llegan al mar. Eva llega primero. Dani llega justo después de Eva. Ana llega antes que Cris. Beto llega último. Ordénalas de la primera a la última.","why":"Eva y Dani ocupan los dos primeros lugares y Beto el último. En medio, Ana va antes que Cris.","hint":"Coloca primero a Eva y a Beto.","tags":["ocean"],"opts":["Eva","Dani","Ana","Cris","Beto"]},{"id":"logB-5-006","topic":"logic","level":5,"type":"choice","q":"Mira este patrón: 1, 4, 13, 40, ❓. ¿Qué número sigue?","why":"Cada número es el triple del anterior más 1. El triple de 40 es 120, y 120 + 1 = 121.","hint":"Mira cómo se convierte cada número en el siguiente.","tags":[],"opts":["124","121","80","120"],"a":1,"fun":true},{"id":"logB-5-007","topic":"logic","level":5,"type":"number","q":"Tres números seguidos (como 7, 8 y 9) suman 48. ¿Cuál es el mayor de los tres?","why":"El número del medio es 48 ÷ 3 = 16. Los números son 15, 16 y 17, y el mayor es 17.","hint":"El número del medio es el promedio.","tags":[],"a":17},{"id":"logB-5-008","topic":"logic","level":5,"type":"choice","q":"Un cubo está pintado de azul arriba y abajo, y de rojo en sus 4 lados. ¿En cuántas de sus 12 aristas se tocan dos caras rojas?","why":"Las 4 aristas verticales unen dos lados rojos. Las 8 aristas de arriba y de abajo unen rojo con azul.","hint":"Cuenta las aristas que suben y bajan.","tags":[],"opts":["8","12","4","6"],"a":2},{"id":"logB-5-009","topic":"logic","level":5,"type":"choice","q":"Verdadero o falso: si la suma de dos números enteros es par, los dos números tienen que ser pares.","why":"3 + 5 = 8 es par, y ninguno de los dos es par. Dos números impares también suman un par.","hint":"Prueba con 3 + 5.","tags":[],"opts":["Verdadero","Falso"],"a":1},{"id":"logB-5-010","topic":"logic","level":5,"type":"choice","q":"El día 1 de un mes cae en jueves. ¿Qué día de la semana es el día 30?","why":"El día 29 está exactamente 4 semanas después del día 1, así que es jueves. El día 30 es viernes.","hint":"Las semanas se repiten cada 7 días. Salta al día 29.","tags":[],"opts":["Sábado","Viernes","Miércoles","Jueves"],"a":1},{"id":"logB-5-011","topic":"logic","level":5,"type":"number","q":"Un lanzador tira 36 lanzamientos y 2/3 son strikes. ¿Cuántos lanzamientos NO son strikes?","why":"Un tercio no son strikes, y 36 ÷ 3 = 12.","hint":"¿Qué fracción no son strikes?","tags":["baseball"],"a":12},{"id":"logB-5-012","topic":"logic","level":5,"type":"number","q":"¿Cuántos números de dos cifras DISTINTAS puedes formar con los dígitos 2, 5 y 8?","why":"Son 25, 28, 52, 58, 82 y 85. Hay 3 opciones para la primera cifra y 2 para la segunda.","hint":"Haz una lista ordenada con cada dígito primero.","tags":[],"a":6},{"id":"logB-5-013","topic":"logic","level":5,"type":"choice","q":"Ana, Beto y Cris se sientan en tres asientos de una fila. Ana está en un extremo. Beto NO está junto a Ana. ¿Quién se sienta en medio?","why":"El asiento del medio toca a los dos de los extremos. Beto no puede estar junto a Ana, así que Cris va en medio.","hint":"El asiento del medio queda junto a los dos extremos.","tags":["baseball"],"opts":["No se puede saber","Ana","Cris","Beto"],"a":2},{"id":"logB-5-014","topic":"logic","level":5,"type":"choice","q":"Verdadero o falso: si es un guante de béisbol, sirve para atrapar la pelota. Este objeto NO sirve para atrapar. Entonces no es un guante de béisbol.","why":"Si todos los guantes de béisbol sirven para atrapar, algo que no sirve para atrapar no puede ser uno.","hint":"¿Podría ser guante algo que no atrapa?","tags":["baseball"],"opts":["Verdadero","Falso"],"a":0},{"id":"logB-5-015","topic":"logic","level":5,"type":"choice","q":"Mira este patrón: 2, 20, 4, 40, 6, 60, ❓. ¿Qué número sigue?","why":"Hay dos patrones mezclados: 2, 4, 6 en los lugares impares y 20, 40, 60 en los pares. Sigue el 8.","hint":"Mira un número sí y otro no.","tags":[],"opts":["8","80","7","10"],"a":0},{"id":"logB-5-016","topic":"logic","level":5,"type":"number","q":"Un cohete despegó a las 11:40 p. m. y aterrizó a las 2:15 a. m. del día siguiente. ¿Cuántos minutos duró el vuelo?","why":"De 11:40 a medianoche son 20 minutos, y de medianoche a las 2:15 son 135. 20 + 135 = 155.","hint":"Cuenta primero hasta la medianoche.","tags":["space"],"a":155},{"id":"logB-5-017","topic":"logic","level":5,"type":"choice","q":"En un cuadrado mágico de 3 × 3, cada fila suma 15. La fila de arriba es 2, ❓, 6. ¿Qué número va en el ❓?","why":"2 + 6 = 8, y 15 − 8 = 7.","hint":"Suma los dos números y compara con 15.","tags":[],"opts":["6","8","5","7"],"a":3},{"id":"logB-5-018","topic":"logic","level":5,"type":"choice","q":"Exactamente una de estas notas es FALSA. A: «El tesoro está en el cofre 2.» B: «El tesoro NO está en el cofre 2.» C: «Está en el cofre 1.» ¿Dónde está el tesoro?","why":"A y B se contradicen: una de ellas ya es la falsa. Entonces C es verdadera y el tesoro está en el cofre 1.","hint":"¿Cuáles dos notas se contradicen?","tags":[],"opts":["En el cofre 1","En el cofre 3","En el cofre 2","No se puede saber"],"a":0,"fun":true},{"id":"logB-5-019","topic":"logic","level":5,"type":"order","q":"Ordena estas fracciones de menor a mayor.","why":"En decimales son 0,25, 0,33, 0,375 y 0,4.","hint":"Pasa cada fracción a decimal.","tags":["baseball"],"opts":["1/4","1/3","3/8","2/5"]},{"id":"logB-5-020","topic":"logic","level":5,"type":"choice","q":"Una pecera tiene 4 peces dorados más que peces payaso. En total hay 14 peces. ¿Cuántos peces dorados hay?","why":"Si quitas los 4 extra, quedan 10 peces repartidos igual: 5 y 5. Entonces hay 5 payaso y 9 dorados.","hint":"Quita primero los 4 peces de más.","tags":["ocean","animals"],"opts":["7","10","5","9"],"a":3},{"id":"logB-6-001","topic":"logic","level":6,"type":"choice","q":"Ocho niños van a un campamento de béisbol. ¿Qué frase TIENE que ser verdadera?","why":"La semana tiene solo 7 días, y hay 8 niños. Alguno tiene que repetir. Un mismo cumpleaños no es seguro.","hint":"La semana tiene solo 7 días para repartir.","tags":["baseball"],"opts":["Todos nacieron en días distintos","Algún día de la semana nadie nació","Dos cumplen años el mismo día del año","Dos nacieron el mismo día de la semana"],"a":3},{"id":"logB-6-002","topic":"logic","level":6,"type":"number","q":"Un pez pesa 6 kilos más la mitad de su propio peso. ¿Cuántos kilos pesa?","why":"La mitad de su peso tiene que ser 6 kilos, así que todo el pez pesa 12. Comprueba: 6 + 6 = 12.","hint":"¿Cuántos kilos son la mitad del pez?","tags":["ocean"],"a":12},{"id":"logB-6-003","topic":"logic","level":6,"type":"choice","q":"¿Cuántos números de dos cifras tienen dígitos que suman 6?","why":"Son 15, 24, 33, 42, 51 y 60. El 60 sí cuenta, pero el 06 no es de dos cifras.","hint":"Haz una lista ordenada, empezando por 15.","tags":[],"opts":["7","4","5","6"],"a":3},{"id":"logB-6-004","topic":"logic","level":6,"type":"choice","q":"Verdadero o falso: al lanzar dos dados normales, sacar un total de 7 es más probable que sacar un total de 11.","why":"El 11 solo sale con 5 y 6 (2 formas). El 7 sale de seis formas, como 1 y 6 o 2 y 5.","hint":"Cuenta las formas de sacar cada total.","tags":[],"opts":["Verdadero","Falso"],"a":0},{"id":"logB-6-005","topic":"logic","level":6,"type":"order","q":"Cinco niños hacen fila en el museo de dinosaurios. Eli va primero. Ana no va última. Beto no va junto a Ana. Cris va justo delante de Dani. Ordénalos de adelante hacia atrás.","why":"Si Ana va segunda, Cris y Dani son pareja en el 3 y el 4. Beto queda último y lejos de Ana.","hint":"Prueba dónde puede ir Ana.","tags":["dinosaurs"],"opts":["Eli","Ana","Cris","Dani","Beto"]},{"id":"logB-6-006","topic":"logic","level":6,"type":"choice","q":"Anteayer fue sábado. ¿Qué día será pasado mañana?","why":"Anteayer fue sábado, ayer fue domingo, hoy es lunes y mañana es martes. Pasado mañana es miércoles.","hint":"Encuentra primero qué día es hoy.","tags":[],"opts":["Jueves","Lunes","Miércoles","Martes"],"a":2},{"id":"logB-6-007","topic":"logic","level":6,"type":"number","q":"Tienes muchas monedas de 10 y de 5 centavos. ¿De cuántas formas distintas puedes juntar exactamente 30 centavos? Puedes usar solo una clase de moneda.","why":"Con 0, 1, 2 o 3 monedas de 10, completas con monedas de 5: 6, 4, 2 o 0. Son 4 formas.","hint":"Empieza sin monedas de 10 y añade una a la vez.","tags":["money"],"a":4},{"id":"logB-6-008","topic":"logic","level":6,"type":"choice","q":"Dos jugadores se turnan para quitar 1, 2 o 3 fichas de una pila de 14. Gana quien quita la última. ¿Cuántas fichas debe quitar el primero para asegurar la victoria?","why":"Quitando 2 quedan 12. Luego, si el otro quita una cantidad, tú quitas lo que falta para sumar 4: quedarán 8, 4 y 0.","hint":"Intenta dejar un múltiplo de 4.","tags":[],"opts":["2","Ninguna cantidad asegura ganar","1","3"],"a":0},{"id":"logB-6-009","topic":"logic","level":6,"type":"number","q":"Una pirámide de cubos tiene 5 capas cuadradas: 5 × 5 cubos abajo, luego 4 × 4, 3 × 3, 2 × 2 y 1 cubo arriba. ¿Cuántos cubos tiene en total?","why":"Las capas tienen 25, 16, 9, 4 y 1 cubos. 25 + 16 + 9 + 4 + 1 = 55.","hint":"Calcula cuántos cubos tiene cada capa.","tags":[],"a":55},{"id":"logB-6-010","topic":"logic","level":6,"type":"choice","q":"Verdadero o falso: todos los delfines son mamíferos y ningún mamífero tiene branquias. Entonces ningún delfín tiene branquias.","why":"Los delfines están dentro del grupo de los mamíferos, y ese grupo no incluye animales con branquias.","hint":"Piensa en círculos dentro de círculos.","tags":["ocean"],"opts":["Verdadero","Falso"],"a":0},{"id":"logB-6-011","topic":"logic","level":6,"type":"choice","q":"¿Cuántos meses del año tienen 31 días?","why":"Tienen 31 días enero, marzo, mayo, julio, agosto, octubre y diciembre. Son 7.","hint":"Recorre los meses uno por uno.","tags":[],"opts":["8","7","5","6"],"a":1,"fun":true},{"id":"logB-6-012","topic":"logic","level":6,"type":"number","q":"Una caja tiene más de 2 pelotas de béisbol. Si las cuentas de 3 en 3, de 4 en 4 o de 5 en 5, siempre sobran 2. ¿Cuál es la menor cantidad posible?","why":"3, 4 y 5 caben exactamente en 60. Sumando las 2 que sobran, la menor cantidad posible es 62.","hint":"Busca un número en el que caben 3, 4 y 5.","tags":["baseball"],"a":62},{"id":"logB-6-013","topic":"logic","level":6,"type":"choice","q":"Diez astronautas se sientan parejos alrededor de una mesa redonda y se numeran del 1 al 10 en orden. ¿Qué número queda justo enfrente del 4?","why":"Enfrente es la mitad del camino, o sea 5 asientos. 4 + 5 = 9.","hint":"La mitad de 10 asientos son 5.","tags":["space"],"opts":["10","7","8","9"],"a":3},{"id":"logB-6-014","topic":"logic","level":6,"type":"choice","q":"Mira este patrón: 2, 3, 5, 8, 13, 21, ❓. ¿Qué número sigue?","why":"Cada número es la suma de los dos anteriores. 13 + 21 = 34.","hint":"Suma los dos últimos números.","tags":[],"opts":["34","29","32","36"],"a":0},{"id":"logB-6-015","topic":"logic","level":6,"type":"number","q":"En un estadio hay personas y perros. Entre todos tienen 12 cabezas y 34 patas. ¿Cuántos perros hay?","why":"Si los 12 tuvieran 2 patas, serían 24. Sobran 10 patas, y cada perro aporta 2 extra, así que hay 5 perros.","hint":"Imagina primero que todos tienen 2 patas.","tags":["baseball","animals"],"a":5},{"id":"logB-6-016","topic":"logic","level":6,"type":"choice","q":"Verdadero o falso: 3 × 3 × 3 × 3 es mayor que 4 × 4 × 4.","why":"3 × 3 × 3 × 3 es 81 y 4 × 4 × 4 es 64, así que 81 es mayor.","hint":"Calcula las dos multiplicaciones.","tags":[],"opts":["Verdadero","Falso"],"a":0},{"id":"logB-6-017","topic":"logic","level":6,"type":"choice","q":"Un tanque de agua está lleno a 1/4. Después de echar 6 jarras, queda lleno a 3/4. ¿Cuántas jarras llenan un tanque vacío?","why":"Las 6 jarras llenaron la mitad del tanque. Entonces el tanque entero necesita 2 × 6 = 12 jarras.","hint":"¿Qué fracción del tanque llenaron las 6 jarras?","tags":["ocean"],"opts":["18","24","12","8"],"a":2},{"id":"logB-6-018","topic":"logic","level":6,"type":"number","q":"⭐ + ⭐ + ⭐ = 🌙 + 6 y 🌙 = ⭐ + 4. ¿Cuánto vale ⭐?","why":"Cambia 🌙 por ⭐ + 4: tres ⭐ son una ⭐ más 10. Entonces dos ⭐ valen 10 y cada ⭐ vale 5.","hint":"Reemplaza 🌙 en la primera línea.","tags":["space"],"a":5},{"id":"logB-6-019","topic":"logic","level":6,"type":"choice","q":"¿Cuántos pedazos como máximo puedes obtener de una pizza redonda con 4 cortes rectos?","why":"Si cada corte cruza a todos los anteriores, los cortes dan 2, 4, 7 y 11 pedazos. Cortar por el centro da solo 8.","hint":"Haz que cada corte cruce a los otros.","tags":["food"],"opts":["9","11","8","10"],"a":1,"fun":true},{"id":"logB-6-020","topic":"logic","level":6,"type":"order","q":"Cuatro bateadores conectaron hits en estas fracciones de sus turnos. Ordena las fracciones de menor a mayor.","why":"En decimales son 0,33, 0,375, 0,4 y 0,42.","hint":"Pasa cada fracción a decimal.","tags":[],"opts":["1/3","3/8","2/5","5/12"]},{"id":"lecB-1-001","topic":"reading","level":1,"type":"choice","q":"Leo se pone su gorra roja para ir a los juegos de béisbol. ¿Qué se pone Leo para ir al béisbol?","why":"El texto dice que Leo usa una gorra roja. Las otras cosas no aparecen.","hint":"Busca la prenda de ropa en la primera oración.","tags":["baseball"],"opts":["Un guante azul","Una gorra roja","Un abrigo verde"],"a":1},{"id":"lecB-1-002","topic":"reading","level":1,"type":"choice","q":"El tiburón martillo tiene la cabeza ancha y plana. Verdadero o falso: su cabeza es redonda como una pelota.","why":"El texto dice ancha y plana. Una pelota es redonda, así que es falso.","hint":"Fíjate en las palabras 'ancha y plana'.","tags":["sharks"],"opts":["Verdadero","Falso"],"a":1},{"id":"lecB-1-003","topic":"reading","level":1,"type":"choice","q":"Cuando Ana llegó a casa, su perrito corrió a la puerta moviendo la cola. ¿Cómo se sintió el perrito?","why":"Correr a la puerta y mover la cola muestran alegría.","hint":"¿Qué muestra un perro cuando mueve la cola?","tags":["animals"],"opts":["Enojado","Asustado","Contento"],"a":2},{"id":"lecB-1-004","topic":"reading","level":1,"type":"order","q":"Ordena el día del pescador.","why":"Primero sube al barco y echa la red. Solo después puede sacar peces y volver.","hint":"¿Qué hay que hacer antes de sacar los peces?","tags":["ocean"],"opts":["El pescador subió a su barco.","Echó la red al mar.","Sacó la red llena de peces.","Regresó al puerto con su pesca."]},{"id":"lecB-1-005","topic":"reading","level":1,"type":"choice","q":"El tiburón nadó muy rápido para atrapar un pez. ¿Por qué nadó rápido?","why":"La razón está en el texto: nadó rápido para atrapar un pez.","hint":"Busca la palabra 'para' en la oración.","tags":["sharks"],"opts":["Para atrapar un pez","Para dormir un rato","Para esconderse en la arena"],"a":0},{"id":"lecB-1-006","topic":"reading","level":1,"type":"choice","q":"Si una estrella de mar pierde un brazo, le puede crecer uno nuevo. ¿Qué le puede crecer?","why":"Muchas estrellas de mar pueden regenerar un brazo perdido. Parece magia, pero es real.","hint":"Lee otra vez qué pierde la estrella de mar.","tags":["ocean","animals"],"opts":["Una cola nueva","Un brazo nuevo","Una concha nueva"],"a":1,"fun":true},{"id":"lecB-1-007","topic":"reading","level":1,"type":"number","q":"Beto tenía 4 tarjetas de béisbol. Lola le regaló 3 más. ¿Cuántas tarjetas tiene Beto ahora?","why":"Beto tenía 4 y recibió 3 más. Entonces 4 más 3 son 7.","hint":"Suma las tarjetas que le dieron.","tags":["baseball"],"a":7},{"id":"lecB-1-008","topic":"reading","level":1,"type":"choice","q":"Todo libro tiene un título en la portada. ¿Qué dice el título?","why":"El título es el nombre del libro. No dice cómo termina ni cuántas hojas tiene.","hint":"Piensa en cómo llamas a un libro.","tags":[],"opts":["El nombre del libro","Dónde termina el libro","Cuántas hojas tiene"],"a":0},{"id":"lecB-1-009","topic":"reading","level":1,"type":"choice","q":"Mateo se puso la gorra, tomó el bate y su guante y corrió al campo. Su equipo lo esperaba. ¿Qué va a hacer Mateo?","why":"El bate, el guante y el equipo esperando indican que va a jugar béisbol.","hint":"Fíjate en lo que lleva en las manos.","tags":["baseball"],"opts":["Hornear un pastel","Irse a dormir","Jugar béisbol"],"a":2},{"id":"lecB-1-010","topic":"reading","level":1,"type":"choice","q":"Las ballenas respiran aire con pulmones. Verdadero o falso: una ballena respira debajo del agua con branquias.","why":"Las ballenas son mamíferos: suben a la superficie a respirar aire. Los peces son los que usan branquias.","hint":"Lee otra vez cómo respiran las ballenas.","tags":["ocean"],"opts":["Verdadero","Falso"],"a":1},{"id":"lecB-1-011","topic":"reading","level":1,"type":"choice","q":"Las olas llegaban a la arena y las gaviotas volaban cerca. Dani cavaba con su pala. ¿Dónde está Dani?","why":"Olas, arena y gaviotas son pistas de una playa.","hint":"¿Qué pistas hablan de arena y olas?","tags":["ocean"],"opts":["En un pueblo con nieve","En la playa","En un bosque tranquilo"],"a":1},{"id":"lecB-1-012","topic":"reading","level":1,"type":"order","q":"Ordena estos animales del mar por orden alfabético.","why":"Las primeras letras b, c, d y t van en ese orden en el abecedario.","hint":"Recita el abecedario y busca cada letra inicial.","tags":["ocean"],"opts":["ballena","cangrejo","delfín","tiburón"]},{"id":"lecB-1-013","topic":"reading","level":1,"type":"choice","q":"Valeria vio por fin una ballena desde el barco. Abrió mucho los ojos y sonrió. ¿Cómo se sintió?","why":"Abrir los ojos y sonreír muestran que estaba contenta.","hint":"¿Qué muestra una sonrisa?","tags":["ocean"],"opts":["Contenta","Triste","Enojada"],"a":0},{"id":"lecB-1-014","topic":"reading","level":1,"type":"choice","q":"La tortuga tiene caparazón y camina despacio. El conejo no tiene caparazón y salta rápido. ¿Cuál de los dos tiene caparazón?","why":"El texto dice que solo la tortuga tiene caparazón.","hint":"Compara las dos primeras oraciones.","tags":["animals"],"opts":["El conejo","La tortuga","Los dos"],"a":1},{"id":"lecB-1-015","topic":"reading","level":1,"type":"number","q":"¿Cuántas sílabas tiene la palabra 'delfín'?","why":"Se lee del-fín: dos golpes de voz, dos sílabas.","hint":"Aplaude al decir la palabra despacio.","tags":["ocean"],"a":2},{"id":"lecB-1-016","topic":"reading","level":1,"type":"choice","q":"Un libro enseña a hacer un barquito de papel, paso a paso. ¿Para qué lo escribió el autor?","why":"Un libro de pasos explica cómo hacer una cosa. Quiere enseñar.","hint":"¿Qué te ayudan a hacer los pasos?","tags":[],"opts":["Para asustar al lector","Para contar un chiste","Para enseñar algo"],"a":2},{"id":"lecB-1-017","topic":"reading","level":1,"type":"choice","q":"El estegosaurio tenía placas en la espalda y comía solo plantas. ¿Qué comía el estegosaurio?","why":"El texto dice que comía solo plantas, así que no comía carne.","hint":"Busca la palabra 'solo' en la oración.","tags":["dinosaurs"],"opts":["Plantas","Carne","Peces"],"a":0},{"id":"lecB-1-018","topic":"reading","level":1,"type":"choice","q":"Un cuento tiene principio, nudo y final. Verdadero o falso: el final es la última parte del cuento.","why":"El final cierra la historia: es la última parte. El principio es la primera.","hint":"Piensa en dónde termina una historia.","tags":[],"opts":["Verdadero","Falso"],"a":0},{"id":"lecB-1-019","topic":"reading","level":1,"type":"choice","q":"La astronauta soltó su lápiz y el lápiz se quedó flotando en el aire. ¿Dónde está la astronauta?","why":"En una nave en el espacio, las cosas flotan en vez de caer como en la Tierra.","hint":"En la Tierra, el lápiz caería.","tags":["space"],"opts":["En la cocina","En el estadio","En el espacio"],"a":2},{"id":"lecB-1-020","topic":"reading","level":1,"type":"choice","q":"¿Qué palabra rima con 'mar'?","why":"Mar y jugar terminan con el mismo sonido: -ar.","hint":"Escucha el final de cada palabra.","tags":["ocean"],"opts":["luna","jugar","pez"],"a":1},{"id":"lecB-2-001","topic":"reading","level":2,"type":"choice","q":"El cangrejo ermitaño es muy tímido. Cuando llega una ola grande, se esconde dentro de su concha. ¿Qué significa 'tímido'?","why":"Esconderse cuando algo se acerca muestra que es vergonzoso y se asusta con facilidad.","hint":"¿Qué te dice la acción de esconderse?","tags":["ocean"],"opts":["Hambriento","Vergonzoso","Ruidoso"],"a":1},{"id":"lecB-2-002","topic":"reading","level":2,"type":"choice","q":"Su equipo iba perdiendo por una carrera. Joaquín respiró hondo, apretó el bate y miró al lanzador. ¿Qué va a hacer Joaquín?","why":"Apretar el bate y mirar al lanzador es prepararse para batear.","hint":"¿Por qué un bateador mira al lanzador?","tags":["baseball"],"opts":["Batear la pelota","Irse del juego","Arreglar la base"],"a":0},{"id":"lecB-2-003","topic":"reading","level":2,"type":"choice","q":"Los tiburones no tienen huesos. Su esqueleto es de cartílago, flexible como la punta de tu oreja. Verdadero o falso: el esqueleto de un tiburón es de cartílago.","why":"Los tiburones tienen un esqueleto de cartílago, que se dobla, igual que la punta de tu oreja.","hint":"Vuelve a leer la segunda oración.","tags":["sharks"],"opts":["Verdadero","Falso"],"a":0},{"id":"lecB-2-004","topic":"reading","level":2,"type":"order","q":"Ordena la vida de una rana.","why":"Primero están los huevos y el renacuajo. Las patas aparecen antes de que sea una rana adulta.","hint":"¿Qué sale primero, el huevo o la rana?","tags":["animals"],"opts":["La rana pone huevos en el agua.","Del huevo sale un renacuajo con cola.","Al renacuajo le salen patas.","El renacuajo se convierte en rana."]},{"id":"lecB-2-005","topic":"reading","level":2,"type":"choice","q":"El caballito de mar macho lleva los huevos en una bolsita de su panza. Los bebés salen cuando están listos. ¿Cuál es la idea principal?","why":"Las dos oraciones hablan de que el papá carga los huevos. No mencionan ríos ni algas.","hint":"¿De qué hablan las dos oraciones?","tags":["ocean","animals"],"opts":["Viven en los ríos y lagos","El papá lleva los huevos","Los bebés comen muchas algas"],"a":1,"fun":true},{"id":"lecB-2-006","topic":"reading","level":2,"type":"choice","q":"El equipo de Tomás ganó el campeonato. Abrazó a sus compañeros y no podía dejar de sonreír. ¿Cómo se sintió Tomás?","why":"Abrazar y sonreír después de ganar muestran mucha felicidad.","hint":"Mira lo que hace Tomás con su cara.","tags":["baseball"],"opts":["Preocupado","Molesto","Muy feliz"],"a":2},{"id":"lecB-2-007","topic":"reading","level":2,"type":"number","q":"Un partido de béisbol tiene 9 entradas. Ya se jugaron 4. ¿Cuántas entradas faltan?","why":"Si hay 9 en total y se jugaron 4, faltan 9 menos 4, que son 5.","hint":"Resta las entradas jugadas del total.","tags":["baseball"],"a":5},{"id":"lecB-2-008","topic":"reading","level":2,"type":"choice","q":"Cuando sale el Sol, los charcos se secan porque el calor convierte el agua en vapor. ¿Qué seca los charcos?","why":"El texto dice que el calor del Sol convierte el agua en vapor.","hint":"Busca la palabra 'porque'.","tags":["weather"],"opts":["El calor del Sol","La luna llena de noche","El viento frío del norte"],"a":0},{"id":"lecB-2-009","topic":"reading","level":2,"type":"choice","q":"¿Qué parte de un libro muestra los capítulos y la página donde empieza cada uno?","why":"El índice lista los capítulos con sus páginas. El glosario explica palabras.","hint":"Se encuentra al principio o al final del libro.","tags":[],"opts":["La portada","El glosario","El índice"],"a":2},{"id":"lecB-2-010","topic":"reading","level":2,"type":"choice","q":"El helado de Lola se derritió porque lo dejó al sol. Verdadero o falso: el helado se derritió porque estaba en el congelador.","why":"Se derritió por el calor del sol. En el congelador habría seguido duro.","hint":"Fíjate en la palabra 'porque'.","tags":["food"],"opts":["Verdadero","Falso"],"a":1},{"id":"lecB-2-011","topic":"reading","level":2,"type":"choice","q":"La huella del dinosaurio era gigantesca: una familia entera cabía dentro. ¿Qué significa 'gigantesca'?","why":"Si cabe una familia entera, la huella debe ser muy grande.","hint":"¿Qué tan grande debe ser una huella para que quepa una familia?","tags":["dinosaurs"],"opts":["Muy pequeña","Muy antigua","Muy grande"],"a":2},{"id":"lecB-2-012","topic":"reading","level":2,"type":"order","q":"Ordena la jugada de béisbol.","why":"Todo empieza con el lanzamiento. El público aplaude después de la atrapada.","hint":"¿Qué debe pasar antes de que alguien atrape la pelota?","tags":["baseball"],"opts":["El lanzador tiró la pelota.","El bateador la golpeó fuerte.","El jardinero la atrapó.","El público aplaudió."]},{"id":"lecB-2-013","topic":"reading","level":2,"type":"choice","q":"Una autora escribe un cuento divertido sobre un perro que usa lentes de sol. ¿Para qué lo escribió?","why":"Los cuentos divertidos se escriben para entretener.","hint":"¿El cuento es para aprender o para pasarla bien?","tags":["animals"],"opts":["Para dar órdenes a todos","Para hacernos sonreír","Para enseñar a sumar mejor"],"a":1},{"id":"lecB-2-014","topic":"reading","level":2,"type":"choice","q":"La ballena azul es muy grande, pero come animalitos diminutos llamados kril. ¿Qué come la ballena azul?","why":"El tamaño engaña: la ballena azul gigante come animalitos diminutos.","hint":"Busca el alimento que nombra el texto.","tags":["ocean"],"opts":["Kril diminuto","Peces enormes","Pulpos grandes"],"a":0,"fun":true},{"id":"lecB-2-015","topic":"reading","level":2,"type":"choice","q":"Las medusas no tienen huesos, cerebro ni corazón. Verdadero o falso: una medusa tiene corazón.","why":"Las medusas casi son puro agua y no tienen corazón, cerebro ni huesos.","hint":"Busca la palabra 'ni' en el texto.","tags":["ocean","animals"],"opts":["Verdadero","Falso"],"a":1,"fun":true},{"id":"lecB-2-016","topic":"reading","level":2,"type":"choice","q":"Orbitar es dar vueltas alrededor de algo. La Luna orbita la Tierra. ¿Qué hace la Luna?","why":"Orbitar significa dar vueltas alrededor, así que la Luna gira alrededor de la Tierra.","hint":"Usa el significado que da el texto.","tags":["space"],"opts":["Se queda quieta","Se aleja de la Tierra","Gira alrededor de ella"],"a":2},{"id":"lecB-2-017","topic":"reading","level":2,"type":"number","q":"Un tiburón perdió 2 dientes en el almuerzo y 4 más en la cena. Cada vez le salieron dientes nuevos. ¿Cuántos dientes perdió en total?","why":"Perdió 2 y luego 4, así que 2 más 4 son 6. Los dientes nuevos no cambian lo que perdió.","hint":"Suma solo los dientes que se cayeron.","tags":["sharks"],"a":6},{"id":"lecB-2-018","topic":"reading","level":2,"type":"choice","q":"En un diccionario, las palabras guía de una página son 'delfín' y 'dragón'. ¿Qué palabra estaría en esa página?","why":"Dinosaurio va después de delfín y antes de dragón en orden alfabético.","hint":"Compara la segunda letra de cada palabra.","tags":["dinosaurs"],"opts":["dinosaurio","ballena","foca"],"a":0},{"id":"lecB-2-019","topic":"reading","level":2,"type":"choice","q":"¿Cuál de estas palabras está bien escrita?","why":"Tiburón es aguda y termina en n, así que lleva tilde en la última sílaba: -rón.","hint":"Di la palabra y escucha cuál sílaba suena más fuerte.","tags":["sharks"],"opts":["tiburon","tiburón","tíburon"],"a":1},{"id":"lecB-2-020","topic":"reading","level":2,"type":"choice","q":"La rana tiene la piel lisa y húmeda. El sapo tiene la piel seca y con bultos. Verdadero o falso: la piel del sapo es seca y con bultos.","why":"Eso dice el texto sobre el sapo. La piel lisa y húmeda es la de la rana.","hint":"Mira qué animal se describe con cada piel.","tags":["animals"],"opts":["Verdadero","Falso"],"a":0},{"id":"lecB-3-001","topic":"reading","level":3,"type":"choice","q":"La exploradora estaba sedienta después de caminar horas por el desierto. Se tomó una botella entera de agua. ¿Qué significa 'sedienta'?","why":"Tomarse una botella entera de agua es la pista: sedienta quiere decir con mucha sed.","hint":"¿Por qué alguien tomaría tanta agua?","tags":[],"opts":["Con mucho sueño","Con mucho frío","Con mucha sed","Con mucho miedo"],"a":2},{"id":"lecB-3-002","topic":"reading","level":3,"type":"choice","q":"El entrenador miró las nubes negras y luego el marcador. —Terminemos rápido antes de que llueva —dijo. ¿Qué le preocupa?","why":"Las nubes negras y la palabra 'llueva' muestran que teme que el clima detenga el partido.","hint":"Une las nubes con lo que dijo el entrenador.","tags":["baseball","weather"],"opts":["Que la lluvia pare el juego","Que se pierda un bate","Que el autobús llegue tarde","Que se rompa un guante"],"a":0},{"id":"lecB-3-003","topic":"reading","level":3,"type":"choice","q":"Cuando el narrador dice 'yo', cuenta la historia como un personaje. Verdadero o falso: en 'Yo caminé hacia el montículo para lanzar', quien cuenta es un personaje de la historia.","why":"La palabra 'yo' muestra que el narrador está dentro de la historia: es el lanzador.","hint":"Fíjate en la palabra 'yo'.","tags":["baseball"],"opts":["Verdadero","Falso"],"a":0},{"id":"lecB-3-004","topic":"reading","level":3,"type":"choice","q":"Los pulpos sueltan tinta oscura cuando se asustan. La tinta forma una nube en el agua y el pulpo se escapa. ¿Para qué suelta tinta el pulpo?","why":"La nube de tinta lo esconde de un depredador y le da tiempo de huir.","hint":"¿Qué pasa justo después de que se forma la nube?","tags":["ocean","animals"],"opts":["Para pintar las rocas","Para llamar a sus amigos","Para cazar su almuerzo","Para escapar del peligro"],"a":3},{"id":"lecB-3-005","topic":"reading","level":3,"type":"choice","q":"Los camaleones cambian de color cuando sienten calor, frío o miedo. También cambian de color para comunicarse con otros camaleones. ¿Cuál es la idea principal?","why":"Las dos oraciones hablan de las razones por las que cambian de color.","hint":"¿Qué tienen en común las dos oraciones?","tags":["animals"],"opts":["Solo viven en los árboles altos","Cambian de color","Los camaleones son muy veloces","Comen muchos insectos al día"],"a":1},{"id":"lecB-3-006","topic":"reading","level":3,"type":"number","q":"Rosa tiene 6 libros de tiburones y 5 de dinosaurios. Le presta 4 libros a su primo. ¿Cuántos libros le quedan a Rosa?","why":"6 más 5 son 11 libros. Si presta 4, quedan 11 menos 4, que son 7.","hint":"Suma primero y luego resta.","tags":["sharks","dinosaurs"],"a":7},{"id":"lecB-3-007","topic":"reading","level":3,"type":"choice","q":"Todos los días después del entrenamiento, Lena recoge las pelotas, ordena los bates y barre el banquillo, aunque nadie se lo pide. ¿Qué palabra describe mejor a Lena?","why":"Hacer tareas extra sin que se lo pidan muestra que es servicial.","hint":"¿Qué muestran sus acciones sobre ella?","tags":["baseball"],"opts":["Perezosa","Mandona","Servicial","Olvidadiza"],"a":2},{"id":"lecB-3-008","topic":"reading","level":3,"type":"choice","q":"El mar estaba sereno. Ningún viento movía las olas y el agua parecía un espejo. ¿Qué significa 'sereno'?","why":"Sin viento ni olas y con el agua como espejo, sereno quiere decir tranquilo.","hint":"Imagina el mar como un espejo.","tags":["ocean"],"opts":["Tranquilo","Furioso","Helado","Oscuro"],"a":0},{"id":"lecB-3-009","topic":"reading","level":3,"type":"order","q":"Ordena el viaje de un cohete.","why":"Antes del despegue hay que esperar y contar al revés. Solo después puede llegar al espacio.","hint":"¿Qué pasa justo antes de despegar?","tags":["space"],"opts":["El cohete espera en la plataforma.","Comienza la cuenta regresiva.","El cohete despega entre fuego y humo.","La nave llega al espacio."]},{"id":"lecB-3-010","topic":"reading","level":3,"type":"choice","q":"Mariana caminó de puntillas por la cocina a medianoche y abrió el refrigerador muy despacito. ¿Por qué caminaba de puntillas?","why":"A medianoche, caminar de puntillas y despacito muestra que no quería despertar a nadie.","hint":"¿Por qué las personas se mueven en silencio de noche?","tags":[],"opts":["Llegaba tarde a clases","Para no hacer ruido","Había perdido sus zapatos","Practicaba ballet"],"a":1},{"id":"lecB-3-011","topic":"reading","level":3,"type":"choice","q":"Las ballenas y los delfines son mamíferos. Las ballenas barbadas filtran su comida y los delfines cazan peces. ¿Qué tienen en común?","why":"El texto dice que los dos son mamíferos. Se alimentan de formas distintas.","hint":"Busca lo que el texto dice de los dos.","tags":["ocean","animals"],"opts":["Filtran su comida","Tienen branquias","Ponen huevos","Son mamíferos"],"a":3},{"id":"lecB-3-012","topic":"reading","level":3,"type":"choice","q":"La arena de la playa se calienta más al mediodía porque el Sol está más alto y da más calor. Verdadero o falso: la arena está más fría al mediodía que al amanecer.","why":"Con el Sol alto y más calor, la arena se calienta más al mediodía, no menos.","hint":"Busca la palabra 'más' en la primera oración.","tags":["ocean","weather"],"opts":["Verdadero","Falso"],"a":1},{"id":"lecB-3-013","topic":"reading","level":3,"type":"choice","q":"¿Cuál de estas oraciones trata de convencerte de algo?","why":"'¡Prueba!' te dice qué hacer. Las otras oraciones solo dan datos.","hint":"¿Cuál intenta cambiar lo que piensas?","tags":["baseball"],"opts":["¡Prueba el béisbol, te va a encantar!","El béisbol se juega con bate y pelota.","Un partido completo tiene nueve entradas.","La pelota de béisbol es blanca y dura."],"a":0},{"id":"lecB-3-014","topic":"reading","level":3,"type":"choice","q":"Los pescadores salieron en su barco al amanecer, cuando el Sol apenas asomaba. ¿Qué parte del día es el amanecer?","why":"El texto dice que el Sol apenas asomaba: es el momento en que sale.","hint":"¿Qué hace el Sol al empezar el día?","tags":["ocean"],"opts":["Cuando se oculta el Sol","El mediodía","Cuando sale el Sol","La medianoche"],"a":2},{"id":"lecB-3-015","topic":"reading","level":3,"type":"number","q":"El equipo anotó 3 carreras en la primera entrada, ninguna en la segunda y 4 en la tercera. ¿Cuántas carreras anotó en las tres entradas?","why":"3 más 0 más 4 son 7 carreras. 'Ninguna' quiere decir cero.","hint":"Recuerda que ninguna es cero.","tags":["baseball"],"a":7},{"id":"lecB-3-016","topic":"reading","level":3,"type":"choice","q":"Las ramas se movían apenas y el mar parecía un espejo. ¿Cómo estaba el tiempo?","why":"Ramas casi quietas y mar como espejo son señales de calma, sin viento fuerte.","hint":"¿Qué pasa con las ramas cuando hay tormenta?","tags":["weather","ocean"],"opts":["Había una fuerte tormenta","Había un gran huracán","Todo estaba en calma","Caía mucho granizo"],"a":2},{"id":"lecB-3-017","topic":"reading","level":3,"type":"choice","q":"Las tortugas marinas no tienen dientes. Cortan su comida con un pico duro. ¿Qué usan en lugar de dientes?","why":"El texto dice que cortan la comida con un pico duro y que no tienen dientes.","hint":"Busca la herramienta que nombra el texto.","tags":["ocean","animals"],"opts":["Colmillos largos","Un pico duro","Garras fuertes","Tentáculos"],"a":1,"fun":true},{"id":"lecB-3-018","topic":"reading","level":3,"type":"order","q":"Ordena cómo Ana prepara un sándwich.","why":"Las palabras primero, luego, después y finalmente señalan el orden.","hint":"Busca las palabras que marcan el orden.","tags":["food"],"opts":["Primero, Ana sacó dos rebanadas de pan.","Luego, puso queso encima.","Después, cerró el sándwich.","Finalmente, se lo comió."]},{"id":"lecB-3-019","topic":"reading","level":3,"type":"choice","q":"Al principio, Omar tenía miedo de meter la cara en el agua. Después de practicar semanas, cruzó la alberca y sonrió orgulloso. ¿Cómo cambió Omar?","why":"Empezó con miedo y terminó sonriendo con orgullo después de lograrlo.","hint":"Compara cómo se siente al inicio y al final.","tags":["ocean"],"opts":["De temeroso a orgulloso","De dormido a enojado","De aburrido a asustado","De alegre a triste"],"a":0},{"id":"lecB-3-020","topic":"reading","level":3,"type":"choice","q":"Cuando una abeja encuentra flores, regresa a la colmena y baila. Su baile les dice a las demás hacia dónde están las flores. ¿Cuál es la idea principal?","why":"Las dos oraciones explican cómo el baile avisa a otras abejas dónde hay flores.","hint":"¿Qué pasa cuando la abeja baila?","tags":["animals"],"opts":["Las abejas duermen casi todo el día","Las flores huelen muy rico","Las colmenas son muy grandes","Las abejas bailan para avisar"],"a":3,"fun":true},{"id":"lecB-4-001","topic":"reading","level":4,"type":"choice","q":"¿Cuál oración contiene un símil?","why":"Un símil compara dos cosas con la palabra 'como'. Aquí la bola rápida se compara con un rayo.","hint":"Busca la palabra 'como'.","tags":["baseball"],"opts":["Su bola rápida era como un rayo.","El lanzador tiró con mucha fuerza.","El público gritó emocionado.","La pelota pasó por encima de la cerca."],"a":0},{"id":"lecB-4-002","topic":"reading","level":4,"type":"choice","q":"Las olas le susurraban secretos a la orilla dormida. ¿Qué hace la autora?","why":"Las olas no pueden susurrar. Darle acciones humanas a la naturaleza se llama personificación.","hint":"¿Pueden las olas susurrar de verdad?","tags":["ocean"],"opts":["Compara las olas con algo","Hace hablar a las olas","Cuenta un dato real del mar","Da una orden a la orilla"],"a":1},{"id":"lecB-4-003","topic":"reading","level":4,"type":"choice","q":"Cuando el mar se calienta demasiado, el coral expulsa las algas diminutas que viven dentro de él y se vuelve blanco. Verdadero o falso: las algas son lo que vuelve blanco al coral.","why":"Al perder las algas, el coral se vuelve blanco. Las algas son las que le dan su color.","hint":"Lee con cuidado qué pasa primero y qué pasa después.","tags":["ocean"],"opts":["Verdadero","Falso"],"a":1},{"id":"lecB-4-004","topic":"reading","level":4,"type":"choice","q":"Su mamá le dijo: 'No dejes para mañana lo que puedes hacer hoy'. ¿Qué enseña este refrán?","why":"El refrán aconseja hacer las cosas hoy, sin esperar. No habla de dormir ni de comer.","hint":"Piensa en la palabra 'mañana'.","tags":[],"opts":["Dormir más temprano cada noche","Esperar siempre hasta el otro día","No dejar tareas para después","Comer menos dulces en casa"],"a":2},{"id":"lecB-4-005","topic":"reading","level":4,"type":"choice","q":"Mía practicó su curva todos los días. Durante semanas falló, pero siguió intentando. En primavera ponchó a tres bateadores. ¿Qué enseña el cuento?","why":"Sus fallos se convirtieron en éxito porque siguió practicando. Esa es la enseñanza.","hint":"Fíjate en qué cambió del principio al final.","tags":["baseball"],"opts":["Las curvas son muy fáciles","La primavera es la mejor estación","Los equipos nunca deben perder","Practicar ayuda a mejorar"],"a":3},{"id":"lecB-4-006","topic":"reading","level":4,"type":"number","q":"Un tiburón nadó 5 kilómetros antes del almuerzo. Después del almuerzo nadó el doble. ¿Cuántos kilómetros nadó en total?","why":"El doble de 5 es 10. Sumando los 5 de la mañana, son 15 kilómetros.","hint":"Calcula primero la distancia de la tarde.","tags":["sharks"],"a":15},{"id":"lecB-4-007","topic":"reading","level":4,"type":"choice","q":"Después de visitar el museo, Pablo dibujó huesos gigantes en su cuaderno. Esa noche pidió un libro sobre fósiles. ¿Qué se puede concluir?","why":"Dibujar huesos gigantes y pedir un libro de fósiles muestran su interés en los dinosaurios.","hint":"¿Qué opción encaja con TODAS sus acciones?","tags":["dinosaurs"],"opts":["A Pablo le interesan los dinosaurios","A Pablo le dan miedo los museos","Pablo quiere ser panadero","A Pablo no le gusta dibujar"],"a":0},{"id":"lecB-4-008","topic":"reading","level":4,"type":"order","q":"Ordena cómo el delfín encuentra un pez con el sonido.","why":"El eco solo vuelve después de que el sonido choca con el pez. Entonces el delfín sabe dónde está.","hint":"¿Qué debe volver antes de que el delfín nade?","tags":["ocean","animals"],"opts":["El delfín emite un chasquido.","El sonido choca con un pez.","El eco regresa al delfín.","El delfín nada hacia el pez."],"fun":true},{"id":"lecB-4-009","topic":"reading","level":4,"type":"choice","q":"Las plantas necesitan luz para crecer. Si dejas una planta muchos días en un armario oscuro, ¿qué le pasará?","why":"Sin luz, la planta no puede fabricar su alimento y se pone pálida y débil.","hint":"¿Qué necesita la planta para crecer?","tags":[],"opts":["Crecerá más fuerte y verde","Se pondrá pálida y débil","Se volverá azul brillante","Crecerá más rápido que antes"],"a":1},{"id":"lecB-4-010","topic":"reading","level":4,"type":"choice","q":"En la oración 'Muchos tiburones cazan peces; sin embargo, el tiburón ballena come plancton', ¿qué indica 'sin embargo'?","why":"'Sin embargo' muestra un contraste: muchos tiburones cazan peces, pero el tiburón ballena come plancton.","hint":"¿La segunda parte es igual o distinta a la primera?","tags":["sharks"],"opts":["Una causa","Un orden de tiempo","Una diferencia","Una lista"],"a":2},{"id":"lecB-4-011","topic":"reading","level":4,"type":"choice","q":"En la Luna no hay viento ni lluvia que borren las huellas, así que las pisadas de los astronautas duran muchísimo. Verdadero o falso: las huellas se borran rápido por los vientos lunares.","why":"En la Luna no hay viento, por eso las huellas se conservan mucho tiempo.","hint":"Revisa qué dice el texto sobre el viento.","tags":["space"],"opts":["Verdadero","Falso"],"a":1,"fun":true},{"id":"lecB-4-012","topic":"reading","level":4,"type":"choice","q":"El arrecife estaba repleto de peces: asomaban de cada grieta y rodeaban cada coral. ¿Qué significa 'repleto'?","why":"Peces en cada grieta y alrededor de cada coral muestran que estaba muy lleno.","hint":"¿Qué te dicen 'cada grieta' y 'cada coral'?","tags":["ocean"],"opts":["Vacío","Cubierto de hielo","Escondido","Muy lleno"],"a":3},{"id":"lecB-4-013","topic":"reading","level":4,"type":"choice","q":"En un libro de ciencias, una palabra en letra negrita suele ser...","why":"Los autores usan la negrita para destacar palabras clave, que muchas veces se explican cerca.","hint":"¿Para qué destacarías una palabra?","tags":[],"opts":["una palabra importante","un error de ortografía","el nombre del autor","el final del capítulo"],"a":0},{"id":"lecB-4-014","topic":"reading","level":4,"type":"choice","q":"Júpiter es un gigante de gas y no tiene una superficie sólida. La Tierra es un planeta rocoso. Verdadero o falso: podrías pararte sobre la superficie sólida de Júpiter.","why":"El texto dice que Júpiter no tiene superficie sólida, así que no hay dónde pararse.","hint":"Fíjate en las palabras 'no tiene'.","tags":["space"],"opts":["Verdadero","Falso"],"a":1},{"id":"lecB-4-015","topic":"reading","level":4,"type":"choice","q":"La jardinera dejó caer la pelota y su equipo perdió. Se mordió el labio, pero fue a felicitar a las rivales. ¿Qué dice esto de ella?","why":"Felicitar a las rivales después de perder muestra que sabe perder con respeto.","hint":"¿Qué hizo después de perder?","tags":["baseball"],"opts":["Odia a sus compañeras","Es una buena deportista","Quería hacer trampa","Estaba muy distraída"],"a":1},{"id":"lecB-4-016","topic":"reading","level":4,"type":"choice","q":"Teo dice que su equipo ganó con una remontada emocionante. Su prima, hincha del otro equipo, dice que fue una derrota dolorosa. ¿Por qué opinan distinto?","why":"Una remontada para un equipo es una derrota para el otro. Cada uno ve el partido desde su lado.","hint":"¿De qué equipo es hincha cada uno?","tags":["baseball"],"opts":["Jugaban otro deporte","Uno no vio el partido","Apoyan a equipos opuestos","Uno entendió mal el marcador"],"a":2},{"id":"lecB-4-017","topic":"reading","level":4,"type":"number","q":"¿Cuántas sílabas tiene la palabra 'pluviómetro'?","why":"Se divide así: plu-vió-me-tro. Son cuatro sílabas.","hint":"Aplaude cada golpe de voz al decirla despacio.","tags":["weather"],"a":4},{"id":"lecB-4-018","topic":"reading","level":4,"type":"choice","q":"El abuelo llamó 'pececito' al pez que atrapó. ¿Qué indica el final -ito?","why":"Los diminutivos como -ito indican que algo es pequeño o que se le tiene cariño.","hint":"¿Qué sientes cuando dices 'perrito'?","tags":["ocean"],"opts":["Que ya no existe","Que es peligroso","Que hay muchos","Pequeño o querido"],"a":3},{"id":"lecB-4-019","topic":"reading","level":4,"type":"choice","q":"Un resumen cuenta solo las ideas más importantes de un texto. Verdadero o falso: un buen resumen incluye cada detalle pequeño.","why":"Un resumen deja los detalles pequeños y conserva solo las ideas principales.","hint":"¿Un resumen es corto o largo?","tags":[],"opts":["Verdadero","Falso"],"a":1},{"id":"lecB-4-020","topic":"reading","level":4,"type":"choice","q":"Los vientos de un huracán pueden arrancar techos. La lluvia fuerte inunda las calles y las olas gigantes inundan las costas. ¿Cuál es la idea principal?","why":"Las tres oraciones dan ejemplos de los daños que causa un huracán.","hint":"¿Qué tienen en común los tres ejemplos?","tags":["weather","ocean"],"opts":["Los huracanes causan daños graves","Los huracanes solo ocurren en invierno","Los techos son fáciles de arreglar","Las olas siempre son pequeñas"],"a":0},{"id":"lecB-5-001","topic":"reading","level":5,"type":"choice","q":"El estadio era un mar de gente. ¿Qué quiere decir esta metáfora?","why":"Un mar es enorme y lleno de olas. La metáfora dice que había muchísima gente, no agua.","hint":"¿Qué tiene de parecido un mar con una multitud?","tags":["baseball","ocean"],"opts":["Que el estadio tenía agua","Que había muchísima gente","Que la gente sabía nadar","Que el estadio era azul"],"a":1},{"id":"lecB-5-002","topic":"reading","level":5,"type":"choice","q":"En verano, la hormiga guardó comida mientras la cigarra solo cantaba. Llegó el invierno y la cigarra no tenía qué comer. ¿Qué enseña esta fábula?","why":"La hormiga se preparó y la cigarra no. La enseñanza es planear con anticipación.","hint":"¿Qué hizo distinto cada animal?","tags":["animals"],"opts":["Prepararse a tiempo","Cantar es malo","El invierno es corto","Las hormigas no cantan"],"a":0},{"id":"lecB-5-003","topic":"reading","level":5,"type":"number","q":"Un museo tiene 4 salas con 6 fósiles cada una. En el patio hay 3 fósiles más. Mandaron 5 fósiles a limpiar. ¿Cuántos fósiles quedan en exhibición?","why":"4 salas por 6 son 24 fósiles. Con los 3 del patio son 27. Si se van 5, quedan 22.","hint":"Multiplica, suma y al final resta.","tags":["dinosaurs"],"a":22},{"id":"lecB-5-004","topic":"reading","level":5,"type":"choice","q":"A mediodía un barco estaba sobre la arena seca. Seis horas después flotaba junto al muelle. ¿Qué pasó con el agua del mar?","why":"La marea sube y baja cada día. Al subir, el agua levantó el barco.","hint":"¿Qué podría levantar un barco de la arena seca?","tags":["ocean"],"opts":["Subió la marea","El barco se hundió","Llovió toda la noche","El muelle se movió"],"a":0},{"id":"lecB-5-005","topic":"reading","level":5,"type":"choice","q":"Los delfines usan chasquidos para encontrar a sus presas. Los murciélagos usan chillidos. Los dos usan el eco para ubicar su comida. ¿Qué estructura tiene el texto?","why":"El texto muestra en qué se parecen dos animales: los dos usan el eco.","hint":"¿Qué dos cosas se comparan?","tags":["ocean","animals"],"opts":["Problema y solución","Secuencia de pasos","Comparación","Descripción de un lugar"],"a":2},{"id":"lecB-5-006","topic":"reading","level":5,"type":"choice","q":"Los koalas comen hojas de eucalipto, que les dan poca energía. Por eso duermen muchas horas al día. Verdadero o falso: según el texto, los koalas duermen mucho porque su comida les da poca energía.","why":"El texto da la causa: las hojas dan poca energía, por eso duermen mucho.","hint":"Busca la expresión 'por eso'.","tags":["animals"],"opts":["Verdadero","Falso"],"a":0,"fun":true},{"id":"lecB-5-007","topic":"reading","level":5,"type":"choice","q":"Dos lectores opinan sobre el mismo cuento. Uno dice: 'Es lentísimo y aburrido'. La otra dice: 'Es tranquilo y se disfruta despacio'. ¿Qué se puede concluir?","why":"Uno ve lo lento como defecto y la otra como virtud, así que opinan distinto del mismo cuento.","hint":"¿Cada lector lo ve como bueno o como malo?","tags":[],"opts":["Uno de ellos inventó el cuento","Los dos odiaron el cuento","El cuento no existe","Tienen opiniones distintas"],"a":3},{"id":"lecB-5-008","topic":"reading","level":5,"type":"choice","q":"Un párrafo explica cómo los pájaros construyen nidos. ¿Qué oración NO pertenece al párrafo?","why":"El viaje al sur es otro tema. Las demás oraciones cuentan los pasos para hacer el nido.","hint":"¿Cuál oración habla de otra cosa?","tags":["animals"],"opts":["Primero juntan ramitas.","Luego las entretejen con hierba.","Algunos viajan al sur.","Por último, forran el nido con plumas."],"a":2},{"id":"lecB-5-009","topic":"reading","level":5,"type":"order","q":"Ordena estas palabras de lo más frío a lo más caliente.","why":"Cada palabra indica más calor que la anterior, hasta ardiente.","hint":"Imagina un cubo de hielo y luego una fogata.","tags":["weather"],"opts":["helado","fresco","tibio","ardiente"]},{"id":"lecB-5-010","topic":"reading","level":5,"type":"choice","q":"Mateo dijo: 'No me importa perder'. Pero se mordía las uñas durante todo el partido y apretaba su gorra. ¿Qué infiere el lector?","why":"Sus acciones dicen lo contrario de sus palabras: sí le importa, pero lo disimula.","hint":"Compara lo que dice con lo que hace.","tags":["baseball"],"opts":["Disimula cuánto le importa","Está muy tranquilo y relajado","Quiere irse a casa ya mismo","Se divierte mucho"],"a":0},{"id":"lecB-5-011","topic":"reading","level":5,"type":"choice","q":"Como llovió mucho, creció la hierba. Como creció la hierba, llegaron los conejos. Como llegaron los conejos, apareció el zorro. ¿Qué hizo aparecer directamente al zorro?","why":"El texto dice que el zorro apareció porque llegaron los conejos. Lo demás fueron causas anteriores.","hint":"Busca el eslabón justo antes del zorro.","tags":["animals"],"opts":["La lluvia","La hierba alta","Los conejos","La noche"],"a":2},{"id":"lecB-5-012","topic":"reading","level":5,"type":"choice","q":"Los gansos vuelan en forma de V. El ganso de adelante se cansa más, así que se turnan. Verdadero o falso: según el texto, el ganso de adelante se cansa menos que los demás.","why":"El texto dice que el de adelante se cansa más. Por eso se turnan.","hint":"Lee cuál ganso se cansa más.","tags":["animals"],"opts":["Verdadero","Falso"],"a":1},{"id":"lecB-5-013","topic":"reading","level":5,"type":"choice","q":"El paleontólogo era minucioso: limpiaba cada granito de polvo del hueso, uno por uno. ¿Qué significa 'minucioso'?","why":"Limpiar granito por granito demuestra que era muy cuidadoso.","hint":"¿Qué muestra hacerlo uno por uno?","tags":["dinosaurs"],"opts":["Muy rápido","Muy cuidadoso","Muy olvidadizo","Muy aburrido"],"a":1},{"id":"lecB-5-014","topic":"reading","level":5,"type":"choice","q":"Las hormigas viven en colonias. Cada una tiene un trabajo, como buscar comida o cuidar a las crías. Todas trabajan juntas para que la colonia sobreviva. ¿Cuál es el mejor resumen?","why":"El resumen reúne las ideas de las tres oraciones: colonias, trabajos y trabajo en equipo.","hint":"¿Qué opción cubre las tres oraciones?","tags":["animals"],"opts":["Las hormigas trabajan juntas en colonias","Las hormigas son los animales más fuertes","Las crías comen solo hojas","Las colonias viven en el mar"],"a":0},{"id":"lecB-5-015","topic":"reading","level":5,"type":"number","q":"Un poema tiene 4 estrofas. Cada estrofa tiene 3 versos, y cada verso tiene 5 palabras. ¿Cuántas palabras tiene el poema?","why":"4 estrofas de 3 versos son 12 versos. 12 versos de 5 palabras son 60 palabras.","hint":"Primero cuenta cuántos versos hay en total.","tags":[],"a":60},{"id":"lecB-5-016","topic":"reading","level":5,"type":"choice","q":"El entrenador dijo que el plan del corredor era 'audaz'. El árbitro dijo que era 'temerario'. ¿En qué se diferencian estas palabras?","why":"Audaz suena a elogio por atreverse. Temerario advierte que es imprudente.","hint":"¿Cada palabra suena a elogio o a advertencia?","tags":["baseball"],"opts":["Significan exactamente lo mismo en todo","Audaz es muy lento","Temerario es muy seguro","Audaz alaba, temerario advierte"],"a":3},{"id":"lecB-5-017","topic":"reading","level":5,"type":"choice","q":"Texto A: Las plantas fabrican su alimento con la luz del Sol. Texto B: Muchos animales se alimentan de plantas. ¿Qué idea muestran los dos textos juntos?","why":"Los animales comen plantas, y las plantas necesitan el Sol. Así que los animales dependen del Sol.","hint":"Une los dos textos en una cadena.","tags":["space","animals"],"opts":["Las plantas comen animales pequeños","El Sol es muy pequeño y lejano","Los animales dependen del Sol","Las plantas viven sin luz"],"a":2},{"id":"lecB-5-018","topic":"reading","level":5,"type":"choice","q":"El índice alfabético está al final de muchos libros y lista temas con las páginas donde aparecen. Verdadero o falso: para hallar dónde se habla de 'ballena', puedes buscar en la B del índice.","why":"El índice alfabético ordena los temas por letra, así que 'ballena' estará en la B.","hint":"¿Con qué letra empieza 'ballena'?","tags":["ocean"],"opts":["Verdadero","Falso"],"a":0},{"id":"lecB-5-019","topic":"reading","level":5,"type":"choice","q":"Ciertos pájaros se posan sobre los búfalos y comen los insectos de su piel. El búfalo se libra de los bichos y el pájaro encuentra comida. ¿Cómo es esta relación?","why":"El búfalo se limpia y el pájaro come. Cada uno obtiene algo bueno.","hint":"Pregunta qué obtiene cada uno.","tags":["animals"],"opts":["Solo gana el pájaro","Los dos salen ganando","Solo gana el búfalo","Nadie gana"],"a":1},{"id":"lecB-5-020","topic":"reading","level":5,"type":"choice","q":"Cuando empezó a llover en la última entrada, el entrenador sonrió y dijo: 'Al mal tiempo, buena cara'. ¿Qué quiso decir?","why":"El refrán aconseja mantener buen ánimo cuando las cosas se ponen difíciles.","hint":"Fíjate en que el entrenador sonrió.","tags":["baseball","weather"],"opts":["Cambiar de ropa mojada","Buscar otro lugar seco","Esperar a que pare la lluvia","Afrontar todo con ánimo"],"a":3},{"id":"lecB-6-001","topic":"reading","level":6,"type":"choice","q":"¿Cuál situación es irónica?","why":"La ironía es lo contrario de lo esperado. Un salvavidas debería ayudar a otros en el agua.","hint":"¿Cuál es lo contrario de lo que esperarías?","tags":["ocean"],"opts":["Un salvavidas que casi se ahoga","Un salvavidas que usa gorra","Un salvavidas que come helado","Un salvavidas muy alto"],"a":0},{"id":"lecB-6-002","topic":"reading","level":6,"type":"choice","q":"Afirmación: los arrecifes de coral son importantes para la vida marina. ¿Qué dato la apoya mejor?","why":"Una buena prueba conecta con la afirmación. Solo el último dato explica por qué los arrecifes ayudan a la vida marina.","hint":"¿Cuál dato habla de la VIDA marina?","tags":["ocean"],"opts":["El coral puede ser rosado o naranja","Algunos arrecifes están lejos de la costa","Los buzos usan aletas para verlos","Muchas especies hallan allí refugio"],"a":3},{"id":"lecB-6-003","topic":"reading","level":6,"type":"number","q":"Un barco de investigación navegó 4 días hasta un arrecife, se quedó allí el triple de días que navegó y volvió en 4 días. ¿Cuántos días duró todo el viaje?","why":"El triple de 4 días son 12 días en el arrecife. El viaje fue 4 más 12 más 4, que son 20 días.","hint":"Calcula primero cuántos días estuvo en el arrecife.","tags":["ocean"],"a":20},{"id":"lecB-6-004","topic":"reading","level":6,"type":"choice","q":"Si la marea no hubiera subido, el delfín varado no habría podido volver al mar. ¿Qué pasó en realidad?","why":"'Si no hubiera subido' quiere decir que sí subió. Por eso el delfín pudo volver al mar.","hint":"Dilo de nuevo como si fuera lo que realmente ocurrió.","tags":["ocean"],"opts":["La marea nunca subió esa tarde","La marea subió y lo liberó","El delfín jamás estuvo en la arena","El delfín tuvo que quedarse allí"],"a":1},{"id":"lecB-6-005","topic":"reading","level":6,"type":"choice","q":"El pronóstico era sombrío, pero la capitana se mantuvo serena y sonrió a su tripulación. ¿Qué significa 'sombrío'?","why":"La palabra 'pero' marca un contraste: el pronóstico era malo, aunque ella siguió serena.","hint":"¿Qué te indica la palabra 'pero'?","tags":["weather"],"opts":["Muy divertido para todos","Muy rápido y ligero","Oscuro y amenazante","Poco claro y confuso"],"a":2},{"id":"lecB-6-006","topic":"reading","level":6,"type":"choice","q":"La luz del Sol tarda unos ocho minutos en llegar a la Tierra. Verdadero o falso: cuando miras el Sol, lo ves como era hace unos ocho minutos.","why":"La luz necesita tiempo para viajar, así que la luz que ves salió del Sol unos ocho minutos antes.","hint":"La luz no viaja de forma instantánea.","tags":["space"],"opts":["Verdadero","Falso"],"a":0,"fun":true},{"id":"lecB-6-007","topic":"reading","level":6,"type":"choice","q":"Después de gritarle al árbitro, el jugador fue expulsado. Su entrenadora dijo: 'Quien siembra vientos, recoge tempestades'. ¿Qué quiso decir?","why":"Quien actúa mal recibe consecuencias, como una tormenta después de sembrar viento.","hint":"Relaciona la expulsión con el refrán.","tags":["baseball"],"opts":["Actuar mal trae consecuencias","Hay que sembrar más plantas en el jardín","El viento siempre ayuda a jugar mejor","Las tormentas son muy bonitas de ver"],"a":0},{"id":"lecB-6-008","topic":"reading","level":6,"type":"choice","q":"Un reporte dice que el equipo local 'ganó por un pelo'. Otro dice que 'aplastó' al rival. ¿Cuál reporte sugiere un juego cerrado?","why":"Ganar por un pelo quiere decir ganar por muy poco. Aplastar quiere decir ganar por mucho.","hint":"¿Cuál expresión significa por muy poco?","tags":["baseball"],"opts":["El que dice 'aplastó'","El que dice 'por un pelo'","Los dos reportes por igual","Ninguno de los dos reportes"],"a":1},{"id":"lecB-6-009","topic":"reading","level":6,"type":"order","q":"Ordena las oraciones para formar un párrafo claro.","why":"La idea general va primero, luego los ejemplos, y la conclusión que empieza con 'Por eso' va al final.","hint":"¿Qué oración presenta el tema y cuál lo cierra?","tags":["ocean","animals"],"opts":["Los delfines son animales muy inteligentes.","Por ejemplo, se reconocen con silbidos propios.","También cooperan para atrapar peces.","Por eso muchos científicos los estudian."]},{"id":"lecB-6-010","topic":"reading","level":6,"type":"choice","q":"Una vuelta de Venus sobre sí mismo tarda 243 días terrestres. Una vuelta de Venus alrededor del Sol tarda 225 días terrestres. ¿Cuál es más larga?","why":"243 es mayor que 225. Venus gira tan despacio que una vuelta sobre sí mismo dura más que un año suyo.","hint":"Compara los dos números con cuidado.","tags":["space"],"opts":["Una vuelta alrededor del Sol","Duran exactamente lo mismo","Una vuelta sobre sí mismo","No se puede saber"],"a":2,"fun":true},{"id":"lecB-6-011","topic":"reading","level":6,"type":"choice","q":"La majestuosa ballena saltó fuera del agua, y desde el barco contamos doce rociadas. ¿Qué palabra muestra la opinión del autor?","why":"'Majestuosa' es un juicio con el que alguien podría no estar de acuerdo. Las demás palabras se pueden comprobar.","hint":"¿Con cuál palabra podrían discrepar dos personas?","tags":["ocean"],"opts":["saltó","contamos","doce","majestuosa"],"a":3},{"id":"lecB-6-012","topic":"reading","level":6,"type":"choice","q":"Sara probó dos mangos verdes y los dos estaban agrios. Dijo: 'Todos los mangos verdes son agrios'. Verdadero o falso: dos mangos demuestran lo que dijo sobre todos los mangos verdes.","why":"Una muestra pequeña no prueba nada sobre todos. Es una generalización apresurada.","hint":"¿Dos mangos son todos los mangos del mundo?","tags":["food"],"opts":["Verdadero","Falso"],"a":1},{"id":"lecB-6-013","topic":"reading","level":6,"type":"choice","q":"Los Delfines ganaron 8 de 10 partidos. Los Halcones ganaron 7 de 8. ¿Qué equipo ganó una parte mayor de sus partidos?","why":"8 de 10 es 80 por ciento, pero 7 de 8 es 87,5 por ciento. Tener más victorias no significa una parte mayor.","hint":"Compara las partes, no el número de victorias.","tags":["baseball"],"opts":["Los Halcones","Los Delfines","Están empatados","No se puede saber"],"a":0},{"id":"lecB-6-014","topic":"reading","level":6,"type":"choice","q":"¿Cuál de estas palabras es esdrújula, es decir, tiene el golpe de voz en la antepenúltima sílaba?","why":"Mur-cié-la-go se acentúa en la antepenúltima sílaba (cié) y lleva tilde. Tiburón y delfín son agudas.","hint":"Cuenta tres sílabas desde el final de cada palabra.","tags":["animals"],"opts":["tiburón","murciélago","delfín","pulpo"],"a":1},{"id":"lecB-6-015","topic":"reading","level":6,"type":"number","q":"Cada fila de la tribuna de un estadio tiene 14 asientos. Llegan 100 aficionados. ¿Cuál es el menor número de filas necesarias para sentarlos a todos?","why":"7 filas solo sientan 98 aficionados. Los 2 que sobran necesitan una octava fila.","hint":"Divide y piensa qué hacer con los que sobran.","tags":["baseball"],"a":8},{"id":"lecB-6-016","topic":"reading","level":6,"type":"choice","q":"Un cuento empieza así: 'Era una noche sin Luna y sin viento'. ¿Qué crea el autor con esa frase?","why":"Una noche sin Luna ni viento crea un ambiente quieto y misterioso.","hint":"Imagina cómo se siente esa noche.","tags":[],"opts":["Una lista de datos","Un problema de sumas","Un ambiente de misterio","Una receta de cocina"],"a":2},{"id":"lecB-6-017","topic":"reading","level":6,"type":"choice","q":"Un libro se llama 'Las partes de un cohete'. Otro se llama 'Por qué debemos cuidar los océanos'. Verdadero o falso: el título 'Las partes de un cohete' sugiere que el autor quiere convencer.","why":"'Las partes de un cohete' suena a información. 'Debemos' en el otro título es señal de persuasión.","hint":"¿Cuál título dice lo que el lector debe hacer?","tags":["space","ocean"],"opts":["Verdadero","Falso"],"a":1},{"id":"lecB-6-018","topic":"reading","level":6,"type":"choice","q":"El árbitro vio que el corredor se adelantó de la base, pero hizo la vista gorda. ¿Qué hizo el árbitro?","why":"Hacer la vista gorda es un modismo: fingir que no se ha visto algo.","hint":"¿Importa la vista del árbitro o lo que decidió hacer?","tags":["baseball"],"opts":["Lo acusó enseguida","Perdió la vista","Lo miró con atención","Fingió no verlo"],"a":3},{"id":"lecB-6-019","topic":"reading","level":6,"type":"choice","q":"La mayoría de los pingüinos vive en lugares fríos, pero algunas especies viven en zonas cálidas, como las islas Galápagos. Verdadero o falso: existe al menos un tipo de pingüino que vive en clima cálido.","why":"El texto dice que algunas especies viven en zonas cálidas, así que al menos una existe.","hint":"¿Qué significa 'algunas especies'?","tags":["animals"],"opts":["Verdadero","Falso"],"a":0},{"id":"lecB-6-020","topic":"reading","level":6,"type":"choice","q":"Foto significa 'luz' y grafía significa 'escritura'. ¿Qué significa literalmente la palabra 'fotografía'?","why":"Foto es luz y grafía es escritura, así que fotografía es escribir o dibujar con luz.","hint":"Une el significado de las dos partes.","tags":[],"opts":["Escritura con luz","Luz de la Luna","Marco de madera","Libro de dibujos"],"a":0},{"id":"cieB-1-001","topic":"science","level":1,"type":"choice","q":"¿Cuál de estos tiburones tiene la cabeza con forma de martillo?","why":"Su cabeza ancha y plana parece un martillo. El tiburón ballena es gigante y el blanco tiene el hocico puntiagudo.","hint":"Piensa en la herramienta que sirve para clavar.","tags":["sharks"],"opts":["El tiburón de puntas negras","El tiburón martillo","El tiburón blanco gigante"],"a":1},{"id":"cieB-1-002","topic":"science","level":1,"type":"choice","q":"Las ballenas son un tipo de pez.","why":"Las ballenas son mamíferos: respiran aire con pulmones y alimentan a sus crías con leche.","hint":"¿Respiran aire o respiran agua?","tags":["ocean"],"opts":["Verdadero","Falso"],"a":1},{"id":"cieB-1-003","topic":"science","level":1,"type":"choice","q":"¿Cuál de estos dinosaurios tenía un cuello larguísimo para alcanzar las hojas más altas?","why":"El braquiosaurio era un gigante herbívoro de cuello largo. El tiranosaurio cazaba y el triceratops tenía tres cuernos.","hint":"Piensa en una jirafa gigante de la prehistoria.","tags":["dinosaurs"],"opts":["Tiranosaurio rex","Triceratops cornudo","Braquiosaurio"],"a":2},{"id":"cieB-1-004","topic":"science","level":1,"type":"number","q":"¿Cuántas patas tiene una araña?","why":"Las arañas tienen 8 patas. Los insectos solo tienen 6, así que las arañas no son insectos.","hint":"Cuenta los pares de patas: son cuatro pares.","tags":["animals"],"a":8},{"id":"cieB-1-005","topic":"science","level":1,"type":"choice","q":"¿Qué parte del cuerpo manda mensajes a todos lados y te permite pensar?","why":"El cerebro controla lo que piensas y cómo se mueve tu cuerpo. El estómago digiere y el corazón bombea sangre.","hint":"Está protegido dentro de tu cabeza.","tags":["body"],"opts":["El cerebro","El estómago","El corazón"],"a":0},{"id":"cieB-1-006","topic":"science","level":1,"type":"choice","q":"¿Cuál es el planeta más grande del sistema solar?","why":"Júpiter es tan grande que cabrían más de mil Tierras dentro de él. Marte es más pequeño que la Tierra.","hint":"Es un planeta gigante hecho de gas.","tags":["space"],"opts":["La Tierra","Marte","Júpiter"],"a":2},{"id":"cieB-1-007","topic":"science","level":1,"type":"order","q":"Ordena el día según se mueve el Sol por el cielo.","why":"El Sol sale por la mañana, está más alto al mediodía y se esconde al atardecer. Luego llega la noche.","hint":"Empieza cuando el Sol asoma por el horizonte.","tags":["space"],"opts":["Amanecer","Mediodía","Atardecer","Noche"]},{"id":"cieB-1-008","topic":"science","level":1,"type":"choice","q":"Las mariposas pueden saborear con las patas.","why":"Tienen sensores de sabor en las patas. Al posarse en una hoja, saben si sirve para poner sus huevos.","hint":"Piensa en dónde se posa una mariposa.","tags":["animals"],"opts":["Verdadero","Falso"],"a":0,"fun":true},{"id":"cieB-1-009","topic":"science","level":1,"type":"choice","q":"¿Qué herramienta te dice cuánto calor o frío hace?","why":"El termómetro mide la temperatura. La regla mide el largo de las cosas y el reloj marca la hora.","hint":"Los meteorólogos la leen para decir la temperatura.","tags":["weather"],"opts":["Un termómetro","Una regla larga","Un reloj de pared"],"a":0},{"id":"cieB-1-010","topic":"science","level":1,"type":"choice","q":"¿Cuál de estos es un gas?","why":"Un gas se esparce y llena todo el espacio que tiene. La leche es líquida y el hielo es sólido.","hint":"Un gas no tiene forma propia.","tags":[],"opts":["La leche de un vaso grande","El aire dentro de un globo","Un cubito de hielo duro"],"a":1},{"id":"cieB-1-011","topic":"science","level":1,"type":"order","q":"Ordena la vida de una tortuga marina, desde el principio.","why":"La mamá tortuga pone huevos en la arena. Las crías nacen, corren al agua y crecen en el mar.","hint":"Las tortugas marinas empiezan su vida en tierra.","tags":["ocean"],"opts":["Huevo en la playa","La cría camina al mar","Tortuga joven nada","Tortuga adulta"]},{"id":"cieB-1-012","topic":"science","level":1,"type":"choice","q":"Un bateador golpea la pelota. ¿Qué hace el bate con la pelota?","why":"El bate empuja la pelota y la manda lejos. Jalar sería traerla hacia ti.","hint":"Piensa en cómo sale volando la pelota.","tags":["baseball"],"opts":["La empuja","La jala","La mantiene quieta"],"a":0},{"id":"cieB-1-013","topic":"science","level":1,"type":"choice","q":"¿Qué usan las plantas para fabricar su alimento?","why":"Las plantas usan luz del Sol, agua y aire para hacer su propio alimento. Por eso crecen hacia las ventanas.","hint":"Las plantas se inclinan hacia la ventana.","tags":[],"opts":["El sonido del viento","La luz del Sol","La sombra de la noche"],"a":1},{"id":"cieB-1-014","topic":"science","level":1,"type":"choice","q":"¿Cuál de estos animales marinos tiene caparazón duro y camina de lado?","why":"El cangrejo tiene caparazón duro y patas dobladas, por eso camina de lado. La medusa es blandita y el delfín nada.","hint":"Vive cerca de las rocas y tiene pinzas.","tags":["ocean"],"opts":["La medusa transparente","El delfín saltarín","El cangrejo"],"a":2},{"id":"cieB-1-015","topic":"science","level":1,"type":"choice","q":"Una sombra se forma cuando un objeto tapa algo. ¿Qué tapa?","why":"La sombra es una zona oscura a la que no llega la luz porque un objeto la bloquea.","hint":"Las sombras se ven en los días de sol.","tags":[],"opts":["El sonido","El viento","La luz"],"a":2},{"id":"cieB-1-016","topic":"science","level":1,"type":"choice","q":"¿Cómo se llama la roca caliente y derretida que sale de un volcán?","why":"La lava es roca derretida del interior de la Tierra. Al enfriarse, se vuelve roca dura otra vez.","hint":"Brilla con colores rojo y naranja.","tags":[],"opts":["Lava","Vapor","Nieve"],"a":0},{"id":"cieB-1-017","topic":"science","level":1,"type":"choice","q":"¿Qué cubre todo tu cuerpo por fuera para protegerlo?","why":"La piel es el órgano más grande del cuerpo. Evita que entren microbios. Los huesos y los músculos están por dentro.","hint":"Es lo que ves y tocas de tu cuerpo.","tags":["body"],"opts":["Los huesos","La piel","Los músculos"],"a":1},{"id":"cieB-1-018","topic":"science","level":1,"type":"choice","q":"¿Qué planeta es famoso por sus anillos grandes y brillantes?","why":"Los anillos de Saturno están hechos de trocitos de hielo y roca. Marte y Venus no tienen anillos.","hint":"Es un planeta gigante, lejos del Sol.","tags":["space"],"opts":["Marte","Saturno","Venus"],"a":1},{"id":"cieB-1-019","topic":"science","level":1,"type":"choice","q":"¿Cuál de estos animales marinos suelta una nube de tinta para escapar?","why":"El calamar lanza tinta para confundir a sus enemigos y huir. La estrella de mar y el caballito se mueven despacio.","hint":"Tiene tentáculos y nada en el mar abierto.","tags":["ocean"],"opts":["La estrella de mar","El caballito de mar","El calamar"],"a":2},{"id":"cieB-1-020","topic":"science","level":1,"type":"choice","q":"¿Cuál de estos animales es un mamífero que sí puede volar?","why":"El murciélago es el único mamífero que vuela de verdad. El búho es un ave y la libélula es un insecto.","hint":"Tiene pelo y sale de noche.","tags":["animals"],"opts":["El murciélago","El búho","La libélula"],"a":0,"fun":true},{"id":"cieB-2-001","topic":"science","level":2,"type":"choice","q":"Un tiburón puede sentir las ondas que hace un pez al nadar cerca de él.","why":"Una línea de sensores a lo largo de su cuerpo, la línea lateral, siente las ondas del agua y le indica dónde está la presa.","hint":"Los tiburones cazan incluso en aguas turbias.","tags":["sharks"],"opts":["Verdadero","Falso"],"a":0},{"id":"cieB-2-002","topic":"science","level":2,"type":"choice","q":"¿Qué dientes le dirían a un científico que un dinosaurio comía carne?","why":"Los dientes afilados y curvos cortan la carne. Los dientes planos sirven para moler hojas y otras plantas.","hint":"Piensa en qué necesita un diente para cortar.","tags":["dinosaurs"],"opts":["Dientes anchos y planos para moler","Dientes afilados y puntiagudos","Dientes pequeños y muy redondos"],"a":1},{"id":"cieB-2-003","topic":"science","level":2,"type":"choice","q":"Algunos dinosaurios se echaban sobre sus huevos en el nido, igual que las aves.","why":"Hay fósiles de pequeños dinosaurios acurrucados sobre sus huevos para darles calor. Las aves son parientes vivos de los dinosaurios.","hint":"Piensa en lo que hacen las gallinas con sus huevos.","tags":["dinosaurs"],"opts":["Verdadero","Falso"],"a":0,"fun":true},{"id":"cieB-2-004","topic":"science","level":2,"type":"choice","q":"Hace mucho, la gente unía estrellas para formar dibujos, como un cazador o un oso. ¿Cómo se llaman?","why":"Una constelación es un grupo de estrellas que imaginamos como un dibujo. Los cometas son viajeros helados del espacio.","hint":"Es una palabra que empieza con 'cons'.","tags":["space"],"opts":["Estrellas fugaces","Órbitas planetarias","Constelaciones"],"a":2},{"id":"cieB-2-005","topic":"science","level":2,"type":"choice","q":"¿Qué instrumento muestra hacia dónde sopla el viento?","why":"La veleta gira y señala de dónde viene el viento. El pluviómetro mide la lluvia y la balanza mide el peso.","hint":"Suele estar en lo alto de un tejado.","tags":["weather"],"opts":["Una veleta","Un pluviómetro","Una balanza"],"a":0},{"id":"cieB-2-006","topic":"science","level":2,"type":"choice","q":"¿Cuál de estos casos muestra un líquido que se vuelve sólido?","why":"Al enfriarse mucho, el agua se vuelve hielo, que es sólido. Derretir y hervir son los cambios contrarios.","hint":"Busca el cambio que ocurre con mucho frío.","tags":[],"opts":["Un hielo que se derrite al sol","Agua que hierve en una olla","Agua del charco que se congela"],"a":2},{"id":"cieB-2-007","topic":"science","level":2,"type":"choice","q":"¿Por qué es más fácil mover una caja pesada con ruedas que arrastrarla?","why":"Las ruedas ruedan en vez de rozar, así que hay menos fricción. La caja pesa lo mismo y la gravedad sigue igual.","hint":"Piensa en lo que pasa cuando algo roza el suelo.","tags":["machines"],"opts":["Las ruedas rozan menos con el suelo","Las ruedas hacen la caja más liviana","Las ruedas quitan la gravedad"],"a":0},{"id":"cieB-2-008","topic":"science","level":2,"type":"choice","q":"¿Por qué el guante de un receptor de béisbol tiene mucho relleno?","why":"El relleno amortigua el golpe de un lanzamiento veloz para que no duela tanto. No cambia el peso de la pelota.","hint":"Piensa en cómo se siente una pelota rápida en la mano.","tags":["baseball"],"opts":["Hace que la pelota pese mucho menos","Suaviza el golpe de la pelota rápida","Hace que la pelota rebote más fuerte"],"a":1},{"id":"cieB-2-009","topic":"science","level":2,"type":"choice","q":"En la rodilla y el codo se unen dos huesos y puedes doblarlos. ¿Cómo se llama ese lugar?","why":"Las articulaciones unen los huesos y les permiten moverse. Las costillas son huesos del pecho y los nervios llevan mensajes.","hint":"Sin ellas, tus piernas no se doblarían.","tags":["body"],"opts":["Articulación","Costilla","Nervio"],"a":0},{"id":"cieB-2-010","topic":"science","level":2,"type":"choice","q":"¿Qué parte de una planta lleva el agua desde las raíces hacia arriba?","why":"El tallo funciona como un popote: sube el agua y los minerales hasta las hojas.","hint":"Piensa en un popote dentro de un vaso.","tags":[],"opts":["La flor","El tallo","La semilla"],"a":1},{"id":"cieB-2-011","topic":"science","level":2,"type":"choice","q":"Un omnívoro come plantas y también animales. ¿Cuál de estos es omnívoro?","why":"Los osos comen frutos, raíces, peces y más. Las vacas solo comen plantas y los leones solo comen carne.","hint":"Busca el animal con el menú más variado.","tags":["animals"],"opts":["La vaca","El león","El oso"],"a":2},{"id":"cieB-2-012","topic":"science","level":2,"type":"choice","q":"¿Cómo respira aire un delfín?","why":"Los delfines son mamíferos con pulmones. Suben a la superficie y respiran por un orificio en la cabeza.","hint":"Los delfines son mamíferos, no peces.","tags":["ocean"],"opts":["Con branquias a los costados","Con la boca, bajo el agua","Por un orificio de la cabeza"],"a":2},{"id":"cieB-2-013","topic":"science","level":2,"type":"choice","q":"¿Qué animal tiene huellas dactilares casi iguales a las de las personas?","why":"Las yemas de los koalas tienen crestas tan parecidas a las nuestras que ni con un microscopio es fácil distinguirlas.","hint":"Piensa en un animal que se agarra de las ramas con las patas.","tags":["animals"],"opts":["El koala","El canguro","El pingüino"],"a":0,"fun":true},{"id":"cieB-2-014","topic":"science","level":2,"type":"choice","q":"La luz del Sol pasa por gotas de lluvia y forma un arcoíris. ¿Qué nos muestra?","why":"Las gotas separan la luz blanca en sus colores: rojo, naranja, amarillo, verde, azul y violeta.","hint":"Los colores vienen de la luz misma.","tags":["weather"],"opts":["Que las gotas son de colores por dentro","Que la luz blanca mezcla muchos colores","Que las nubes guardan colores"],"a":1},{"id":"cieB-2-015","topic":"science","level":2,"type":"choice","q":"Golpeas un tambor grande y uno pequeño. ¿Cuál suena más grave?","why":"Lo grande vibra más despacio, y las vibraciones lentas dan sonidos graves. Los tambores pequeños suenan más agudos.","hint":"Piensa en un 'bum' profundo y en un 'tac' ligero.","tags":[],"opts":["El tambor pequeño","El tambor grande","Suenan exactamente igual"],"a":1},{"id":"cieB-2-016","topic":"science","level":2,"type":"order","q":"Ordena del más pequeño al más grande.","why":"La Luna es más pequeña que la Tierra. Júpiter es mucho mayor que la Tierra, pero el Sol es muchísimo mayor que Júpiter.","hint":"Empieza por lo que gira alrededor de la Tierra.","tags":["space"],"opts":["Luna","Tierra","Júpiter","Sol"]},{"id":"cieB-2-017","topic":"science","level":2,"type":"number","q":"¿En cuántos días, más o menos, da la Tierra una vuelta completa al Sol?","why":"Una vuelta al Sol dura unos 365 días. A esa vuelta la llamamos un año.","hint":"Es la cantidad de días que tiene un año.","tags":["space"],"a":365},{"id":"cieB-2-018","topic":"science","level":2,"type":"choice","q":"El aire caliente sube sobre el aire frío, y eso ayuda a flotar a los globos aerostáticos.","why":"El aire caliente pesa menos que el aire frío que lo rodea, así que sube y levanta el globo.","hint":"Piensa en lo que hace el quemador con el aire.","tags":["weather"],"opts":["Verdadero","Falso"],"a":0},{"id":"cieB-2-019","topic":"science","level":2,"type":"choice","q":"Un modelo de puente se cae durante una prueba. ¿Qué debe hacer después una ingeniera?","why":"Los ingenieros aprenden de las pruebas que fallan. Arreglan el punto débil y lo intentan otra vez hasta que funcione.","hint":"Los fallos dan pistas para mejorar el diseño.","tags":["machines"],"opts":["Construir el puente real igual","Decidir que los puentes no funcionan","Mejorar lo débil y probar de nuevo"],"a":2},{"id":"cieB-2-020","topic":"science","level":2,"type":"choice","q":"¿Qué animal marino puede hacer una perla dentro de su concha?","why":"La ostra cubre un granito con capas lisas, y con el tiempo se convierte en una perla.","hint":"Tiene dos conchas que se abren y se cierran.","tags":["ocean"],"opts":["La ostra","El cangrejo","La estrella de mar"],"a":0},{"id":"cieB-3-001","topic":"science","level":3,"type":"choice","q":"Un tiburón huele una gota de sangre en muchísima agua. ¿Con qué huele?","why":"El agua entra por las fosas nasales del tiburón, y una gran parte de su cerebro se dedica al olfato.","hint":"El olfato está en la parte delantera de la cabeza.","tags":["sharks"],"opts":["Con agujeritos de las aletas","Con las ranuras de las branquias","Con las fosas nasales del hocico","Con las filas de dientes"],"a":2},{"id":"cieB-3-002","topic":"science","level":3,"type":"choice","q":"El pteranodon volaba por el cielo en la época de los dinosaurios. ¿Qué animal era?","why":"Los pterosaurios, como el pteranodon, eran reptiles voladores. Vivieron junto a los dinosaurios, pero no eran dinosaurios.","hint":"Sus alas eran de piel, no de plumas.","tags":["dinosaurs"],"opts":["Un reptil volador","Un dinosaurio con plumas","Un murciélago gigante","Un ave muy antigua"],"a":0},{"id":"cieB-3-003","topic":"science","level":3,"type":"choice","q":"Los cohetes queman combustible para volar. ¿Por qué un cohete lleva su propio oxígeno al espacio?","why":"El fuego necesita oxígeno y en el espacio casi no hay. Por eso los cohetes llevan oxígeno junto con el combustible.","hint":"Piensa en lo que necesita un fuego para arder.","tags":["space"],"opts":["Porque el oxígeno de la Tierra pesa demasiado","Porque el combustible se congelaría sin él","Porque el motor se calentaría demasiado","Porque en el espacio casi no hay aire"],"a":3},{"id":"cieB-3-004","topic":"science","level":3,"type":"number","q":"Imagina 6 estrellas de mar con 5 brazos cada una. ¿Cuántos brazos hay en total?","why":"Seis estrellas con 5 brazos cada una dan 6 x 5 = 30 brazos.","hint":"Cuenta de cinco en cinco.","tags":["ocean"],"a":30},{"id":"cieB-3-005","topic":"science","level":3,"type":"choice","q":"Una lagartija se calienta el cuerpo tomando el sol.","why":"Las lagartijas producen poco calor propio, así que toman el sol para calentarse y buscan sombra cuando tienen demasiado calor.","hint":"Piensa en dónde ves lagartijas por la mañana.","tags":["animals"],"opts":["Verdadero","Falso"],"a":0},{"id":"cieB-3-006","topic":"science","level":3,"type":"choice","q":"¿Qué produce el fuerte estruendo de un trueno?","why":"El rayo calienta el aire tan rápido que este se expande de golpe y suena el estruendo. Las nubes no chocan.","hint":"El trueno llega siempre después de algo que ves.","tags":["weather"],"opts":["Las nubes grandes que chocan entre sí","El aire que el rayo calienta de golpe","La lluvia fuerte que cae del cielo","El viento que sopla entre las montañas"],"a":1},{"id":"cieB-3-007","topic":"science","level":3,"type":"choice","q":"¿A cuál de estos objetos NO se pega un imán?","why":"Los imanes atraen el hierro y el acero. El aluminio, el plástico y la madera no son magnéticos.","hint":"¿Cuál no es de hierro ni de acero?","tags":[],"opts":["A un clavo largo de hierro","A un clip de acero","A una olla de hierro","A una lata de aluminio"],"a":3},{"id":"cieB-3-008","topic":"science","level":3,"type":"choice","q":"Un hacha parte un tronco empujando la madera hacia los lados. ¿Qué máquina simple es su filo?","why":"La cuña es delgada en un borde y ancha en el otro, y convierte un empuje hacia abajo en uno hacia los lados.","hint":"Piensa en la forma de un tope de puerta.","tags":["machines"],"opts":["Una polea","Una cuña","Una palanca","Una rueda con eje"],"a":1},{"id":"cieB-3-009","topic":"science","level":3,"type":"choice","q":"Un swing fuerte manda la pelota mucho más lejos que un toque suave. ¿Por qué?","why":"Un golpe más fuerte le da a la pelota más rapidez y energía, y por eso llega más lejos. Su peso no cambia.","hint":"Piensa en qué tan grande es el empuje.","tags":["baseball"],"opts":["Un empuje más grande le da más rapidez","La pelota pesa menos tras un golpe fuerte","El toque suave aumenta la gravedad","El swing fuerte aparta todo el aire"],"a":0},{"id":"cieB-3-010","topic":"science","level":3,"type":"choice","q":"¿Qué parte del esqueleto funciona como una jaula que protege el corazón y los pulmones?","why":"Tus costillas se curvan alrededor del pecho como una jaula. El cráneo protege el cerebro y la columna protege los nervios.","hint":"Puedes sentirlas en tu pecho.","tags":["body"],"opts":["La columna vertebral","El cráneo","Las costillas","La cadera"],"a":2},{"id":"cieB-3-011","topic":"science","level":3,"type":"choice","q":"Los tiburones y otros buenos nadadores tienen cuerpos lisos y alargados. ¿Cómo les ayuda esa forma?","why":"Una forma lisa y alargada ofrece menos resistencia, así que gastan menos energía al nadar rápido.","hint":"Piensa en cómo una lancha puntiaguda corta las olas.","tags":["sharks","ocean"],"opts":["Les ayuda a flotar hacia arriba","El agua resbala a su alrededor","Evita que entre agua a su cuerpo","Los hace pesar mucho menos"],"a":1},{"id":"cieB-3-012","topic":"science","level":3,"type":"order","q":"Ordena los pasos de cómo se forma un fósil de dinosaurio.","why":"Si un animal queda enterrado pronto, sus huesos se protegen. Con millones de años, los minerales los endurecen hasta volverlos piedra.","hint":"El fósil debe existir antes de que alguien lo encuentre.","tags":["dinosaurs"],"opts":["Un animal muere y queda enterrado","Arena y lodo se amontonan encima","Los minerales convierten el hueso en roca","Alguien desentierra el fósil"]},{"id":"cieB-3-013","topic":"science","level":3,"type":"choice","q":"Una estrella de mar puede volver a hacer crecer un brazo que perdió.","why":"Muchas estrellas de mar regeneran sus brazos. Algunas especies hasta forman un cuerpo nuevo a partir de un solo brazo.","hint":"Los animales marinos tienen trucos para curarse.","tags":["ocean"],"opts":["Verdadero","Falso"],"a":0},{"id":"cieB-3-014","topic":"science","level":3,"type":"choice","q":"Las hojas son verdes porque tienen un material verde que atrapa la luz del Sol. ¿Cómo se llama?","why":"La clorofila absorbe la luz del Sol para que la hoja haga alimento. En otoño se descompone y aparecen otros colores.","hint":"Su nombre viene de una palabra griega que significa verde.","tags":[],"opts":["Polen de flor","Néctar dulce","Savia espesa","Clorofila"],"a":3},{"id":"cieB-3-015","topic":"science","level":3,"type":"choice","q":"El pez loro raspa algas de los corales con sus dientes duros como pico. ¿En qué se convierte parte de lo que expulsa?","why":"El pez loro muele trocitos de coral y lo que expulsa se vuelve arena. Un solo pez puede hacer toneladas al año.","hint":"Piensa en de qué está hecha una playa.","tags":["ocean"],"opts":["En perlas diminutas y lisas","En cristales de sal gruesa","En arena fina y blanca","En nuevos arrecifes enteros"],"a":2,"fun":true},{"id":"cieB-3-016","topic":"science","level":3,"type":"choice","q":"Una ventana de vidrio limpio deja pasar la luz sin problema. ¿Cómo se llama ese tipo de material?","why":"Un material transparente deja pasar la luz y se ve claro a través de él. Uno opaco bloquea la luz por completo.","hint":"Empieza con 'trans', que significa a través.","tags":[],"opts":["Transparente","Opaco","Reflectante","Magnético"],"a":0},{"id":"cieB-3-017","topic":"science","level":3,"type":"choice","q":"Gritas en un cañón y un instante después oyes tu voz otra vez. ¿Qué es eso?","why":"El eco es sonido que rebota en una superficie dura y regresa hasta ti.","hint":"El sonido debe volver desde algún lugar.","tags":[],"opts":["Sonido que se vuelve un rayo de luz","El viento repitiendo tus palabras","Sonido que rebota en algo duro","Tus oídos haciendo un ruido propio"],"a":2},{"id":"cieB-3-018","topic":"science","level":3,"type":"choice","q":"La primera versión de prueba de un invento nuevo se llama...","why":"Los ingenieros hacen un prototipo para probar su idea y mejorarla antes de hacer la versión final.","hint":"Es el primer modelo que se hace para probar.","tags":["machines"],"opts":["Prototipo","Hipótesis","Ecosistema","Eclipse"],"a":0},{"id":"cieB-3-019","topic":"science","level":3,"type":"choice","q":"Una medusa no tiene cerebro, ni corazón, ni huesos.","why":"Casi todo el cuerpo de una medusa es agua. Una red de nervios le permite sentir y el cuerpo mueve el agua sin corazón.","hint":"Las medusas son animales muy sencillos.","tags":["ocean"],"opts":["Verdadero","Falso"],"a":0,"fun":true},{"id":"cieB-3-020","topic":"science","level":3,"type":"choice","q":"Durante un eclipse solar, el Sol parece desaparecer unos minutos. ¿Qué ocurre?","why":"La Luna se coloca frente al Sol y bloquea su luz. La sombra de la Tierra causa un eclipse de Luna.","hint":"Algo grande se pone en el camino de la luz.","tags":["space"],"opts":["La sombra de la Tierra tapa al Sol","El Sol deja de brillar un rato","Una nube gigante cruza frente al Sol","La Luna se pone frente al Sol"],"a":3},{"id":"cieB-4-001","topic":"science","level":4,"type":"choice","q":"Un tiburón martillo mueve su cabeza ancha de un lado a otro sobre la arena. ¿Qué está haciendo, muy probablemente?","why":"La cabeza ancha tiene sensores muy separados. Al barrer la arena, detecta rayas enterradas.","hint":"Piensa en por qué ayudan unos sensores muy separados.","tags":["sharks"],"opts":["Limpiándose las branquias","Cavando un nido para sus huevos","Buscando presas escondidas","Buscando un lugar para dormir"],"a":2},{"id":"cieB-4-002","topic":"science","level":4,"type":"choice","q":"Los excrementos fósiles de dinosaurio se llaman coprolitos. ¿Qué pueden descubrir los científicos con ellos?","why":"Los coprolitos pueden tener trocitos de hueso, semillas o fibras de plantas. Esas pistas muestran lo que comió.","hint":"Piensa en lo que sale después de una comida.","tags":["dinosaurs"],"opts":["Qué comía el dinosaurio","Qué tan fuerte rugía","De qué color era su piel","Qué tan rápido corría"],"a":0,"fun":true},{"id":"cieB-4-003","topic":"science","level":4,"type":"choice","q":"¿Cuántas Tierras cabrían dentro del Sol, más o menos?","why":"El Sol es enorme: cabrían como 1,3 millones de Tierras, aunque desde lejos se vea pequeño.","hint":"Al lado del Sol, la Tierra parece una canica.","tags":["space"],"opts":["Unas mil","Unas diez mil","Unos cientos de miles","Más de un millón"],"a":3},{"id":"cieB-4-004","topic":"science","level":4,"type":"number","q":"Imagina que un arrecife de coral crece 3 centímetros por año. ¿Cuántos centímetros crece en 10 años?","why":"El crecimiento se suma cada año: 3 cm x 10 años = 30 cm. Los arrecifes crecen despacio, por eso los grandes son muy antiguos.","hint":"Multiplica el crecimiento anual por los años.","tags":["ocean"],"a":30},{"id":"cieB-4-005","topic":"science","level":4,"type":"choice","q":"La corteza de la Tierra está rota en enormes piezas que se mueven muy despacio. ¿Cómo se llaman?","why":"Las placas se mueven unos centímetros al año. Donde chocan o se deslizan puede haber terremotos y volcanes.","hint":"Esas piezas encajan como un rompecabezas gigante.","tags":[],"opts":["Tubos de lava","Placas tectónicas","Corrientes marinas","Cámaras de magma"],"a":1},{"id":"cieB-4-006","topic":"science","level":4,"type":"choice","q":"¿Cuál de estas frases habla del clima y no del tiempo de un día?","why":"El tiempo es lo que pasa en el cielo un día cualquiera. El clima es el patrón habitual a lo largo de muchos años.","hint":"El clima describe lo que ocurre año tras año.","tags":["weather"],"opts":["Hoy llovió en la ciudad por la mañana","Esta tarde sopló un viento muy fuerte","Anoche cayó nieve en el cerro","Aquí los veranos son secos cada año"],"a":3},{"id":"cieB-4-007","topic":"science","level":4,"type":"choice","q":"Revuelves azúcar en agua tibia y parece desaparecer. ¿Dónde está el azúcar?","why":"El azúcar se disuelve: sus trocitos diminutos se reparten por el agua. Si pruebas el agua, todavía sabe dulce.","hint":"Si pruebas el agua, lo sabrás.","tags":["food"],"opts":["Se convirtió en más agua del vaso","Se mezcló en trocitos invisibles","Se destruyó y ya no existe más","Se hundió y quedó escondida abajo"],"a":1},{"id":"cieB-4-008","topic":"science","level":4,"type":"choice","q":"Una cuerda pasa por una rueda en lo alto de un asta de bandera. ¿Para qué sirve esta polea?","why":"Una polea fija solo cambia la dirección del jalón. No reduce el peso ni la fuerza que necesitas.","hint":"Piensa hacia dónde se mueven tus manos.","tags":["machines"],"opts":["Para subir la bandera jalando abajo","Para que la bandera pese menos","Para subir la bandera con media fuerza","Para que la cuerda sea más larga"],"a":0},{"id":"cieB-4-009","topic":"science","level":4,"type":"choice","q":"Una pelota de béisbol rueda y cae de una mesa. Mientras cae, va cada vez más rápido. ¿Por qué?","why":"La gravedad jala todo el tiempo que la pelota cae, así que su rapidez aumenta. Su peso no cambia.","hint":"Una fuerza actúa durante toda la caída.","tags":["baseball"],"opts":["El aire la empuja con fuerza desde arriba","La pelota se vuelve más pesada al caer","La gravedad sigue jalándola hacia abajo","Su giro le va sumando más rapidez"],"a":2},{"id":"cieB-4-010","topic":"science","level":4,"type":"choice","q":"Con mucha luz, el centro oscuro de tu ojo se hace más pequeño. ¿Cómo se llama ese centro?","why":"La pupila es la abertura por donde entra la luz. El iris es el anillo de color que la agranda o la achica.","hint":"Es un agujero, no un anillo.","tags":["body"],"opts":["El iris","La pupila","El cristalino","El párpado"],"a":1},{"id":"cieB-4-011","topic":"science","level":4,"type":"choice","q":"Las algas crecen cerca de la superficie del mar, pero no en el fondo profundo. ¿Por qué?","why":"Las algas necesitan luz para hacer su alimento, y la luz se apaga con la profundidad. Muy abajo todo está oscuro.","hint":"¿Qué necesitan las plantas para hacer su alimento?","tags":["ocean"],"opts":["El agua profunda es demasiado salada","Las olas son muy fuertes allá abajo","Los peces se comen todas las algas allí","El Sol no ilumina las aguas profundas"],"a":3},{"id":"cieB-4-012","topic":"science","level":4,"type":"order","q":"Ordena según cuándo aparecieron por primera vez en la Tierra, de lo más antiguo a lo más reciente.","why":"Trilobites: hace más de 500 millones de años. Tiburones: unos 450 millones. Dinosaurios: unos 230 millones. Humanos actuales: unos 300 000.","hint":"Los dinosaurios llegaron mucho después de los primeros tiburones.","tags":["sharks","dinosaurs"],"opts":["Trilobites","Tiburones","Dinosaurios","Seres humanos"]},{"id":"cieB-4-013","topic":"science","level":4,"type":"choice","q":"Las nutrias marinas a veces se toman de las patas al dormir para no separarse.","why":"Duermen flotando sobre el agua y se agarran de las patas o se envuelven en algas para quedar juntas.","hint":"Piensa en lo que preocupa a un animal que flota dormido.","tags":["ocean"],"opts":["Verdadero","Falso"],"a":0,"fun":true},{"id":"cieB-4-014","topic":"science","level":4,"type":"choice","q":"Un popote en un vaso con agua parece torcido en la superficie del agua. ¿Por qué?","why":"La luz se desvía al pasar del agua al aire; eso se llama refracción. El popote sigue derecho.","hint":"Saca el popote y míralo otra vez.","tags":[],"opts":["El popote sí se dobla en el agua","El agua calienta el popote a medias","La luz se desvía entre agua y aire","El vaso aprieta el popote hacia un lado"],"a":2},{"id":"cieB-4-015","topic":"science","level":4,"type":"choice","q":"Golpeas un tambor con más fuerza. ¿Por qué suena más fuerte?","why":"Un golpe más fuerte produce vibraciones más grandes, y las vibraciones grandes dan sonidos fuertes. La rapidez del sonido no cambia.","hint":"Piensa en cuánto se mueve la piel del tambor.","tags":[],"opts":["La piel vibra con movimientos más grandes","El sonido viaja mucho más rápido","El tambor se vuelve más pesado","El aire a su alrededor se espesa"],"a":0},{"id":"cieB-4-016","topic":"science","level":4,"type":"choice","q":"Una ingeniera quiere un armazón de puente más fuerte. ¿Qué forma le da más resistencia?","why":"Los triángulos no se deforman con facilidad, por eso los puentes y las torres los usan por todas partes.","hint":"Mira las estructuras de metal de los puentes grandes.","tags":["machines"],"opts":["Los círculos","Las líneas onduladas","Los triángulos","Los lazos sueltos"],"a":2},{"id":"cieB-4-017","topic":"science","level":4,"type":"choice","q":"Los hongos y las bacterias descomponen las hojas caídas del bosque. ¿Qué logran con esto?","why":"Los descomponedores convierten las hojas muertas en nutrientes que las plantas toman con sus raíces. En un bosque sano nada se desperdicia.","hint":"Piensa en qué pasa con los restos de las hojas.","tags":[],"opts":["Devuelven nutrientes al suelo","Dan hojas nuevas a los árboles al instante","Vuelven el suelo más duro y seco","Evitan que los animales hallen comida"],"a":0},{"id":"cieB-4-018","topic":"science","level":4,"type":"choice","q":"El lenguado se echa en la arena del fondo del mar y copia sus colores. ¿Para qué le sirve?","why":"El camuflaje lo esconde de los depredadores y de los animalitos que caza.","hint":"Piensa en por qué sirve igualar colores.","tags":["ocean"],"opts":["Para mantenerse tibio","Para nadar mucho más rápido","Para respirar mejor","Para pasar inadvertido"],"a":3},{"id":"cieB-4-019","topic":"science","level":4,"type":"choice","q":"Algunos dinosaurios eran tan pequeños como una gallina.","why":"Los dinosaurios venían en todos los tamaños. Los pequeños, como el compsognato, eran del tamaño de una gallina.","hint":"No todos los dinosaurios eran gigantes.","tags":["dinosaurs"],"opts":["Verdadero","Falso"],"a":0},{"id":"cieB-4-020","topic":"science","level":4,"type":"choice","q":"Una abeja bebe néctar de las flores. ¿Qué hace también por las plantas, sin darse cuenta?","why":"El polen que se pega a la abeja pasa a otras flores y ayuda a hacer semillas y frutos. Eso se llama polinización.","hint":"Su cuerpo peludo se llena de un polvito amarillo.","tags":["animals"],"opts":["Les echa agua en las raíces","Lleva polen de una flor a otra","Les quita todas las hojas viejas","Les deja abono en el tallo"],"a":1},{"id":"cieB-5-001","topic":"science","level":5,"type":"choice","q":"Casi todos los peces flotan con una vejiga llena de gas. Los tiburones no la tienen. ¿Qué les ayuda a no hundirse?","why":"El aceite del hígado pesa menos que el agua de mar y les da algo de empuje hacia arriba. Las aletas y nadar también ayudan.","hint":"Piensa en el aceite flotando sobre el agua.","tags":["sharks"],"opts":["Huesos huecos llenos de mucho aire","Tragar aire en la superficie del mar","Un hígado grande lleno de aceite","Sangre caliente que los eleva en el agua"],"a":2},{"id":"cieB-5-002","topic":"science","level":5,"type":"choice","q":"¿Cómo calculan los científicos la edad de un fósil de dinosaurio?","why":"Las capas de roca guardan relojes naturales: ciertos minerales cambian a un ritmo constante. Eso indica la edad de los fósiles cercanos.","hint":"La roca marca el tiempo mejor que el hueso.","tags":["dinosaurs"],"opts":["Datando las capas de roca que lo rodean","Pesando el fósil entero en una balanza","Midiendo qué tan grande llegó a ser","Contando las grietas que tiene el hueso"],"a":0},{"id":"cieB-5-003","topic":"science","level":5,"type":"choice","q":"Desde la Tierra siempre vemos la misma cara de la Luna. ¿Por qué?","why":"La Luna sí gira. Da exactamente una vuelta sobre sí misma mientras orbita una vez la Tierra, así que siempre nos muestra la misma cara.","hint":"La Luna gira a un ritmo muy especial.","tags":["space"],"opts":["Su otra cara siempre está en sombra","Nunca gira sobre sí misma","Las nubes tapan su otra cara","Gira una vez por cada órbita"],"a":3},{"id":"cieB-5-004","topic":"science","level":5,"type":"number","q":"Solo el 10 % de la energía de cada eslabón pasa al siguiente. Las algas tienen 20 000 unidades. Cadena: algas, camarones, peces, tiburón. ¿Cuántas unidades llegan al tiburón?","why":"De las algas pasan 2 000 a los camarones, 200 a los peces y 20 al tiburón. La energía disminuye en cada paso.","hint":"Saca el 10 % tres veces.","tags":["sharks","ocean"],"a":20},{"id":"cieB-5-005","topic":"science","level":5,"type":"choice","q":"El aire que sube se enfría. ¿Cómo ayuda eso a formar una nube?","why":"El aire frío guarda menos vapor, así que el sobrante se condensa en gotitas. Miles de millones de gotas forman una nube.","hint":"Piensa en un vaso frío en un día caluroso.","tags":["weather"],"opts":["El polvo del aire se convierte en agua","El vapor de agua se convierte en gotitas","El oxígeno se congela en cristales de hielo","El viento exprime la lluvia del aire"],"a":1},{"id":"cieB-5-006","topic":"science","level":5,"type":"choice","q":"¿Cuál de estos es un cambio químico, que forma una sustancia nueva?","why":"Al arder, la madera se convierte en ceniza, humo y gases: sustancias nuevas. Derretir, disolver y rasgar no cambian el material.","hint":"Un cambio químico no se deshace fácilmente.","tags":[],"opts":["Un hielo que se derrite en un vaso","Azúcar que se disuelve en té","Un papel que se rasga en pedacitos","Madera que arde en una fogata"],"a":3},{"id":"cieB-5-007","topic":"science","level":5,"type":"choice","q":"En una carretilla, ¿dónde está el punto de apoyo (fulcro) de la palanca?","why":"La carretilla gira alrededor de su rueda. La carga está entre la rueda y tus manos, que levantan en las manijas.","hint":"Lo que queda fijo mientras levantas es el punto de apoyo.","tags":["machines"],"opts":["En las manijas","En la rueda","En medio de la carga","En la parte delantera del cajón"],"a":1},{"id":"cieB-5-008","topic":"science","level":5,"type":"choice","q":"El bate golpea la pelota con mucha fuerza. ¿Qué hace la pelota con el bate?","why":"Las fuerzas vienen en pares del mismo tamaño y en sentidos opuestos. Por eso un batazo fuerte puede hacer sentir un golpe en las manos.","hint":"Piensa en lo que sienten las manos del bateador.","tags":["baseball"],"opts":["Lo empuja con una fuerza igual","Lo empuja con mucha menos fuerza","Lo empuja con mucha más fuerza","No lo empuja para nada"],"a":0},{"id":"cieB-5-009","topic":"science","level":5,"type":"choice","q":"¿Qué parte de la sangre ayuda a combatir los microbios?","why":"Los glóbulos blancos encuentran y atacan los microbios. Los rojos llevan oxígeno y las plaquetas tapan las heridas.","hint":"El color da una pista del tipo de célula.","tags":["body"],"opts":["Los glóbulos rojos","Las plaquetas de la sangre","Los glóbulos blancos","El plasma amarillento"],"a":2},{"id":"cieB-5-010","topic":"science","level":5,"type":"choice","q":"¿Qué seres vivos producen la mayor parte del oxígeno que viene del océano?","why":"El fitoplancton usa la luz del Sol para hacer alimento y suelta oxígeno. Aporta una enorme parte del oxígeno que respiramos.","hint":"La respuesta es pequeña y flota con la luz.","tags":["ocean"],"opts":["Las ballenas y los delfines","Algas diminutas (fitoplancton)","Solo los bosques de algas gigantes","Los arrecifes de coral y esponjas"],"a":1},{"id":"cieB-5-011","topic":"science","level":5,"type":"order","q":"Ordena las capas de la atmósfera, desde el suelo hacia arriba.","why":"El tiempo ocurre en la troposfera. Más arriba están la estratosfera, la mesosfera y la termosfera, donde el aire es muy delgado.","hint":"La capa más baja empieza con 'tropo'.","tags":["weather"],"opts":["Troposfera","Estratosfera","Mesosfera","Termosfera"]},{"id":"cieB-5-012","topic":"science","level":5,"type":"choice","q":"Un rayo es más caliente que la superficie del Sol.","why":"Un rayo calienta el aire a unos 30 000 grados por una fracción de segundo. La superficie del Sol está a unos 5 500.","hint":"Un rayo dura poco, pero quema muchísimo.","tags":["weather"],"opts":["Verdadero","Falso"],"a":0,"fun":true},{"id":"cieB-5-013","topic":"science","level":5,"type":"choice","q":"Un científico halla conchas fósiles cerca de la cima de una montaña muy alta. ¿Qué sugiere esto?","why":"Las placas de la Tierra empujan la roca hacia arriba durante millones de años. Un fondo marino antiguo puede acabar en una cima.","hint":"Piensa en dónde viven los moluscos y en cómo se mueve la tierra.","tags":["ocean"],"opts":["Los moluscos subían por la montaña","Las aves llevaron las conchas allí","La lluvia subió las conchas por la ladera","Ese suelo marino se elevó con el tiempo"],"a":3},{"id":"cieB-5-014","topic":"science","level":5,"type":"choice","q":"Una camiseta roja se ve roja bajo el Sol. ¿Qué pasa con la luz?","why":"El color que ves es la luz que rebota hacia tus ojos. La camiseta roja devuelve la luz roja y absorbe los demás colores.","hint":"El color que ves es la luz que rebota.","tags":[],"opts":["Produce luz roja dentro de sí","Absorbe la luz roja y refleja el resto","Refleja la luz roja y absorbe el resto","Bloquea toda la luz que le llega"],"a":2},{"id":"cieB-5-015","topic":"science","level":5,"type":"choice","q":"¿Por qué ves el relámpago antes de oír el trueno, si ocurren a la vez?","why":"La luz recorre casi 300 000 km cada segundo y el sonido solo unos 340 metros. La luz llega primero.","hint":"Compara la rapidez de la luz y la del sonido.","tags":["weather"],"opts":["La luz viaja mucho más rápido","El trueno sale después del relámpago","El sonido tiene que subir al cielo","Los ojos son más rápidos que los oídos"],"a":0},{"id":"cieB-5-016","topic":"science","level":5,"type":"choice","q":"Un equipo hace una bicicleta más fuerte con un material nuevo, pero cuesta mucho más. ¿Qué es esto?","why":"Los ingenieros pesan lo bueno y lo malo de cada decisión de diseño. Ganar algo suele costar otra cosa.","hint":"Ganas algo y renuncias a otra cosa.","tags":["machines"],"opts":["Un prototipo para probar la idea","Una hipótesis sobre el material","Un equilibrio entre ventajas y costos","Una variable que cambia en pruebas"],"a":2},{"id":"cieB-5-017","topic":"science","level":5,"type":"choice","q":"El zorro del desierto tiene orejas enormes. ¿Cómo le ayudan a sobrevivir?","why":"Por sus orejas delgadas pasa mucha sangre que suelta calor al aire, y eso mantiene fresco al zorro.","hint":"Piensa en lo que el desierto le hace al cuerpo.","tags":["animals"],"opts":["Dejan escapar el exceso de calor","Guardan agua para días secos","Oyen agua bajo la tierra","Espantan a animales más grandes"],"a":0},{"id":"cieB-5-018","topic":"science","level":5,"type":"choice","q":"Las hojas tienen aberturas diminutas, sobre todo por debajo. ¿Qué pasa por ellas?","why":"Esas aberturas, llamadas estomas, dejan entrar dióxido de carbono y salir oxígeno y vapor de agua.","hint":"Funcionan como puertitas para gases.","tags":[],"opts":["Luz del Sol y tierra","Savia y raíces","Semillas y polen","Gases del aire y vapor de agua"],"a":3},{"id":"cieB-5-019","topic":"science","level":5,"type":"choice","q":"Los astronautas flotan en la estación espacial aunque la gravedad aún los jala. ¿Por qué?","why":"Allá la gravedad es casi tan fuerte como aquí. La estación avanza tan rápido de lado que siempre cae alrededor de la Tierra.","hint":"La gravedad no se ha apagado.","tags":["space"],"opts":["Allá arriba no hay gravedad","Ellos y la estación caen en órbita","Motores internos cancelan la gravedad","La estación está sobre el aire"],"a":1},{"id":"cieB-5-020","topic":"science","level":5,"type":"choice","q":"Una abeja que encuentra flores puede 'bailar' para avisar a las demás hacia dónde ir.","why":"La danza de la abeja indica la dirección y la distancia de las flores. Así la colmena encuentra comida más rápido.","hint":"Las abejas se comunican con movimientos.","tags":["animals"],"opts":["Verdadero","Falso"],"a":0,"fun":true},{"id":"cieB-6-001","topic":"science","level":6,"type":"choice","q":"Los tiburones tienen esqueleto de cartílago, no de hueso. ¿Qué peces son sus parientes más cercanos?","why":"Tiburones, rayas y mantarrayas tienen esqueleto de cartílago y comparten un antepasado. Atunes y anguilas tienen esqueleto de hueso.","hint":"Busca otro grupo de esqueleto flexible.","tags":["sharks"],"opts":["Las anguilas y las morenas","Los atunes y las caballas","Las rayas y las mantarrayas","Los caballitos de mar y peces pipa"],"a":2},{"id":"cieB-6-002","topic":"science","level":6,"type":"choice","q":"El Archaeopteryx tenía plumas y alas, pero también dientes y una larga cola ósea. ¿Por qué es tan importante este fósil?","why":"El Archaeopteryx mezcla rasgos de aves con rasgos de dinosaurios. Eso apoya la idea de que las aves vienen de los dinosaurios.","hint":"Es una mezcla de dos grupos de animales.","tags":["dinosaurs"],"opts":["Muestra rasgos de dinosaurios y de aves","Prueba que todos los dinosaurios volaban","Muestra que las aves vinieron primero","Prueba que los dinosaurios vivían en el agua"],"a":0},{"id":"cieB-6-003","topic":"science","level":6,"type":"choice","q":"Una estrella está a 10 años luz de la Tierra. ¿Qué ves al mirarla esta noche?","why":"Un año luz es lo que recorre la luz en un año. Esa luz salió hace 10 años: ves el pasado de la estrella.","hint":"La luz tarda en cruzar el espacio.","tags":["space"],"opts":["La estrella como es ahora mismo","La estrella dentro de 10 años","La estrella como era hace 10 días","La estrella como era hace 10 años"],"a":3},{"id":"cieB-6-004","topic":"science","level":6,"type":"number","q":"La Tierra gira 360 grados en 24 horas, a un ritmo constante. ¿Cuántos grados gira en 2 horas?","why":"360 entre 24 es 15 grados por hora, así que en 2 horas giran 30 grados. Por eso los husos horarios miden unos 15 grados.","hint":"Primero calcula cuántos grados gira en una hora.","tags":["space"],"a":30},{"id":"cieB-6-005","topic":"science","level":6,"type":"choice","q":"Un huracán se debilita rápido cuando llega a tierra. ¿Por qué?","why":"Los huracanes sacan su energía del agua cálida del mar. En tierra se quedan sin ella y el roce con el suelo frena el viento.","hint":"¿De dónde saca energía la tormenta?","tags":["weather"],"opts":["En tierra hay mucho viento frío","Pierde el mar cálido que lo alimenta","Las montañas lo rompen en mil pedazos","En tierra el aire pesa mucho más"],"a":1},{"id":"cieB-6-006","topic":"science","level":6,"type":"choice","q":"Un clavo de acero macizo se hunde, pero un enorme barco de acero flota. ¿Por qué?","why":"El casco hueco hace que el barco entero sea menos denso que el agua. Desplaza un peso de agua igual al suyo y flota.","hint":"Piensa en la forma de todo el barco, no solo en el metal.","tags":["ocean","machines"],"opts":["Su acero es un tipo más liviano","El motor lo empuja hacia arriba","Lo muy grande siente menos gravedad","Su forma hueca desplaza mucha agua"],"a":3},{"id":"cieB-6-007","topic":"science","level":6,"type":"number","q":"Un engranaje de 12 dientes mueve a uno de 36 dientes. ¿Cuántas vueltas del pequeño hacen que el grande gire exactamente una vez?","why":"Cada vuelta del pequeño mueve 12 dientes. Para mover los 36 dientes se necesitan 36 entre 12 igual a 3 vueltas.","hint":"Cuenta cuántos dientes deben pasar.","tags":["machines"],"a":3},{"id":"cieB-6-008","topic":"science","level":6,"type":"choice","q":"La energía de movimiento de una pelota depende del cuadrado de su rapidez. Si un lanzamiento va al doble de rápido, su energía de movimiento se vuelve...","why":"Al duplicar la rapidez, el cuadrado se multiplica por 2 x 2 = 4. Por eso los lanzamientos rápidos son mucho más difíciles de atrapar.","hint":"Eleva el 2 al cuadrado.","tags":["baseball"],"opts":["Dos veces mayor","Cuatro veces mayor","Tres veces mayor","Ocho veces mayor"],"a":1},{"id":"cieB-6-009","topic":"science","level":6,"type":"choice","q":"¿Por qué con dos ojos calculas mejor la distancia que con uno solo?","why":"El cerebro compara dos vistas ligeramente distintas para calcular qué tan lejos están las cosas. Con un ojo tapado, es más difícil.","hint":"Tus ojos están a pocos centímetros uno del otro.","tags":["body"],"opts":["Cada ojo ve desde un lugar distinto","Dos ojos reciben el doble de luz","Un ojo siempre está cerrado por dentro","Cada ojo ve un color de luz distinto"],"a":0},{"id":"cieB-6-010","topic":"science","level":6,"type":"choice","q":"Un rape de aguas profundas lleva una carnada luminosa. ¿Cómo se produce esa luz?","why":"Se llama bioluminiscencia: sustancias que reaccionan y dan luz sin calor, a veces con ayuda de bacterias. Así atrae presas en la oscuridad.","hint":"La luz puede venir de la química y no solo del calor.","tags":["ocean"],"opts":["Guardando la luz del Sol que recibió","Con chispas eléctricas como una pila","Con reacciones químicas en sus células","Frotando sus escamas con fuerza entre sí"],"a":2,"fun":true},{"id":"cieB-6-011","topic":"science","level":6,"type":"order","q":"Ordena el camino de un sonido por tu oído.","why":"El sonido hace vibrar el tímpano, los huesecillos pasan la vibración hacia adentro y los nervios la convierten en señales que el cerebro entiende.","hint":"El tímpano es lo primero que vibra.","tags":["body"],"opts":["El sonido entra por el canal del oído","El tímpano vibra","Huesecillos pasan la vibración","Los nervios avisan al cerebro"]},{"id":"cieB-6-012","topic":"science","level":6,"type":"choice","q":"Una cuchara de metal se siente más fría que una de madera en el mismo cuarto porque el metal está más frío.","why":"Las dos tienen la misma temperatura del cuarto. El metal le quita calor a tu mano más rápido y por eso se siente más frío.","hint":"Las dos cucharas llevan el mismo tiempo en el cuarto.","tags":[],"opts":["Verdadero","Falso"],"a":1},{"id":"cieB-6-013","topic":"science","level":6,"type":"choice","q":"Los científicos estudian burbujas de aire atrapadas en hielo polar muy antiguo. ¿Qué pueden mostrar?","why":"La nieve se compacta y se vuelve hielo, y atrapa burbujas del aire de esa época. Cuanto más profundo, más antiguo es el aire.","hint":"Las burbujas se sellaron cuando cayó la nieve.","tags":["weather"],"opts":["Qué tan profundos eran los océanos","Cómo era el aire en el pasado","Qué animales vivían en el hielo","Cuántas tormentas hubo el año pasado"],"a":1},{"id":"cieB-6-014","topic":"science","level":6,"type":"number","q":"Estás a 3 metros de un espejo plano. ¿A cuántos metros de ti parece estar tu reflejo?","why":"Tu reflejo parece estar detrás del espejo, tan lejos como tú estás delante: 3 m + 3 m = 6 m de ti.","hint":"El reflejo se ve detrás del espejo.","tags":[],"a":6},{"id":"cieB-6-015","topic":"science","level":6,"type":"choice","q":"La sirena de una ambulancia suena más aguda al acercarse y más grave al alejarse. ¿Por qué?","why":"Al acercarse, el vehículo aprieta las ondas y el sonido se vuelve más agudo. Al alejarse, las estira y suena más grave.","hint":"El vehículo se mueve mientras emite el sonido.","tags":[],"opts":["La sirena cambia su propia melodía","El sonido viaja más rápido al alejarse","El aire se espesa detrás del vehículo","Las ondas se juntan y luego se estiran"],"a":3},{"id":"cieB-6-016","topic":"science","level":6,"type":"choice","q":"¿Por qué una torre de bloques ancha y baja es más difícil de volcar que una alta y angosta?","why":"Un centro de gravedad bajo sobre una base amplia mantiene la torre en equilibrio y hace falta un empujón mayor para volcarla.","hint":"Piensa en dónde está el peso y sobre qué se apoya.","tags":["machines"],"opts":["Tiene muchos menos bloques","Sus bloques pesan más de un lado","Tiene el peso abajo y una base ancha","El viento no toca las torres anchas"],"a":2},{"id":"cieB-6-017","topic":"science","level":6,"type":"choice","q":"Un sírfido inofensivo tiene rayas amarillas y negras como una avispa que pica. ¿Cómo se llama este truco?","why":"En el mimetismo, un animal se parece a otro que los depredadores evitan. El camuflaje, en cambio, se confunde con el fondo.","hint":"Imita el aspecto de otro animal.","tags":["animals"],"opts":["Mimetismo","Hibernación","Migración","Camuflaje"],"a":0},{"id":"cieB-6-018","topic":"science","level":6,"type":"choice","q":"Una semilla diminuta crece hasta ser un árbol que pesa toneladas. ¿De dónde salen los átomos de carbono de su madera?","why":"Las hojas toman dióxido de carbono del aire y lo convierten en azúcares y madera. La luz del Sol da energía, no átomos.","hint":"Los árboles fabrican madera a partir de un gas.","tags":[],"opts":["De los minerales del suelo","Del agua que toman las raíces","Del dióxido de carbono del aire","De la luz del Sol sobre las hojas"],"a":2},{"id":"cieB-6-019","topic":"science","level":6,"type":"choice","q":"¿Por qué un agujero negro es negro?","why":"Un agujero negro junta muchísima masa en un espacio diminuto. Su gravedad es tan fuerte que ni la luz puede salir.","hint":"Piensa en qué puede escapar de una gravedad muy fuerte.","tags":["space"],"opts":["Ni la luz escapa de su gravedad","Está cubierto de polvo negro espeso","Está demasiado frío para dar luz","Es un hueco que no tiene masa"],"a":0},{"id":"cieB-6-020","topic":"science","level":6,"type":"choice","q":"Los tiburones ya vivían en la Tierra antes de que existieran los primeros árboles.","why":"Los tiburones nadaban en los mares hace más de 400 millones de años. Los primeros árboles aparecieron hace unos 385 millones.","hint":"Los tiburones llevan muchísimo tiempo en el planeta.","tags":["sharks"],"opts":["Verdadero","Falso"],"a":0,"fun":true},{"id":"palB-1-001","topic":"words","level":1,"type":"choice","q":"El tiburón ballena es enorme. El pececito es lo contrario. ¿Cuál palabra describe al pececito?","why":"Los contrarios significan lo opuesto. Enorme y grande significan casi lo mismo; pequeño es lo contrario.","hint":"Contrario quiere decir opuesto.","tags":["sharks","ocean"],"opts":["grande","veloz","pequeño"],"a":2},{"id":"palB-1-002","topic":"words","level":1,"type":"choice","q":"¿Con qué sílaba empieza la palabra 'cohete'?","why":"Cohete se divide así: co-he-te. La primera sílaba es co.","hint":"Aplaude cada sílaba al decir la palabra.","tags":["space"],"opts":["ho","co","te"],"a":1},{"id":"palB-1-003","topic":"words","level":1,"type":"choice","q":"____ estrellas brillan en la noche. ¿Qué palabra falta?","why":"Estrellas es femenino y plural, así que lleva 'las'.","hint":"Estrellas es femenino y hay muchas.","tags":["space"],"opts":["Las","Los","El"],"a":0},{"id":"palB-1-004","topic":"words","level":1,"type":"choice","q":"La palabra 'luna' tiene dos sílabas: lu-na.","why":"Lu-na tiene dos palmadas, es decir, dos sílabas.","hint":"Aplaude al decir la palabra.","tags":["space"],"opts":["Verdadero","Falso"],"a":0},{"id":"palB-1-005","topic":"words","level":1,"type":"choice","q":"El dinosaurio era enorme. ¿Qué palabra significa casi lo mismo que enorme?","why":"Enorme y gigante significan muy grande. Chiquito significa lo contrario.","hint":"Busca otra manera de decir muy grande.","tags":["dinosaurs"],"opts":["gigante","chiquito","lento"],"a":0},{"id":"palB-1-006","topic":"words","level":1,"type":"choice","q":"En 'El delfín salta alto', ¿qué palabra dice lo que hace el delfín?","why":"Salta es la acción, o sea, el verbo. Delfín dice quién, y alto dice cómo.","hint":"Busca la acción.","tags":["ocean"],"opts":["delfín","salta","alto"],"a":1},{"id":"palB-1-007","topic":"words","level":1,"type":"order","q":"Ordena las sílabas para formar el nombre de un objeto con cola brillante que viaja por el espacio.","why":"Co-me-ta forma cometa: una bola de hielo y polvo que deja una cola brillante.","hint":"Piensa en una cola de luz en el cielo.","tags":["space"],"opts":["co","me","ta"]},{"id":"palB-1-008","topic":"words","level":1,"type":"choice","q":"¿Qué palabra rima con 'luna'?","why":"Luna y cuna terminan igual: -una. Mesa y sol suenan distinto al final.","hint":"Escucha cómo terminan las palabras.","tags":["space"],"opts":["mesa","sol","cuna"],"a":2},{"id":"palB-1-009","topic":"words","level":1,"type":"choice","q":"En el abecedario del español, ¿qué letra va justo después de la 'n'?","why":"El abecedario sigue así: m, n, ñ, o. La ñ es una letra propia del español.","hint":"Canta el abecedario despacio.","tags":[],"opts":["o","m","ñ"],"a":2},{"id":"palB-1-010","topic":"words","level":1,"type":"number","q":"¿Cuántas vocales (a, e, i, o, u) tiene la palabra 'tiburón'?","why":"Tiburón tiene i, u y ó. La o con tilde también cuenta como vocal.","hint":"Cuenta cada vocal, aunque lleve tilde.","tags":["sharks"],"a":3},{"id":"palB-1-011","topic":"words","level":1,"type":"choice","q":"____ ballena canta bajo el mar. ¿Qué palabra falta?","why":"Ballena es femenino y singular, por eso lleva 'la'.","hint":"Ballena es femenino y es una sola.","tags":["ocean"],"opts":["La","El","Los"],"a":0},{"id":"palB-1-012","topic":"words","level":1,"type":"choice","q":"Lee la palabra 'sol' de atrás hacia adelante. ¿Qué palabra sale?","why":"Al revés, s-o-l se lee l-o-s: los. Sal tiene una a en medio, y sol sería la misma palabra sin voltearla.","hint":"Empieza por la última letra.","tags":["space"],"opts":["sal","sol","los"],"a":2,"fun":true},{"id":"palB-1-013","topic":"words","level":1,"type":"choice","q":"La palabra 'pelota' es una acción, como correr.","why":"Pelota es un sustantivo: nombra una cosa. Correr es un verbo, o sea, una acción.","hint":"¿Pelota nombra una cosa o una acción?","tags":["baseball"],"opts":["Verdadero","Falso"],"a":1},{"id":"palB-1-014","topic":"words","level":1,"type":"choice","q":"Un cangrejo, dos ____ . ¿Cuál es el plural correcto?","why":"Si la palabra termina en vocal, se agrega -s: cangrejo, cangrejos.","hint":"Termina en o. ¿Qué letra agregas?","tags":["ocean"],"opts":["cangrejes","cangrejos","cangrejas"],"a":1},{"id":"palB-1-015","topic":"words","level":1,"type":"choice","q":"¿Cuál palabra empieza con el mismo sonido que 'cangrejo'?","why":"Cangrejo y casa empiezan con el sonido /k/. En cielo y cebra, la c suena suave.","hint":"Di cada palabra y escucha el primer sonido.","tags":["ocean"],"opts":["casa","cielo","cebra"],"a":0},{"id":"palB-1-016","topic":"words","level":1,"type":"order","q":"Ordena las palabras para formar una oración.","why":"Una oración empieza con mayúscula y dice quién es y qué hace.","hint":"Empieza por la palabra con mayúscula.","tags":["sharks"],"opts":["El","tiburón","nada","rápido."]},{"id":"palB-1-017","topic":"words","level":1,"type":"choice","q":"El satélite está arriba, en el cielo. ¿Cuál palabra es lo contrario de 'arriba'?","why":"Arriba y abajo son opuestos. Afuera es lo contrario de adentro.","hint":"Piensa en dónde está el piso.","tags":["space"],"opts":["afuera","abajo","cerca"],"a":1},{"id":"palB-1-018","topic":"words","level":1,"type":"choice","q":"¿Cuál de estas palabras NO es un animal del mar?","why":"La medusa y el pulpo viven en el mar. El conejo vive en la tierra.","hint":"Piensa dónde vive cada animal.","tags":["ocean"],"opts":["conejo","medusa","pulpo"],"a":0},{"id":"palB-1-019","topic":"words","level":1,"type":"choice","q":"El astronauta tuvo un ____ bonito sobre la Luna. ¿Cómo se escribe?","why":"Sueño lleva ñ, la letra con una ondita arriba.","hint":"Busca la letra con una ondita.","tags":["space"],"opts":["sueno","sueño","suenio"],"a":1},{"id":"palB-1-020","topic":"words","level":1,"type":"choice","q":"¿Cuál palabra se lee igual de izquierda a derecha y de derecha a izquierda?","why":"Oso al revés sigue siendo oso. Lobo al revés dice 'obol'. Estas palabras se llaman palíndromos.","hint":"Lee cada palabra desde su última letra.","tags":["animals"],"opts":["lobo","foca","oso"],"a":2,"fun":true},{"id":"palB-2-001","topic":"words","level":2,"type":"choice","q":"¿Cuál de estas palabras es compuesta, o sea, está hecha con dos palabras?","why":"Girasol viene de gira + sol, porque la flor gira siguiendo al sol. Tulipán y jardín son una sola palabra.","hint":"Busca una palabra que se pueda partir en dos.","tags":["space"],"opts":["tulipán","girasol","jardín"],"a":1,"fun":true},{"id":"palB-2-002","topic":"words","level":2,"type":"choice","q":"El macho es el león. ¿Cómo se llama la hembra?","why":"Al cambiar a femenino, león pierde la tilde: leona. Muchas hembras terminan en -a, como osa.","hint":"La hembra termina en -a.","tags":["animals"],"opts":["leona","leóna","leonesa"],"a":0},{"id":"palB-2-003","topic":"words","level":2,"type":"choice","q":"Un tiburón, dos ____ . ¿Cómo se escribe el plural?","why":"Al agregar -es, la palabra pierde la tilde: tiburones.","hint":"Escucha dónde suena más fuerte la voz.","tags":["sharks"],"opts":["tiburones","tiburónes","tiburons"],"a":0},{"id":"palB-2-004","topic":"words","level":2,"type":"choice","q":"Con solo una tilde, 'papa' (una comida) se convierte en 'papá' (tu padre).","why":"La tilde cambia el significado: papa es una comida y papá es tu padre. ¡Una rayita hace la diferencia!","hint":"Fíjate en la rayita sobre la última a.","tags":["food"],"opts":["Verdadero","Falso"],"a":0,"fun":true},{"id":"palB-2-005","topic":"words","level":2,"type":"choice","q":"¿Cuál es el diminutivo de 'pez'?","why":"Pez cambia a pececito: la z se vuelve c, como en el plural peces.","hint":"Piensa en el plural: peces.","tags":["ocean"],"opts":["pezito","pececito","pezecito"],"a":1},{"id":"palB-2-006","topic":"words","level":2,"type":"choice","q":"El fondo del mar es oscuro. ¿Cuál palabra es lo contrario de 'oscuro'?","why":"Oscuro y claro son contrarios. Negro es un color oscuro, no su contrario.","hint":"Piensa en un cuarto lleno de luz.","tags":["ocean"],"opts":["negro","frío","claro"],"a":2},{"id":"palB-2-007","topic":"words","level":2,"type":"choice","q":"Los tiburones ____ cerca del arrecife. ¿Qué forma del verbo nadar falta?","why":"Tiburones es plural, así que el verbo también: nadan. Nada va con un solo tiburón.","hint":"¿Hay uno o muchos tiburones?","tags":["sharks"],"opts":["nada","nadas","nadan"],"a":2},{"id":"palB-2-008","topic":"words","level":2,"type":"order","q":"Ordena las oraciones para contar lo que pasó en el juego.","why":"Primero lanza el pitcher, luego batea el bateador, después vuela la pelota y al final llega el jonrón.","hint":"Piensa qué pasa primero en un turno al bate.","tags":["baseball"],"opts":["El lanzador tiró la primera bola.","El bateador la golpeó fuerte.","La pelota voló sobre la cerca.","¡Fue un jonrón!"]},{"id":"palB-2-009","topic":"words","level":2,"type":"choice","q":"____ mano del pelotero atrapó la pelota. ¿Qué artículo falta?","why":"Mano es femenina aunque termine en o: la mano. Es una excepción que hay que aprender.","hint":"Di en voz alta: ¿el mano o la mano?","tags":["baseball"],"opts":["La","El","Los"],"a":0},{"id":"palB-2-010","topic":"words","level":2,"type":"choice","q":"¿Cómo se escribe el nombre de un felino manchado que corre muy rápido?","why":"Con ge la g suena como j. Para que suene fuerte, se escribe gue: guepardo.","hint":"Esa g suena fuerte, como en 'guitarra'.","tags":["animals"],"opts":["guepardo","gepardo","guiepardo"],"a":0},{"id":"palB-2-011","topic":"words","level":2,"type":"number","q":"¿Cuántas sílabas tiene la palabra 'dinosaurio'?","why":"Di-no-sau-rio tiene cuatro. Las vocales 'au' e 'io' van juntas y forman una sola sílaba cada una.","hint":"Las vocales juntas suenan en una sola sílaba.","tags":["dinosaurs"],"a":4},{"id":"palB-2-012","topic":"words","level":2,"type":"choice","q":"El pelotero corrió veloz hasta la base. ¿Qué palabra significa casi lo mismo que 'veloz'?","why":"Veloz y rápido significan que algo se mueve con mucha rapidez. Pesado no tiene que ver.","hint":"Piensa en alguien que corre mucho.","tags":["baseball"],"opts":["pesado","rápido","cansado"],"a":1},{"id":"palB-2-013","topic":"words","level":2,"type":"choice","q":"El buzo se sumergió en el mar. ¿Qué significa 'sumergió'?","why":"Sumergirse es meterse bajo el agua. La pista es que un buzo trabaja dentro del mar.","hint":"Piensa en lo que hace un buzo.","tags":["ocean"],"opts":["saltó muy alto desde el barco","se metió bajo el agua","salió nadando hasta la orilla"],"a":1},{"id":"palB-2-014","topic":"words","level":2,"type":"choice","q":"En español, los días de la semana, como 'lunes', se escriben con mayúscula inicial.","why":"En español, los días y los meses se escriben con minúscula, porque son nombres comunes.","hint":"¿Es un nombre propio o uno común?","tags":[],"opts":["Verdadero","Falso"],"a":1},{"id":"palB-2-015","topic":"words","level":2,"type":"choice","q":"¿Cuál palabra es de la familia de 'sol'?","why":"Soleado viene de sol: un día con mucho sol. Soldado y solo tienen otro origen.","hint":"Busca la palabra que tiene que ver con el cielo.","tags":["weather","space"],"opts":["soldado","solo","soleado"],"a":2},{"id":"palB-2-016","topic":"words","level":2,"type":"choice","q":"¿Cómo se escribe el instrumento que se toca con palillos?","why":"Antes de b siempre se escribe m, nunca n: tambor, cambio, también.","hint":"Piensa en la regla de m antes de b.","tags":[],"opts":["tanbor","tambor","tamvor"],"a":1},{"id":"palB-2-017","topic":"words","level":2,"type":"choice","q":"Las palabras 'grande' y 'pequeño' son sinónimos.","why":"Los sinónimos significan lo mismo. Grande y pequeño significan lo contrario, así que son antónimos.","hint":"¿Significan lo mismo o lo opuesto?","tags":[],"opts":["Verdadero","Falso"],"a":1},{"id":"palB-2-018","topic":"words","level":2,"type":"choice","q":"¿Cuál de estas palabras se escribe siempre con mayúscula inicial?","why":"Marte es el nombre propio de un planeta, por eso lleva mayúscula. Planeta y estrella son nombres comunes.","hint":"Un nombre propio señala algo único.","tags":["space"],"opts":["Marte","planeta","estrella"],"a":0},{"id":"palB-2-019","topic":"words","level":2,"type":"choice","q":"Ayer yo ____ béisbol con mis amigos. ¿Qué forma del verbo jugar falta?","why":"Ayer ya pasó, así que el verbo va en pasado: jugué.","hint":"Ayer ya pasó.","tags":["baseball"],"opts":["juego","jugaré","jugué"],"a":2},{"id":"palB-2-020","topic":"words","level":2,"type":"choice","q":"En 'El tiburón gris nada', ¿qué palabra dice cómo es el tiburón?","why":"Gris es un adjetivo: describe al sustantivo. Nada es el verbo.","hint":"Busca la palabra que describe.","tags":["sharks"],"opts":["nada","tiburón","gris"],"a":2},{"id":"palB-3-001","topic":"words","level":3,"type":"choice","q":"Una ____ gigante llegó a la orilla. ¿Qué palabra falta?","why":"Ola, sin h, es el movimiento del agua del mar. Hola, con h, es un saludo. Suenan casi igual.","hint":"¿Cuál palabra mueve el agua del mar?","tags":["ocean"],"opts":["hola","olla","ora","ola"],"a":3},{"id":"palB-3-002","topic":"words","level":3,"type":"choice","q":"Algo que no se puede ver es ____ . ¿Qué palabra falta?","why":"El prefijo in- significa no. Invisible es lo que no se puede ver.","hint":"Busca el prefijo que significa no.","tags":[],"opts":["visible","visual","visera","invisible"],"a":3},{"id":"palB-3-003","topic":"words","level":3,"type":"choice","q":"El buzo respiraba por un ____ de aire. ¿Qué palabra falta?","why":"Tubo, con b, es un conducto hueco. Tuvo, con v, viene del verbo tener.","hint":"¿Qué objeto hueco deja pasar el aire?","tags":["ocean"],"opts":["tuvo","tubo","tubó","tuvó"],"a":1},{"id":"palB-3-004","topic":"words","level":3,"type":"choice","q":"La palabra 'cielo' tiene un diptongo, o sea, dos vocales juntas en una sola sílaba.","why":"En cie-lo, la i y la e van juntas en una sola sílaba. Eso se llama diptongo.","hint":"Aplaude las sílabas de cielo.","tags":["space"],"opts":["Verdadero","Falso"],"a":0},{"id":"palB-3-005","topic":"words","level":3,"type":"choice","q":"El sufijo -dor significa 'el que hace algo'. ¿Cómo se llama el que lanza la pelota?","why":"Lanzar + -dor forma lanzador, la persona que lanza. Lanzar es solo la acción.","hint":"Busca a la persona que hace la acción.","tags":["baseball"],"opts":["lancero","lanzada","lanzar","lanzador"],"a":3},{"id":"palB-3-006","topic":"words","level":3,"type":"choice","q":"En 'Un banco de peces pasó nadando', ¿qué significa 'banco'?","why":"Banco tiene varios significados. Aquí, banco de peces es un grupo grande de peces que nadan juntos.","hint":"Piensa en lo que hacen los peces.","tags":["ocean"],"opts":["un asiento largo","un lugar para guardar dinero","la orilla del río","un grupo de peces"],"a":3,"fun":true},{"id":"palB-3-007","topic":"words","level":3,"type":"choice","q":"El tiburón nadó ____ hacia su presa. ¿Cómo se escribe la palabra?","why":"Las palabras con -mente conservan la tilde del adjetivo: rápido, rápidamente.","hint":"Mira cómo se escribe rápido.","tags":["sharks"],"opts":["rápidamente","rapidamente","rápidomente","rapidomente"],"a":0},{"id":"palB-3-008","topic":"words","level":3,"type":"number","q":"¿Cuántas de estas palabras llevan tilde: árbitro, guante, césped, pelota, rápido, jugador?","why":"Árbitro, césped y rápido llevan tilde. Guante, pelota y jugador no la necesitan.","hint":"Fíjate en dónde suena más fuerte cada palabra.","tags":["baseball"],"a":3},{"id":"palB-3-009","topic":"words","level":3,"type":"choice","q":"¿Cuál es el aumentativo de 'casa'?","why":"El aumentativo dice que algo es más grande. Una casona es una casa grande. Casita y casilla son pequeñas.","hint":"Aumentativo quiere decir más grande.","tags":[],"opts":["casita","casilla","casero","casona"],"a":3},{"id":"palB-3-010","topic":"words","level":3,"type":"choice","q":"El astronauta fue muy valiente. ¿Qué palabra significa casi lo mismo que 'valiente'?","why":"Valiente y audaz se dicen de quien no tiene miedo de hacer cosas difíciles. Tímido es lo contrario.","hint":"Busca la palabra que va con no tener miedo.","tags":["space"],"opts":["tímido","audaz","cansado","veloz"],"a":1},{"id":"palB-3-011","topic":"words","level":3,"type":"choice","q":"'Jonrón' viene del inglés 'home run'. ¿Cómo se llama a las palabras que un idioma toma de otro?","why":"Los préstamos son palabras que un idioma toma de otro. Jonrón suena parecido a home run.","hint":"Piensa en palabras que viajaron de un idioma a otro.","tags":["baseball"],"opts":["préstamos","sinónimos","rimas","diptongos"],"a":0,"fun":true},{"id":"palB-3-012","topic":"words","level":3,"type":"order","q":"Ordena alfabéticamente estas palabras del mar.","why":"Todas empiezan con p, así que miramos la segunda letra: e, i, l, u.","hint":"Compara la segunda letra de cada palabra.","tags":["ocean"],"opts":["pez","pingüino","plancton","pulpo"]},{"id":"palB-3-013","topic":"words","level":3,"type":"choice","q":"Hay peces en abundancia. Lo contrario de 'abundante' es ____ . ¿Qué palabra falta?","why":"Abundante es lo que hay mucho. Escaso es lo que hay muy poco. Numeroso se parece a abundante.","hint":"Busca el opuesto de mucho.","tags":["ocean"],"opts":["numeroso","enorme","escaso","colorido"],"a":2},{"id":"palB-3-014","topic":"words","level":3,"type":"choice","q":"El cangrejo es muy ágil y se escabulle entre las rocas. ¿Qué significa 'ágil'?","why":"Ágil se dice de quien se mueve con rapidez y facilidad. La pista es que se escabulle entre las rocas.","hint":"Usa la pista: se escabulle entre las rocas.","tags":["ocean"],"opts":["es muy pesado y se cansa","tiene el caparazón muy duro","hace mucho ruido al caminar","se mueve rápido y fácil"],"a":3},{"id":"palB-3-015","topic":"words","level":3,"type":"choice","q":"Ayer los astronautas ____ la Luna de cerca. ¿Qué forma del verbo ver falta?","why":"Ver es irregular en pasado: ellos vieron. Veyeron y veron no existen.","hint":"Ayer ya pasó, y son varios astronautas.","tags":["space"],"opts":["veyeron","vieron","vieran","veron"],"a":1},{"id":"palB-3-016","topic":"words","level":3,"type":"choice","q":"Todos los verbos que terminan en -bir, como 'escribir', se escriben con b.","why":"Casi todos llevan b, pero hay tres excepciones: hervir, servir y vivir, que llevan v.","hint":"Piensa en el verbo vivir.","tags":[],"opts":["Verdadero","Falso"],"a":1},{"id":"palB-3-017","topic":"words","level":3,"type":"choice","q":"¿Cuál frase está bien escrita?","why":"Planeta es masculina aunque termine en a: el planeta. Por eso el adjetivo va en masculino: rojo.","hint":"Fíjate en cómo concuerdan artículo y adjetivo.","tags":["space"],"opts":["la planeta roja","el planeta roja","el planeta rojo","la planeta rojo"],"a":2},{"id":"palB-3-018","topic":"words","level":3,"type":"choice","q":"El entrenador tiene un corazón de oro. ¿Qué quiere decir esa frase?","why":"Corazón de oro es una expresión, no es literal. Se dice de alguien muy bueno y generoso.","hint":"No es literal: piensa en cómo es la persona.","tags":["baseball"],"opts":["tiene joyas escondidas","está enfermo del corazón","es muy bondadoso","es muy rico"],"a":2},{"id":"palB-3-019","topic":"words","level":3,"type":"choice","q":"El agua congelada se llama ____ . ¿Cómo se escribe?","why":"Hielo empieza con h aunque no suene: h-ie-lo. Lo mismo pasa con hierro y hierba.","hint":"La h no se oye, pero ahí está.","tags":["weather"],"opts":["hielo","ielo","yelo","jielo"],"a":0},{"id":"palB-3-020","topic":"words","level":3,"type":"choice","q":"Un grupo de abejas se llama ____ . ¿Qué palabra falta?","why":"Un enjambre es un grupo de abejas. Cardumen es de peces, bandada de aves y manada de lobos.","hint":"Piensa en un panal.","tags":["animals"],"opts":["enjambre","cardumen","bandada","manada"],"a":0},{"id":"palB-4-001","topic":"words","level":4,"type":"choice","q":"En 'tiburón', la sílaba que suena más fuerte es la última. ¿Cómo se llama esa clase de palabra?","why":"Si la sílaba más fuerte es la última, la palabra es aguda: ti-bu-RÓN. Las llanas cargan la penúltima.","hint":"Cuenta las sílabas desde el final.","tags":["sharks"],"opts":["aguda","llana","esdrújula","sobresdrújula"],"a":0},{"id":"palB-4-002","topic":"words","level":4,"type":"choice","q":"El prefijo pre- significa 'antes'. ¿Qué significa 'prehistórico'?","why":"Pre- significa antes. Los dinosaurios vivieron mucho antes de que existiera la escritura, así que son prehistóricos.","hint":"Pre- significa antes.","tags":["dinosaurs"],"opts":["posterior a la historia escrita","que cuenta muchas historias","que no tiene ninguna historia","anterior a la historia escrita"],"a":3},{"id":"palB-4-003","topic":"words","level":4,"type":"choice","q":"Los fanáticos saltaron la ____ del estadio. ¿Qué palabra falta?","why":"Valla, con v, es una cerca. Vaya viene del verbo ir, y baya es un fruto pequeño. Suenan casi igual.","hint":"¿Qué palabra nombra una cerca?","tags":["baseball"],"opts":["valla","vaya","baya","balla"],"a":0},{"id":"palB-4-004","topic":"words","level":4,"type":"choice","q":"Las palabras terminadas en -illa, como 'ardilla', se escriben con y.","why":"Las terminaciones -illo e -illa se escriben con ll: ardilla, cuchillo, sencilla.","hint":"Piensa en cómo se escribe 'sencilla'.","tags":["animals"],"opts":["Verdadero","Falso"],"a":1},{"id":"palB-4-005","topic":"words","level":4,"type":"choice","q":"El pez sierra tiene un hocico largo con dientes a los lados. ¿Qué significa 'sierra' aquí?","why":"Sierra también es una herramienta con dientes. El hocico del pez sierra parece una. Otra sierra es una cadena de montañas.","hint":"Piensa en lo que parece su hocico.","tags":["ocean"],"opts":["una cadena de montañas","una herramienta con dientes para cortar","un tipo de ola","un lugar muy frío"],"a":1,"fun":true},{"id":"palB-4-006","topic":"words","level":4,"type":"choice","q":"Planeta es una palabra que incluye a Marte y Venus. ¿Qué palabra incluye a 'tiburón', 'atún' y 'sardina'?","why":"Tiburón, atún y sardina son tipos de pez. Pez es la palabra general que los reúne.","hint":"Busca el grupo grande al que pertenecen.","tags":["sharks"],"opts":["mamífero","molusco","pez","crustáceo"],"a":2},{"id":"palB-4-007","topic":"words","level":4,"type":"choice","q":"El entrenador le dice al lanzador: '____ la pelota con fuerza'. ¿Qué forma de lanzar es una orden?","why":"Una orden se escribe en imperativo: tú, lanza. Lanzo, lanzaba y lanzará cuentan lo que alguien hace o hará.","hint":"Busca la forma que da una orden.","tags":["baseball"],"opts":["Lanzo","Lanzaba","Lanzará","Lanza"],"a":3},{"id":"palB-4-008","topic":"words","level":4,"type":"number","q":"¿Cuántas sílabas tiene la palabra 'paracaídas'?","why":"Pa-ra-ca-í-das tiene cinco sílabas. En 'ca-í' las vocales van separadas, y eso se llama hiato.","hint":"La í con tilde va en su propia sílaba.","tags":[],"a":5},{"id":"palB-4-009","topic":"words","level":4,"type":"choice","q":"¿Cuál de estas palabras es esdrújula, o sea, suena más fuerte en la antepenúltima sílaba?","why":"Sa-TÉ-li-te suena más fuerte tres sílabas antes del final. Planeta, cohete y estrella son llanas.","hint":"Cuenta tres sílabas desde el final.","tags":["space"],"opts":["planeta","cohete","satélite","estrella"],"a":2},{"id":"palB-4-010","topic":"words","level":4,"type":"choice","q":"'El delfín nadaba como un rayo.' ¿Qué figura literaria es?","why":"Compara dos cosas con la palabra como: el delfín y un rayo. Eso es una comparación o símil.","hint":"Busca la palabra que une las dos cosas.","tags":["ocean"],"opts":["metáfora","personificación","rima","comparación"],"a":3},{"id":"palB-4-011","topic":"words","level":4,"type":"choice","q":"El sufijo -ería nombra el lugar donde se vende algo. ¿Dónde se compra pescado?","why":"Pescadería es la tienda donde se vende pescado. Pescadero es la persona que lo vende.","hint":"Busca el nombre del lugar, no de la persona.","tags":["food","ocean"],"opts":["pescadería","pescadero","pescado","pescar"],"a":0},{"id":"palB-4-012","topic":"words","level":4,"type":"order","q":"Ordena estas palabras de la menor a la mayor cantidad de agua.","why":"Una gota es muy poca agua, un charco es más, una laguna es mucho más y un océano es lo más grande.","hint":"Piensa en tamaños.","tags":["ocean"],"opts":["gota","charco","laguna","océano"]},{"id":"palB-4-013","topic":"words","level":4,"type":"choice","q":"¿Qué significa el refrán 'Más vale pájaro en mano que ciento volando'?","why":"Un refrán no se lee al pie de la letra. Aconseja quedarse con lo seguro y no arriesgarlo por algo incierto.","hint":"No habla solo de pájaros: piensa en el consejo.","tags":["animals"],"opts":["Cien pájaros valen más que uno solo","Los pájaros vuelan muy rápido y lejos","Hay que cuidar a las aves","Conviene lo seguro, no lo dudoso"],"a":3},{"id":"palB-4-014","topic":"words","level":4,"type":"choice","q":"El arrecife de coral es un lugar muy ____ . ¿Qué palabra falta?","why":"Bello, con b, significa hermoso. Vello, con v, es pelo fino, y velo es una tela.","hint":"¿Qué palabra significa hermoso?","tags":["ocean"],"opts":["bello","vello","velo","belo"],"a":0},{"id":"palB-4-015","topic":"words","level":4,"type":"choice","q":"¿Cuál oración usa bien la 'y' o la 'e'?","why":"Antes de una palabra que empieza con el sonido i se usa e en lugar de y: peces e invertebrados.","hint":"Fíjate con qué sonido empieza la palabra siguiente.","tags":["ocean"],"opts":["Pescamos peces y invertebrados.","Pescamos peces e erizos.","Pescamos peces u invertebrados.","Pescamos peces e invertebrados."],"a":3},{"id":"palB-4-016","topic":"words","level":4,"type":"choice","q":"Todas las palabras esdrújulas, como 'satélite', llevan tilde.","why":"Las esdrújulas siempre llevan tilde, sin excepción: satélite, rápido, murciélago.","hint":"El golpe de voz cae tres sílabas antes del final.","tags":["space"],"opts":["Verdadero","Falso"],"a":0},{"id":"palB-4-017","topic":"words","level":4,"type":"choice","q":"Este guante es ____ que el otro. ¿Qué palabra falta?","why":"Bueno tiene un comparativo especial: mejor. No se dice más bueno ni más mejor.","hint":"Bueno cambia por completo al comparar.","tags":["baseball"],"opts":["más bueno","más mejor","buenísimo","mejor"],"a":3},{"id":"palB-4-018","topic":"words","level":4,"type":"choice","q":"¿Cuál oración usa bien el verbo haber?","why":"Con el sentido de existir, haber no cambia al plural: había muchos peces. Se dice 'hay peces', no 'hayn'.","hint":"Compara con hay: hay peces.","tags":["ocean"],"opts":["Habían muchos peces en la bahía.","Habia muchos peces en la bahía.","Había muchos peces en la bahía.","Habían mucho peces en la bahía."],"a":2},{"id":"palB-4-019","topic":"words","level":4,"type":"choice","q":"¿Cuál de estas palabras se usa igual para un hombre y una mujer, cambiando solo el artículo?","why":"Se dice el astronauta y la astronauta. En profesor, niño y león cambia la terminación.","hint":"Busca la palabra que no cambia al pasar a femenino.","tags":["space"],"opts":["profesor","astronauta","niño","león"],"a":1},{"id":"palB-4-020","topic":"words","level":4,"type":"choice","q":"En español, el gallo canta 'quiquiriquí'. ¿Cómo se llama una palabra que imita un sonido?","why":"Las onomatopeyas imitan sonidos y cambian entre idiomas. En inglés el gallo dice cock-a-doodle-doo.","hint":"Piensa en palabras como guau o miau.","tags":["animals"],"opts":["sinónimo","onomatopeya","refrán","diptongo"],"a":1,"fun":true},{"id":"palB-5-001","topic":"words","level":5,"type":"choice","q":"¿Cuál oración usa bien 'sé' y 'se'?","why":"Sé, con tilde, viene de saber: yo sé. Se, sin tilde, acompaña a verbos como esconder: se esconde.","hint":"Una es del verbo saber; la otra va con esconde.","tags":["ocean"],"opts":["Yo se que el pulpo sé esconde.","Yo sé que el pulpo sé esconde.","Yo se que el pulpo se esconde.","Yo sé que el pulpo se esconde."],"a":3},{"id":"palB-5-002","topic":"words","level":5,"type":"choice","q":"Un tiburón muy hambriento se comió un pez de un bocado. ¿Qué verbo expresa eso con más fuerza que 'comió'?","why":"Devorar es comer con muchas ganas y muy rápido. Probar y saborear son comer despacio, y picar es comer poquito.","hint":"Busca el verbo para comer con muchísima hambre.","tags":["sharks"],"opts":["probó","devoró","picó","saboreó"],"a":1},{"id":"palB-5-003","topic":"words","level":5,"type":"choice","q":"¿Cómo se escribe el cereal amarillo que se come en mazorca?","why":"En maíz, la tilde sobre la í separa las dos vocales: ma-íz. Sin tilde se leería en una sola sílaba.","hint":"Fíjate en la vocal que suena más fuerte.","tags":["food"],"opts":["maiz","máiz","maíz","maís"],"a":2},{"id":"palB-5-004","topic":"words","level":5,"type":"choice","q":"La palabra 'tomate' viene del náhuatl, el idioma de antiguos pueblos de México.","why":"Tomate viene del náhuatl 'tomatl'. También chocolate, aguacate y chicle vienen de esa lengua.","hint":"El náhuatl le dio al español muchas palabras.","tags":["food"],"opts":["Verdadero","Falso"],"a":0,"fun":true},{"id":"palB-5-005","topic":"words","level":5,"type":"choice","q":"¿Cuál oración usa bien la 'o' o la 'u'?","why":"Antes de una palabra que empieza con el sonido o se usa u en lugar de o: siete u ocho.","hint":"Compara el sonido inicial de siete y de ocho.","tags":["sharks"],"opts":["Hay siete u ocho tiburones.","Hay siete o ocho tiburones.","Hay seis u siete tiburones.","Hay ocho u nueve tiburones."],"a":0},{"id":"palB-5-006","topic":"words","level":5,"type":"choice","q":"Las burbujas del mar son efímeras: duran muy poco. ¿Cuál palabra es lo contrario de 'efímero'?","why":"Efímero es lo que dura poco, y duradero es lo que dura mucho. Frágil es lo que se rompe fácil.","hint":"Busca lo que dura mucho tiempo.","tags":["ocean"],"opts":["frágil","pequeño","redondo","duradero"],"a":3},{"id":"palB-5-007","topic":"words","level":5,"type":"choice","q":"El tiranosaurio era bípedo. ¿Qué significa 'bípedo'?","why":"Bípedo viene de bi- (dos) y pedis (pie): camina sobre dos pies o dos patas. Cuadrúpedo sería de cuatro.","hint":"Piensa en bicicleta: dos ruedas.","tags":["dinosaurs"],"opts":["que camina sobre cuatro patas","que vuela con dos alas","que camina sobre dos patas","que nada con dos aletas"],"a":2},{"id":"palB-5-008","topic":"words","level":5,"type":"number","q":"¿Cuántas sílabas tiene la palabra 'ciempiés'?","why":"Ciem-piés tiene solo dos sílabas, porque la ie de cada una es un diptongo. ¡Aunque el nombre dice cien pies!","hint":"Las vocales juntas 'ie' suenan en una sola sílaba.","tags":["animals"],"a":2,"fun":true},{"id":"palB-5-009","topic":"words","level":5,"type":"choice","q":"¿Cuál oración está bien escrita?","why":"Agua es femenina, pero lleva 'el' por su sonido. El adjetivo sí va en femenino: el agua salada.","hint":"El artículo cambia, pero el adjetivo concuerda con agua.","tags":["ocean"],"opts":["El agua del mar es salada.","El agua del mar es salado.","La agua del mar es salada.","El agua del mar es saladas."],"a":0},{"id":"palB-5-010","topic":"words","level":5,"type":"choice","q":"Ayer el cohete por fin ____ despegar. ¿Qué forma del verbo poder falta?","why":"Poder es irregular en pasado: él pudo. Las otras formas no existen.","hint":"Ayer ya pasó, y el verbo cambia por dentro.","tags":["space"],"opts":["pudo","podió","pudió","puedó"],"a":0},{"id":"palB-5-011","topic":"words","level":5,"type":"choice","q":"Ojalá que mañana no ____ tormenta en la playa. ¿Qué forma del verbo haber falta?","why":"Después de ojalá se usa el subjuntivo: haya. Haiga es un error común, y hay y habrá no encajan.","hint":"Después de ojalá va una forma especial del verbo.","tags":["weather"],"opts":["haiga","hay","haya","habrá"],"a":2},{"id":"palB-5-012","topic":"words","level":5,"type":"order","q":"Ordena estas palabras de la más suave a la más fuerte.","why":"Una brisa es un viento suave, el viento es más fuerte, el vendaval es muy fuerte y el huracán es el más poderoso.","hint":"Imagina un viento que sube de fuerza.","tags":["weather"],"opts":["brisa","viento","vendaval","huracán"]},{"id":"palB-5-013","topic":"words","level":5,"type":"choice","q":"La raíz 'hidro' significa agua. ¿Cuál palabra nombra un avión que despega y aterriza en el agua?","why":"Hidro significa agua, así que un hidroavión es un avión que usa el agua como pista.","hint":"Busca la palabra que empieza con la raíz del agua.","tags":["ocean"],"opts":["helicóptero","paracaídas","planeador","hidroavión"],"a":3},{"id":"palB-5-014","topic":"words","level":5,"type":"choice","q":"Algunos tiburones salen a ____ de noche. ¿Qué verbo falta?","why":"Cazar es buscar animales para comerlos. Casar es unir en boda a dos personas.","hint":"Piensa en lo que hacen los cazadores.","tags":["sharks"],"opts":["casar","cassar","zasar","cazar"],"a":3},{"id":"palB-5-015","topic":"words","level":5,"type":"choice","q":"¿Cuál oración usa bien los dos puntos?","why":"Los dos puntos van después de la frase que anuncia la lista: Trae lo necesario: gorra, guante y pelota.","hint":"Van justo antes de enumerar las cosas.","tags":["baseball"],"opts":["Trae: lo necesario gorra, guante y pelota.","Trae lo necesario: gorra, guante y pelota.","Trae lo necesario gorra: guante y pelota.","Trae lo necesario gorra, guante: y pelota."],"a":1},{"id":"palB-5-016","topic":"words","level":5,"type":"choice","q":"'Mas' sin tilde y 'más' con tilde significan lo mismo.","why":"Más, con tilde, indica cantidad. Mas, sin tilde, significa pero. Una tilde cambia todo.","hint":"Una de las dos se puede cambiar por 'pero'.","tags":[],"opts":["Verdadero","Falso"],"a":1},{"id":"palB-5-017","topic":"words","level":5,"type":"choice","q":"El astronauta flotaba, ingrávido, dentro de la nave. ¿Qué significa 'ingrávido'?","why":"In- significa sin, y grávido viene de grave, que es pesado. Ingrávido es sin peso, por eso flotaba.","hint":"In- puede significar sin.","tags":["space"],"opts":["muy pesado","muy cansado","muy asustado","sin peso"],"a":3},{"id":"palB-5-018","topic":"words","level":5,"type":"choice","q":"'La Luna es una moneda de plata en el cielo.' ¿Qué figura literaria es?","why":"Una metáfora dice que una cosa ES otra, sin usar como. Una comparación sí usaría la palabra como.","hint":"¿Aparece la palabra como?","tags":["space"],"opts":["comparación","metáfora","hipérbole","onomatopeya"],"a":1},{"id":"palB-5-019","topic":"words","level":5,"type":"choice","q":"El sufijo -oso significa 'lleno de'. ¿Qué significa que un fondo marino es rocoso?","why":"Rocoso es roca + -oso: lleno de rocas.","hint":"Piensa en peligroso: lleno de peligro.","tags":["ocean"],"opts":["tiene muchas rocas","no tiene rocas","es muy blando","es muy oscuro"],"a":0},{"id":"palB-5-020","topic":"words","level":5,"type":"choice","q":"Pez es a nadar como ave es a ____ .","why":"El pez se mueve nadando y el ave se mueve volando. Es la misma relación: animal y su manera de moverse.","hint":"Piensa en cómo se mueve cada animal.","tags":["animals"],"opts":["cantar","aire","pluma","volar"],"a":3},{"id":"palB-6-001","topic":"words","level":6,"type":"choice","q":"¿Cuál de estas palabras tiene un triptongo, o sea, tres vocales en una sola sílaba?","why":"Buey tiene u-e-y en una sola sílaba: es un triptongo. Miedo, peine y cuota solo tienen dos vocales juntas.","hint":"Cuenta las vocales que van juntas, incluida la y final.","tags":["animals"],"opts":["miedo","peine","cuota","buey"],"a":3},{"id":"palB-6-002","topic":"words","level":6,"type":"choice","q":"Ala es a ave como aleta es a ____ .","why":"El ala es una parte del ave, y la aleta es una parte del pez.","hint":"Piensa de qué animal es parte cada una.","tags":["sharks"],"opts":["pez","agua","nadar","mar"],"a":0},{"id":"palB-6-003","topic":"words","level":6,"type":"choice","q":"Espera a que el agua ____ antes de echar la pasta. ¿Cuál palabra falta?","why":"Hierva es una forma del verbo hervir, y se escribe con v. Hierba, con b, es una planta verde.","hint":"¿Cuál palabra es una forma del verbo hervir?","tags":["food"],"opts":["hierba","hierva","yerva","ierva"],"a":1},{"id":"palB-6-004","topic":"words","level":6,"type":"choice","q":"Según la RAE, las palabras 'fue' y 'dio' se escriben sin tilde.","why":"Fue, dio, vio y fui tienen una sola sílaba, por eso no llevan tilde.","hint":"Cuenta las sílabas de fue y dio.","tags":[],"opts":["Verdadero","Falso"],"a":0},{"id":"palB-6-005","topic":"words","level":6,"type":"choice","q":"El pulpo es escurridizo: se escapa por cualquier rendija. ¿Qué significa 'escurridizo'?","why":"Escurridizo viene de escurrirse: deslizarse y escapar. Lo escurridizo es difícil de atrapar.","hint":"Usa la pista: se escapa por cualquier rendija.","tags":["ocean"],"opts":["que pesa mucho más que el agua","que hace mucho ruido al moverse","que se mueve muy despacio siempre","difícil de atrapar"],"a":3},{"id":"palB-6-006","topic":"words","level":6,"type":"choice","q":"¿Cuál de estas palabras necesita tilde para separar dos vocales (hiato)?","why":"En bú-ho, la u suena fuerte y se separa de la o, así que lleva tilde. Teatro también es hiato, pero no la necesita.","hint":"Busca una vocal cerrada que suena fuerte junto a otra.","tags":["animals"],"opts":["búho","teatro","cuenta","causa"],"a":0},{"id":"palB-6-007","topic":"words","level":6,"type":"choice","q":"La raíz griega 'ictio' significa pez. ¿Qué estudia un ictiólogo?","why":"Ictio significa pez, y -logo indica quien estudia. Las aves las estudia un ornitólogo.","hint":"La terminación -logo viene de estudio.","tags":["sharks","ocean"],"opts":["las aves","los insectos","las rocas","los peces"],"a":3},{"id":"palB-6-008","topic":"words","level":6,"type":"number","q":"¿Cuántas sílabas tiene la palabra 'braquiosaurio'?","why":"Bra-quio-sau-rio tiene cuatro sílabas: 'io', 'au' e 'io' son diptongos y cada uno cuenta como una sola.","hint":"Busca vocales juntas que suenan en un solo golpe.","tags":["dinosaurs"],"a":4},{"id":"palB-6-009","topic":"words","level":6,"type":"choice","q":"Submarino, marinero y marino nacen de una misma palabra más simple. ¿Cuál es esa palabra primitiva?","why":"La palabra primitiva es la más simple, la que no viene de otra. De mar nacen marino, marinero y submarino.","hint":"Busca la palabra sin prefijo ni sufijo.","tags":["ocean"],"opts":["mar","marino","submarino","marinero"],"a":0},{"id":"palB-6-010","topic":"words","level":6,"type":"choice","q":"Un pelotero ahorrador guarda su dinero. ¿Cuál palabra es lo contrario de 'ahorrador'?","why":"Derrochador gasta sin pensar. Tacaño, austero y cuidadoso se parecen más a ahorrador.","hint":"Busca al que gasta mucho.","tags":["money","baseball"],"opts":["tacaño","derrochador","austero","cuidadoso"],"a":1},{"id":"palB-6-011","topic":"words","level":6,"type":"choice","q":"El tiburón ballena es una ____ muy grande de pez. ¿Qué palabra falta?","why":"Especie es un tipo de ser vivo. Especia es un condimento, como la pimienta.","hint":"¿Cuál palabra nombra un tipo de animal?","tags":["sharks"],"opts":["especia","especie","espécie","espezie"],"a":1},{"id":"palB-6-012","topic":"words","level":6,"type":"order","q":"Ordena alfabéticamente, como en los diccionarios de hoy, donde la ch se ordena letra por letra.","why":"Desde 2010, ch y ll ya no son letras separadas. Chimpancé va entre ce y ci porque se ordena como c-h-i.","hint":"Compara la segunda letra: e, h, i, o.","tags":["animals"],"opts":["cebra","chimpancé","ciervo","cocodrilo"],"fun":true},{"id":"palB-6-013","topic":"words","level":6,"type":"choice","q":"Elige la oración correcta.","why":"Creer lleva directamente 'que', sin 'de', sin 'en' y sin coma. Decir 'creo de que' es un error común.","hint":"Creo que... se dice sin preposición.","tags":["ocean"],"opts":["Creo que el pulpo es muy listo.","Creo de que el pulpo es muy listo.","Creo en que el pulpo es muy listo.","Creo, que el pulpo es muy listo."],"a":0},{"id":"palB-6-014","topic":"words","level":6,"type":"choice","q":"¿Qué significa el refrán 'Camarón que se duerme se lo lleva la corriente'?","why":"El refrán usa un camarón para aconsejar estar atento: quien se distrae se queda sin lo que quería.","hint":"No habla de camarones de verdad: piensa en el consejo.","tags":["ocean"],"opts":["Los camarones duermen de día","Hay que nadar contra la corriente","Quien se descuida pierde su oportunidad","El mar siempre devuelve lo que toma"],"a":2},{"id":"palB-6-015","topic":"words","level":6,"type":"choice","q":"Astrónomo es a telescopio como biólogo es a ____ .","why":"El astrónomo usa un telescopio para ver astros lejanos. El biólogo usa un microscopio para ver seres muy pequeños.","hint":"¿Qué herramienta mira lo diminuto?","tags":["space"],"opts":["martillo","balanza","brújula","microscopio"],"a":3},{"id":"palB-6-016","topic":"words","level":6,"type":"choice","q":"La palabra 'ahí' tiene un diptongo.","why":"En a-hí, la a y la í van en sílabas separadas: es un hiato. La h no las une.","hint":"Cuenta las sílabas de ahí.","tags":[],"opts":["Verdadero","Falso"],"a":1},{"id":"palB-6-017","topic":"words","level":6,"type":"choice","q":"En 'El velero izó la vela', ¿qué significa 'vela'?","why":"Aquí vela es la tela del barco que recibe el viento. También puede ser una barra de cera o quedarse despierto.","hint":"Piensa en lo que necesita un velero para avanzar.","tags":["ocean"],"opts":["barra de cera que se enciende","cuerda gruesa del ancla","tela grande que atrapa el viento","acción de quedarse despierto"],"a":2},{"id":"palB-6-018","topic":"words","level":6,"type":"choice","q":"Los paleontólogos ____ la tierra para encontrar fósiles. ¿Qué forma está bien escrita?","why":"Excavar lleva x porque viene de ex- (fuera): sacar tierra de un lugar.","hint":"Piensa en la palabra excavadora.","tags":["dinosaurs"],"opts":["escavan","ecscavan","exsavan","excavan"],"a":3},{"id":"palB-6-019","topic":"words","level":6,"type":"choice","q":"¿Cuál de estas oraciones está en voz pasiva?","why":"En la voz pasiva, el sujeto recibe la acción: la pelota fue lanzada. En la activa, el sujeto la realiza: el lanzador lanzó.","hint":"Busca el sujeto que recibe la acción.","tags":["baseball"],"opts":["El lanzador lanzó la pelota.","El lanzador lanza muy fuerte.","La pelota fue lanzada por el lanzador.","La pelota rodó hacia la base."],"a":2},{"id":"palB-6-020","topic":"words","level":6,"type":"choice","q":"La palabra 'azúcar' se puede usar como masculina o femenina: el azúcar o la azúcar.","why":"La RAE acepta los dos géneros. Se usa más 'el azúcar', pero en algunos lugares se oye 'la azúcar'.","hint":"Piensa en cómo lo dicen en tu casa.","tags":["food"],"opts":["Verdadero","Falso"],"a":0,"fun":true},{"id":"munB-1-001","topic":"world","level":1,"type":"choice","q":"Los tiburones nadan en una enorme masa de agua salada. ¿Cómo se llama?","why":"El océano es inmenso y salado. En un charco o en una piscina no podría vivir un tiburón.","hint":"Cubre la mayor parte de nuestro planeta.","tags":["sharks","ocean"],"opts":["El océano","Una piscina","Un charco"],"a":0},{"id":"munB-1-002","topic":"world","level":1,"type":"choice","q":"Un mapa es un dibujo que muestra dónde están los lugares.","why":"Los mapas muestran dónde están las ciudades, los caminos, las montañas y los océanos.","hint":"Piensa en lo que usas para encontrar un lugar.","tags":["maps"],"opts":["Verdadero","Falso"],"a":0},{"id":"munB-1-003","topic":"world","level":1,"type":"choice","q":"¿Qué vehículo puede llevar a muchas personas a cruzar el océano?","why":"Los barcos flotan en el agua y son lo bastante grandes para llevar a muchas personas muy lejos.","hint":"Piensa en lo que flota.","tags":["ocean"],"opts":["Una bicicleta","Un barco","Una patineta"],"a":1},{"id":"munB-1-004","topic":"world","level":1,"type":"choice","q":"Un salvavidas trabaja en la playa. ¿Cuál es su trabajo?","why":"Los salvavidas vigilan el agua y ayudan a las personas que están en peligro mientras nadan.","hint":"El nombre dice a quién protege.","tags":["ocean"],"opts":["Cuidar a los bañistas","Vender helados","Arreglar botes"],"a":0},{"id":"munB-1-005","topic":"world","level":1,"type":"number","q":"Cada entrada a un juego de béisbol cuesta 3 dólares. ¿Cuántos dólares cuestan 3 entradas?","why":"Tres entradas de 3 dólares son 3 más 3 más 3, o sea, 9 dólares.","hint":"Suma el precio tres veces.","tags":["baseball","money"],"a":9},{"id":"munB-1-006","topic":"world","level":1,"type":"choice","q":"El sushi es arroz con pescado o verduras. ¿De qué país es muy famoso?","why":"El sushi es un plato tradicional de Japón, un país formado por islas en el océano Pacífico.","hint":"Es un país de islas en Asia.","tags":["food"],"opts":["Chile","México","Japón"],"a":2},{"id":"munB-1-007","topic":"world","level":1,"type":"choice","q":"Chichén Itzá es una gran pirámide que construyeron los mayas. ¿En qué país está?","why":"Chichén Itzá está en la península de Yucatán, en México. Las pirámides de Egipto son otras.","hint":"Los mayas vivieron en Mesoamérica.","tags":["maps"],"opts":["China","México","Egipto"],"a":1},{"id":"munB-1-008","topic":"world","level":1,"type":"order","q":"Ordena los pasos para ir a la escuela en autobús.","why":"Primero esperas el autobús, luego subes, viajas y por último bajas en la escuela.","hint":"¿Qué debe pasar antes de poder viajar?","tags":[],"opts":["Espera en la parada","Sube al autobús","Viaja hasta la escuela","Baja en la escuela"]},{"id":"munB-1-009","topic":"world","level":1,"type":"choice","q":"¿Qué vehículo puede viajar bajo el agua?","why":"Los submarinos están hechos para sumergirse y quedarse bajo el agua. Los helicópteros vuelan y los autobuses van por la calle.","hint":"Su nombre empieza con una palabra que significa debajo.","tags":["ocean"],"opts":["Un helicóptero","Un autobús escolar","Un submarino"],"a":2},{"id":"munB-1-010","topic":"world","level":1,"type":"choice","q":"Los huesos de dinosaurio que se convirtieron en piedra se llaman…","why":"Los fósiles se forman cuando huesos enterrados se vuelven roca durante millones de años. Algunos tienen más de 66 millones de años.","hint":"Vienen de hace muchísimo tiempo.","tags":["dinosaurs"],"opts":["Conchas","Fósiles","Cristales"],"a":1,"fun":true},{"id":"munB-1-011","topic":"world","level":1,"type":"choice","q":"El béisbol se juega solo en Estados Unidos.","why":"Hay aficionados al béisbol en México, Cuba, Venezuela, Japón y muchos otros países.","hint":"Piensa en los países de habla hispana.","tags":["baseball"],"opts":["Verdadero","Falso"],"a":1},{"id":"munB-1-012","topic":"world","level":1,"type":"choice","q":"¿Qué debe hacer un conductor cuando el semáforo está en rojo?","why":"El rojo significa alto. Esperar en el semáforo protege a los conductores y a quienes cruzan.","hint":"Piensa en los colores de un semáforo.","tags":[],"opts":["Detenerse","Acelerar","Tocar la bocina y seguir"],"a":0},{"id":"munB-1-013","topic":"world","level":1,"type":"choice","q":"¿Qué vehículo lleva a los astronautas al espacio?","why":"Un cohete empuja con mucha fuerza para subir por encima del aire y llevar a los astronautas al espacio.","hint":"Despega con fuego y humo.","tags":["space","machines"],"opts":["Un cohete","Un velero","Un autobús escolar"],"a":0},{"id":"munB-1-014","topic":"world","level":1,"type":"order","q":"Ordena estas masas de agua de la más pequeña a la más grande.","why":"Un charco es diminuto, un lago es mucho mayor, y el océano es tan grande que en él viven ballenas y tiburones.","hint":"Piensa en lo que podría contener una ballena.","tags":["ocean"],"opts":["Un charco","Un lago","El océano"]},{"id":"munB-1-015","topic":"world","level":1,"type":"number","q":"Ahorras 2 dólares cada semana. ¿Cuántos dólares tendrás después de 3 semanas?","why":"Suma 2 tres veces: 2 más 2 más 2 son 6 dólares.","hint":"Cuenta de dos en dos.","tags":["money"],"a":6},{"id":"munB-1-016","topic":"world","level":1,"type":"choice","q":"¿Qué invento te permite hablar con un amigo que está lejos?","why":"El teléfono lleva la voz a larga distancia. La brújula señala el norte y la regla sirve para medir.","hint":"Lo acercas a la oreja.","tags":[],"opts":["La brújula","La regla","El teléfono"],"a":2},{"id":"munB-1-017","topic":"world","level":1,"type":"choice","q":"\"Hello\" es una forma de saludar. ¿En qué idioma?","why":"Hello es hola en inglés. El inglés se habla en Estados Unidos, Canadá y otros países.","hint":"Es el idioma de Estados Unidos.","tags":[],"opts":["Inglés","Italiano","Japonés"],"a":0},{"id":"munB-1-018","topic":"world","level":1,"type":"choice","q":"Un globo terráqueo es una hoja de papel plana.","why":"Un globo terráqueo es un modelo de la Tierra con forma de esfera. Una hoja plana de papel es un mapa.","hint":"Piensa en una pelota que puedes girar.","tags":["maps","space"],"opts":["Verdadero","Falso"],"a":1},{"id":"munB-1-019","topic":"world","level":1,"type":"choice","q":"Pones monedas en una alcancía y no las gastas. ¿Qué estás haciendo?","why":"Ahorrar es guardar dinero para usarlo después, por ejemplo para un juguete grande o un viaje.","hint":"Lo guardas para más tarde.","tags":["money"],"opts":["Pidiendo prestado","Ahorrando","Vendiendo"],"a":1},{"id":"munB-1-020","topic":"world","level":1,"type":"choice","q":"Hay un incendio. ¿Quién llega en un camión rojo para apagarlo?","why":"Los bomberos usan mangueras y escaleras para apagar el fuego y ayudar a las personas.","hint":"Usa una manguera grande.","tags":[],"opts":["El panadero","El cartero","El bombero"],"a":2},{"id":"munB-2-001","topic":"world","level":2,"type":"choice","q":"El río Amazonas es uno de los ríos más poderosos de la Tierra. ¿Por qué continente fluye?","why":"El Amazonas atraviesa la selva de América del Sur y desemboca en el océano Atlántico.","hint":"Piensa en la selva junto a los Andes.","tags":["maps"],"opts":["Asia","América del Sur","África"],"a":1},{"id":"munB-2-002","topic":"world","level":2,"type":"choice","q":"Un barco sale de Nueva York y llega a España. ¿Qué océano cruza?","why":"El Atlántico separa América de Europa y África. Los barcos lo cruzan para ir de un lado a otro.","hint":"España está en Europa, al otro lado.","tags":["ocean","maps"],"opts":["El Índico","El Pacífico","El Atlántico"],"a":2},{"id":"munB-2-003","topic":"world","level":2,"type":"choice","q":"Algunos tiburones viven en el océano Ártico, que es muy frío.","why":"Los tiburones de Groenlandia nadan en aguas heladas del Ártico. No todos los tiburones viven en mares cálidos.","hint":"Piensa si un tiburón puede aguantar el frío.","tags":["sharks","ocean"],"opts":["Verdadero","Falso"],"a":0,"fun":true},{"id":"munB-2-004","topic":"world","level":2,"type":"choice","q":"¿Cómo se llama el dinero que una persona gana por hacer su trabajo?","why":"El sueldo es el dinero que se gana trabajando. El precio dice cuánto cuesta algo y un préstamo es dinero que se pide.","hint":"Los trabajadores lo reciben por trabajar.","tags":["money"],"opts":["El préstamo","El sueldo","El precio"],"a":1},{"id":"munB-2-005","topic":"world","level":2,"type":"order","q":"Ordena estas formas de viajar de la más lenta a la más rápida.","why":"Caminar es lo más lento. La bicicleta va más rápido, el carro más aún y el avión es el más veloz.","hint":"Piensa en cuánto recorre cada uno en una hora.","tags":["machines"],"opts":["Caminar","Andar en bicicleta","Manejar un carro","Volar en un avión"]},{"id":"munB-2-006","topic":"world","level":2,"type":"choice","q":"El monte Fuji es un famoso volcán nevado. ¿En qué país está?","why":"El monte Fuji se alza cerca de la costa de Japón, un país formado por muchas islas en el océano Pacífico.","hint":"Es un país de islas en Asia.","tags":["maps"],"opts":["Japón","Perú","Noruega"],"a":0},{"id":"munB-2-007","topic":"world","level":2,"type":"choice","q":"En Brasil, la mayoría de las personas hablan…","why":"Brasil fue colonizado por Portugal, así que allí se habla portugués. La mayoría de sus vecinos hablan español.","hint":"No es el idioma de la mayoría de sus vecinos.","tags":[],"opts":["Portugués","Español","Francés"],"a":0},{"id":"munB-2-008","topic":"world","level":2,"type":"choice","q":"Todos los tiburones son peligrosos para las personas.","why":"Existen más de 500 tipos de tiburones y casi todos son inofensivos para las personas. Muchos son pequeños.","hint":"Piensa en los tiburones pequeños.","tags":["sharks"],"opts":["Verdadero","Falso"],"a":1},{"id":"munB-2-009","topic":"world","level":2,"type":"choice","q":"Una persona que dibuja mapas como trabajo se llama…","why":"Los cartógrafos estudian la tierra y dibujan mapas. Los bibliotecarios cuidan libros y los plomeros arreglan tuberías.","hint":"Piensa en alguien que estudia la tierra y la dibuja.","tags":["maps"],"opts":["Bibliotecario","Plomero","Cartógrafo"],"a":2},{"id":"munB-2-010","topic":"world","level":2,"type":"choice","q":"Una torre en la costa tiene una luz potente que avisa a los barcos de noche. ¿Cómo se llama?","why":"Los faros muestran a los marineros dónde hay rocas y costas para que los barcos naveguen sin peligro.","hint":"Está en la costa y brilla de noche.","tags":["ocean"],"opts":["Molino","Castillo","Faro"],"a":2},{"id":"munB-2-011","topic":"world","level":2,"type":"number","q":"Un paquete de 6 tarjetas de béisbol cuesta 3 dólares. ¿Cuántos dólares cuestan 4 paquetes?","why":"Cuatro paquetes de 3 dólares son 3 más 3 más 3 más 3, que da 12 dólares.","hint":"Suma 3 cuatro veces.","tags":["baseball","money"],"a":12},{"id":"munB-2-012","topic":"world","level":2,"type":"choice","q":"Las tortillas tradicionales de México se hacen con harina de…","why":"Los pueblos de México cultivan maíz desde hace miles de años. Con su masa se hacen tortillas, tamales y más.","hint":"Es un cereal con mazorcas amarillas.","tags":["food"],"opts":["Papa","Maíz","Arroz"],"a":1},{"id":"munB-2-013","topic":"world","level":2,"type":"choice","q":"Se han encontrado fósiles de dinosaurios en la Antártida.","why":"Hace millones de años la Antártida era cálida y verde. Allí se han desenterrado huesos de dinosaurio.","hint":"Piensa en cómo era la Antártida hace muchísimo tiempo.","tags":["dinosaurs"],"opts":["Verdadero","Falso"],"a":0,"fun":true},{"id":"munB-2-014","topic":"world","level":2,"type":"choice","q":"¿Para qué sirve un puente?","why":"Los puentes sostienen caminos y vías de tren sobre ríos y huecos profundos para que la gente pase.","hint":"Piensa en lo que hay debajo de un puente.","tags":["machines"],"opts":["Para cruzar un río o un valle","Para flotar sobre las olas del mar","Para excavar túneles bajo la tierra"],"a":0},{"id":"munB-2-015","topic":"world","level":2,"type":"choice","q":"¿Qué fue lo que excavó el Gran Cañón durante millones de años?","why":"El río Colorado fue desgastando la roca poco a poco y hoy el cañón es muy profundo.","hint":"Piensa en lo que hace el agua con la roca.","tags":[],"opts":["Máquinas gigantes","Un meteorito","Un río"],"a":2},{"id":"munB-2-016","topic":"world","level":2,"type":"number","q":"Un tiburón nada 5 kilómetros cada hora. ¿Cuántos kilómetros nada en 3 horas?","why":"Tres horas de 5 kilómetros son 5 más 5 más 5, o sea, 15 kilómetros.","hint":"Suma 5 tres veces.","tags":["sharks"],"a":15},{"id":"munB-2-017","topic":"world","level":2,"type":"choice","q":"¿Qué invento ayudó a mover cargas pesadas con menos esfuerzo?","why":"Las ruedas ruedan en vez de arrastrar, así que los carros y las carretas llevan peso empujando mucho menos.","hint":"Es redonda y rueda.","tags":["machines"],"opts":["La rueda","La cometa","El clip"],"a":0},{"id":"munB-2-018","topic":"world","level":2,"type":"choice","q":"Un barco gigante lleva cientos de cajas de juguetes y ropa por el mar. ¿Cómo se llama?","why":"Los cargueros transportan mercancías entre países. Un velero usa velas y una lancha es pequeña.","hint":"Su nombre habla de la carga que lleva.","tags":["ocean"],"opts":["Lancha","Carguero","Velero"],"a":1},{"id":"munB-2-019","topic":"world","level":2,"type":"choice","q":"Australia es un país y también un continente.","why":"Australia es un solo país que ocupa un continente entero. La mayoría de los continentes tienen muchos países.","hint":"No lo comparte con otros países.","tags":["maps","ocean"],"opts":["Verdadero","Falso"],"a":0},{"id":"munB-2-020","topic":"world","level":2,"type":"choice","q":"Te prestan un libro en la biblioteca. ¿Qué debes prometer?","why":"Las bibliotecas prestan libros a todos. Devolver el tuyo permite que otra persona lo disfrute.","hint":"Las bibliotecas prestan, no regalan.","tags":[],"opts":["Devolverlo a tiempo","Quedártelo para siempre","Dibujar en las páginas"],"a":0},{"id":"munB-3-001","topic":"world","level":3,"type":"choice","q":"En un mapa, ¿para qué sirve la leyenda?","why":"La leyenda explica los símbolos, como una tienda de campaña que marca un campamento. La rosa de los vientos indica direcciones.","hint":"Busca el recuadro que explica los dibujitos.","tags":["maps"],"opts":["Para saber quién hizo el mapa y cuándo","Para saber qué tan lejos están dos lugares","Para explicar qué significan los símbolos","Para saber dónde queda el norte"],"a":2},{"id":"munB-3-002","topic":"world","level":3,"type":"choice","q":"¿Qué océano queda entre África y Australia?","why":"El Índico baña África, Asia y Australia. El Atlántico queda al otro lado de África y el Pacífico, al este de Australia.","hint":"Su nombre se parece al de un país de Asia.","tags":["ocean","maps"],"opts":["El Atlántico","El Pacífico","El Ártico","El Índico"],"a":3},{"id":"munB-3-003","topic":"world","level":3,"type":"choice","q":"Los tiburones blancos viven cerca de las costas de California, Sudáfrica y Australia.","why":"Los tiburones blancos nadan en aguas costeras templadas de todo el mundo, incluidos estos tres lugares.","hint":"Los tiburones blancos recorren muchos océanos.","tags":["sharks","ocean"],"opts":["Verdadero","Falso"],"a":0},{"id":"munB-3-004","topic":"world","level":3,"type":"choice","q":"¿Cuál de estas cosas es un servicio y no un producto?","why":"Un servicio es un trabajo que alguien hace para ti. Los productos son cosas que puedes tocar, como un bate o una bicicleta.","hint":"No puedes llevártelo a casa en una bolsa.","tags":["money"],"opts":["Una bicicleta","Un corte de pelo","Un sándwich","Un bate de béisbol"],"a":1},{"id":"munB-3-005","topic":"world","level":3,"type":"order","q":"Ordena estos inventos del más antiguo al más nuevo.","why":"La rueda tiene miles de años. La brújula se usó hace siglos, el teléfono llegó en 1876 y las computadoras, mucho después.","hint":"¿Cuál se inventó antes que la electricidad?","tags":["machines"],"opts":["La rueda","La brújula","El teléfono","La computadora"]},{"id":"munB-3-006","topic":"world","level":3,"type":"choice","q":"¿En qué idioma se dice \"arigato\" para dar las gracias?","why":"Arigato significa gracias en japonés. El coreano, el hindi y el italiano tienen sus propias palabras para agradecer.","hint":"Se habla en islas del océano Pacífico.","tags":[],"opts":["Hindi","Coreano","Japonés","Italiano"],"a":2},{"id":"munB-3-007","topic":"world","level":3,"type":"choice","q":"El Aconcagua, la montaña más alta de América, pertenece a la cordillera de…","why":"El Aconcagua está en los Andes, en Argentina. Los Alpes están en Europa y el Himalaya, en Asia.","hint":"Esa cordillera recorre América del Sur.","tags":["maps"],"opts":["El Himalaya","Los Alpes","Las Rocosas","Los Andes"],"a":3},{"id":"munB-3-008","topic":"world","level":3,"type":"number","q":"Una etiqueta en un tiburón envía una señal cada 2 horas. ¿Cuántas señales envía en un día completo?","why":"Un día tiene 24 horas. Si divides 24 horas en grupos de 2 horas, salen 12 señales.","hint":"¿Cuántos 2 caben en 24?","tags":["sharks"],"a":12},{"id":"munB-3-009","topic":"world","level":3,"type":"choice","q":"¿Qué es un puerto?","why":"En los puertos se suben y bajan mercancías de los barcos grandes, y los pasajeros pueden embarcar.","hint":"Piensa en dónde se detienen los barcos.","tags":["ocean"],"opts":["Un bote pequeño para pescar","Una bandera que ondea en un mástil","Una cuerda que amarra un bote al muelle","Un lugar para cargar y descargar barcos"],"a":3},{"id":"munB-3-010","topic":"world","level":3,"type":"choice","q":"Todos los países del mundo usan el mismo tipo de dinero.","why":"Los países tienen su propio dinero, como dólares, pesos o yenes. Solo algunos grupos de países comparten uno.","hint":"Piensa en el dinero de distintos países.","tags":["money"],"opts":["Verdadero","Falso"],"a":1},{"id":"munB-3-011","topic":"world","level":3,"type":"choice","q":"¿Quién cuida un parque nacional y ayuda a proteger a los visitantes y a los animales?","why":"Los guardaparques protegen los lugares silvestres, responden preguntas y ayudan a quienes se pierden.","hint":"Piensa en quién protege los lugares silvestres.","tags":["animals"],"opts":["Un guardaparques","Un cocinero","Un controlador aéreo","Un cartero"],"a":0},{"id":"munB-3-012","topic":"world","level":3,"type":"choice","q":"En la Patagonia argentina se han hallado huesos de dinosaurios gigantes. ¿Por qué es fácil verlos allí?","why":"Los dinosaurios vivieron en muchos lugares. En tierras áridas, el viento y la lluvia desgastan la roca y descubren huesos enterrados.","hint":"Piensa en lo que desgasta las rocas.","tags":["dinosaurs"],"opts":["Viento y lluvia desgastan la roca","El aire seco convierte los huesos en piedra","Los dinosaurios solo vivieron en lugares secos","Las dunas llevaron los huesos hasta allí"],"a":0},{"id":"munB-3-013","topic":"world","level":3,"type":"number","q":"Un tren recorre 80 kilómetros cada hora. ¿Cuántos kilómetros recorre en 3 horas?","why":"Suma 80 tres veces: 80 más 80 más 80 son 240 kilómetros.","hint":"Suma 80 tres veces.","tags":["machines"],"a":240},{"id":"munB-3-014","topic":"world","level":3,"type":"choice","q":"Es de día en América, pero de noche en Asia. ¿Por qué?","why":"La Tierra es una esfera que gira, y el Sol solo ilumina la mitad. Al girar, el día y la noche se desplazan.","hint":"Piensa en lo que hace la Tierra cada 24 horas.","tags":["space"],"opts":["Asia queda mucho más lejos del Sol hoy","La Tierra gira, el Sol alumbra un lado","La Luna tapa el Sol sobre Asia entera","El Sol rodea la Tierra todos los días"],"a":1},{"id":"munB-3-015","topic":"world","level":3,"type":"choice","q":"Cuba y la República Dominicana, donde el béisbol es muy popular, están en el mar…","why":"Cuba y la República Dominicana son islas del cálido mar Caribe, al sureste de Florida.","hint":"Piensa en islas cálidas cerca de Florida.","tags":["baseball","ocean","maps"],"opts":["Caribe","Báltico","Rojo","Mediterráneo"],"a":0},{"id":"munB-3-016","topic":"world","level":3,"type":"order","q":"Ordena estos lugares del más alto al más bajo.","why":"Las montañas se elevan sobre las colinas, las playas están al nivel del mar y el fondo del océano queda muy por debajo.","hint":"Empieza por el lugar más cercano a las nubes.","tags":["ocean"],"opts":["La cima de una montaña","La cima de una colina","Una playa a nivel del mar","El fondo del océano"]},{"id":"munB-3-017","topic":"world","level":3,"type":"choice","q":"Los antiguos egipcios escribían con dibujos y símbolos llamados…","why":"Los jeroglíficos se tallaban en templos y se pintaban en papiros. La escritura cuneiforme usaba marcas con forma de cuña en arcilla.","hint":"Piensa en la escritura con dibujos de los templos.","tags":[],"opts":["Cuneiformes","Jeroglíficos","Braille","Código Morse"],"a":1},{"id":"munB-3-018","topic":"world","level":3,"type":"choice","q":"Hacia 1610, Galileo usó un invento nuevo para ver las lunas que giran alrededor de Júpiter. ¿Cuál era?","why":"Los telescopios acercan lo que está muy lejos. Un microscopio agranda lo muy pequeño.","hint":"Acerca lo que está lejos.","tags":["space"],"opts":["Una cámara","Un microscopio","Una brújula","Un telescopio"],"a":3},{"id":"munB-3-019","topic":"world","level":3,"type":"choice","q":"En Paraguay, el español y el guaraní son idiomas oficiales.","why":"Muchos paraguayos hablan guaraní, una lengua de los pueblos originarios, y también español. Algunos países tienen más de un idioma oficial.","hint":"Piensa en un país con una lengua indígena muy viva.","tags":[],"opts":["Verdadero","Falso"],"a":0,"fun":true},{"id":"munB-3-020","topic":"world","level":3,"type":"choice","q":"Un panadero hace pan y una familia lo compra para comérselo. ¿Cómo se llama la persona que compra y usa el pan?","why":"Los productores hacen los productos y los consumidores los compran y los usan. El panadero produce y la familia consume.","hint":"La familia se lo come.","tags":["food","money"],"opts":["Banquero","Productor","Inventor","Consumidor"],"a":3},{"id":"munB-4-001","topic":"world","level":4,"type":"choice","q":"El suroeste queda justo entre dos direcciones. ¿Cuáles son?","why":"El suroeste mezcla el sur y el oeste. Norte y oeste forman el noroeste, y sur y este forman el sureste.","hint":"Di el nombre en dos partes.","tags":["maps"],"opts":["Sur y este","Sur y oeste","Norte y oeste","Norte y este"],"a":1},{"id":"munB-4-002","topic":"world","level":4,"type":"choice","q":"Una tienda baja el precio de los abrigos cuando llega el calor. ¿Por qué?","why":"Cuando menos personas quieren algo, los vendedores suelen bajar el precio para vender lo que les queda.","hint":"Piensa en quién quiere un abrigo cuando hace calor.","tags":["money","weather"],"opts":["Porque cuesta más fabricar abrigos en verano","Porque en verano hay más gente comprando abrigos","Porque menos gente quiere abrigos","Porque solo se venden abrigos en invierno"],"a":2},{"id":"munB-4-003","topic":"world","level":4,"type":"choice","q":"El océano Atlántico toca América del Norte, América del Sur, Europa y África.","why":"El Atlántico se extiende entre las Américas, por un lado, y Europa y África, por el otro.","hint":"Imagina el Atlántico en el centro de un mapamundi.","tags":["ocean","maps"],"opts":["Verdadero","Falso"],"a":0},{"id":"munB-4-004","topic":"world","level":4,"type":"choice","q":"¿Cuál es la capital de Brasil?","why":"Brasilia se construyó en el centro del país para ser la capital. Río y São Paulo son más conocidas, por eso mucha gente las elige.","hint":"Es una ciudad planeada y relativamente nueva.","tags":["maps"],"opts":["Brasilia","Lima","Río de Janeiro","São Paulo"],"a":0},{"id":"munB-4-005","topic":"world","level":4,"type":"choice","q":"Tu teléfono muestra dónde estás con el GPS. El GPS funciona con señales de…","why":"Los satélites del GPS orbitan muy alto y mandan señales. El teléfono las usa para calcular exactamente dónde está.","hint":"Viajan muy por encima del cielo.","tags":["space","maps"],"opts":["Faros encendidos en todas las costas","Grandes torres construidas sobre la Luna","Satélites que orbitan la Tierra","Cables enterrados muy hondo bajo el suelo"],"a":2},{"id":"munB-4-006","topic":"world","level":4,"type":"number","q":"Un barco navega 20 kilómetros cada hora. ¿Cuántas horas necesita para recorrer 100 kilómetros?","why":"Divide 100 kilómetros entre 20 kilómetros por hora. Cinco horas de navegación cubren 100 kilómetros.","hint":"¿Cuántos 20 caben en 100?","tags":["ocean"],"a":5},{"id":"munB-4-007","topic":"world","level":4,"type":"choice","q":"La palabra \"safari\" viene del suajili, un idioma del este de África. ¿Qué significa \"safari\" allí?","why":"Safari significa viaje en suajili. La palabra pasó a otros idiomas por los viajes largos que se hacían por África.","hint":"Mucha gente hace uno para ver animales salvajes.","tags":["animals"],"opts":["Viaje","Cazador","Animal salvaje","Atardecer"],"a":0,"fun":true},{"id":"munB-4-008","topic":"world","level":4,"type":"choice","q":"¿Qué científico estudia el clima y avisa cuando viene un huracán?","why":"Los meteorólogos estudian el aire y el clima. Los oceanógrafos estudian el mar, los geólogos las rocas y los cartógrafos hacen mapas.","hint":"Piensa en el pronóstico del tiempo.","tags":["weather"],"opts":["Un cartógrafo","Un meteorólogo","Un geólogo","Un oceanógrafo"],"a":1},{"id":"munB-4-009","topic":"world","level":4,"type":"order","q":"Ordena de lo más antiguo a lo más reciente.","why":"Los dinosaurios fueron primero. Las pinturas de cuevas tienen decenas de miles de años, las pirámides mayas miles, y la Luna fue en 1969.","hint":"¿Qué pasó antes de que existieran personas?","tags":["dinosaurs","space"],"opts":["Los dinosaurios dominan la Tierra","Las personas pintan en cuevas","Los mayas construyen pirámides","Los astronautas llegan a la Luna"]},{"id":"munB-4-010","topic":"world","level":4,"type":"choice","q":"El canal de Panamá une el Atlántico y el Pacífico. Sin él, los barcos tendrían que rodear un continente. ¿Cuál?","why":"El canal cruza Panamá, una franja angosta de tierra. Los barcos ahorran miles de kilómetros al no rodear América del Sur.","hint":"Piensa en la forma de las Américas.","tags":["ocean","maps"],"opts":["África","Asia","Australia","América del Sur"],"a":3},{"id":"munB-4-011","topic":"world","level":4,"type":"choice","q":"El maíz se cultivó por primera vez hace miles de años en una región que hoy es…","why":"Los pueblos de Mesoamérica convirtieron una hierba silvestre en maíz. Desde allí, este cereal viajó por el mundo.","hint":"Es la tierra de las tortillas.","tags":["food"],"opts":["México","Egipto","Australia","China"],"a":0},{"id":"munB-4-012","topic":"world","level":4,"type":"choice","q":"Casi nunca crecen ciudades grandes junto a ríos o puertos.","why":"Los barcos transportaban comida y productos con poco costo, así que la gente se instaló junto a ríos y puertos.","hint":"¿Cómo viajaban los productos hace mucho tiempo?","tags":["ocean","money"],"opts":["Verdadero","Falso"],"a":1},{"id":"munB-4-013","topic":"world","level":4,"type":"choice","q":"Un científico le pone una etiqueta a un tiburón. ¿Qué puede mostrar la etiqueta?","why":"Las etiquetas registran la ruta del tiburón y qué tan hondo se sumerge. No cuentan dientes ni muestran sus comidas.","hint":"Piensa en mapas y viajes.","tags":["sharks","maps"],"opts":["Qué pez comió ayer","Qué tan fuerte late su corazón","Cuántos dientes le saldrán","Por dónde viaja"],"a":3},{"id":"munB-4-014","topic":"world","level":4,"type":"choice","q":"En el desierto de Gobi se han hallado nidos de dinosaurio con huevos. ¿En qué continente está el Gobi?","why":"El Gobi se extiende por Mongolia y el norte de China. Allí se han encontrado huesos y nidos de dinosaurio.","hint":"Piensa en Mongolia y China.","tags":["dinosaurs","maps"],"opts":["África","Australia","América del Sur","Asia"],"a":3,"fun":true},{"id":"munB-4-015","topic":"world","level":4,"type":"number","q":"Un puesto vende 40 hot dogs en un juego de béisbol a 3 dólares cada uno. ¿Cuántos dólares recibe?","why":"40 por 3 es 120. El dinero que se recibe al vender se llama ingreso; la ganancia es lo que queda después de los gastos.","hint":"Piensa en 4 decenas por 3.","tags":["baseball","money"],"a":120},{"id":"munB-4-016","topic":"world","level":4,"type":"choice","q":"Los productos que un país vende a otros países se llaman…","why":"Las exportaciones salen del país para venderse afuera. Las importaciones son productos que llegan de otros países.","hint":"Piensa en 'ex' como en 'exterior'.","tags":["money"],"opts":["Impuestos","Importaciones","Exportaciones","Ahorros"],"a":2},{"id":"munB-4-017","topic":"world","level":4,"type":"choice","q":"En lugares muy calurosos y soleados, muchas casas se pintan de blanco. ¿Por qué?","why":"Los colores claros rechazan la luz del sol en lugar de absorberla, así que las paredes blancas se calientan menos.","hint":"Piensa en usar una camiseta blanca bajo el sol.","tags":["weather"],"opts":["Es la pintura más barata que existe","Evita que la lluvia entre por las paredes","Detiene el viento fuerte que llega del mar","Refleja el sol y mantiene fresca la casa"],"a":3},{"id":"munB-4-018","topic":"world","level":4,"type":"order","q":"Ordena estas formas de compartir mensajes, de la más antigua a la más nueva.","why":"Primero las cuevas. Luego los libros impresos del siglo XV, el teléfono hacia 1870 y el correo electrónico hacia 1970.","hint":"¿Cuáles necesitan electricidad?","tags":[],"opts":["Dibujos en cuevas","Libros impresos","Llamadas telefónicas","Correo electrónico"]},{"id":"munB-4-019","topic":"world","level":4,"type":"choice","q":"¿Cuál de estos países usa el peso como moneda?","why":"México usa el peso. Brasil usa el real, Perú el sol y Estados Unidos el dólar. Cada país suele tener su propia moneda.","hint":"Piensa en el dinero de países vecinos.","tags":["money"],"opts":["Estados Unidos","México","Perú","Brasil"],"a":1},{"id":"munB-4-020","topic":"world","level":4,"type":"choice","q":"En la isla de Pascua hay enormes estatuas de piedra llamadas moáis. ¿En qué océano está la isla?","why":"La isla de Pascua, o Rapa Nui, pertenece a Chile y está en medio del Pacífico, a miles de kilómetros de la costa.","hint":"Piensa en un océano muy ancho al oeste de Chile.","tags":["ocean","maps"],"opts":["El Ártico","El Atlántico","El Índico","El Pacífico"],"a":3,"fun":true},{"id":"munB-5-001","topic":"world","level":5,"type":"choice","q":"¿Por qué los países comercian entre sí?","why":"El clima, la tierra y las habilidades son distintos, así que los países intercambian lo que les sobra por lo que no pueden producir fácilmente.","hint":"Piensa en bananas en un país muy frío.","tags":["money"],"opts":["Solo los países pequeños lo necesitan","Todos los países producen todo lo que necesitan","El comercio ayuda solo al país que vende","Cada uno tiene lo que falta al otro"],"a":3},{"id":"munB-5-002","topic":"world","level":5,"type":"choice","q":"En muchos mapas planos, Groenlandia parece tan grande como África, pero África es mucho mayor. ¿Por qué?","why":"Al aplanar una Tierra redonda se estiran los lugares cercanos a los polos. África es unas 14 veces más grande que Groenlandia.","hint":"Piensa en aplanar la cáscara de una naranja.","tags":["maps"],"opts":["Los cartógrafos dibujan más pequeños los países grandes","Groenlandia creció mucho desde esos mapas","El hielo hace más alta a Groenlandia","Aplanar la Tierra estira las zonas polares"],"a":3,"fun":true},{"id":"munB-5-003","topic":"world","level":5,"type":"choice","q":"Si cruzas la línea internacional de cambio de fecha hacia el oeste, el calendario retrocede un día.","why":"Al cruzar hacia el oeste, en el Pacífico, el calendario salta un día hacia adelante. Hacia el este, se pierde un día.","hint":"¿Hacia dónde empieza antes el nuevo día?","tags":["ocean","maps"],"opts":["Verdadero","Falso"],"a":1},{"id":"munB-5-004","topic":"world","level":5,"type":"choice","q":"¿Cómo se llama una franja angosta de tierra que une dos tierras más grandes y tiene agua a ambos lados?","why":"Panamá es un istmo. Una península tiene agua por tres lados y un archipiélago es un grupo de islas.","hint":"El ejemplo más famoso es Panamá.","tags":["maps"],"opts":["Una península","Un istmo","Un delta","Un archipiélago"],"a":1},{"id":"munB-5-005","topic":"world","level":5,"type":"choice","q":"La Ruta de la Seda unía China con el Mediterráneo. Además de productos, ¿qué viajaba por ella?","why":"Por la Ruta de la Seda se difundieron ideas, como la fabricación de papel, junto con la seda y las especias.","hint":"Los viajeros también compartían lo que sabían.","tags":[],"opts":["Pasajeros de globos aerostáticos","Líneas telefónicas y cables","Gigantescos barcos de acero","Ideas e inventos"],"a":3},{"id":"munB-5-006","topic":"world","level":5,"type":"order","q":"Ordena las zonas del océano desde la superficie hasta lo más profundo.","why":"La luz se apaga con la profundidad: primero capa brillante, luego penumbra, después oscuridad total y por último las fosas.","hint":"La luz solo llega a la parte de arriba.","tags":["ocean"],"opts":["Zona iluminada","Zona crepuscular","Zona de medianoche","Fosa oceánica"]},{"id":"munB-5-007","topic":"world","level":5,"type":"choice","q":"La piedra de Rosetta ayudó a leer por fin los jeroglíficos egipcios. ¿Por qué?","why":"Una de las escrituras era el griego, que los sabios sí leían. Al compararlas descifraron los jeroglíficos.","hint":"Una de las escrituras ya se conocía.","tags":[],"opts":["Tenía el mismo mensaje en tres escrituras","Mostraba un dibujo para cada jeroglífico","Era un diccionario completo tallado en piedra","Un faraón ya la había traducido hace siglos"],"a":0},{"id":"munB-5-008","topic":"world","level":5,"type":"choice","q":"Un partido de béisbol empieza a las 9:00 a. m. del jueves en Tokio. Los Ángeles va unas 16 o 17 horas atrás de Tokio. ¿Qué día es en Los Ángeles?","why":"Si retrocedes 16 o 17 horas desde las 9:00 a. m. del jueves, cruzas la medianoche y llegas a la tarde del día anterior.","hint":"Al retroceder tantas horas, cruzas la medianoche.","tags":["baseball","maps"],"opts":["Jueves","Martes","Miércoles","Viernes"],"a":2},{"id":"munB-5-009","topic":"world","level":5,"type":"choice","q":"El mar Mediterráneo toca Europa, África y Asia.","why":"El sur de Europa, el norte de África y el oeste de Asia tienen costas en el Mediterráneo.","hint":"Piensa en España, Egipto y Turquía.","tags":["ocean","maps"],"opts":["Verdadero","Falso"],"a":0},{"id":"munB-5-010","topic":"world","level":5,"type":"choice","q":"¿Cuál de estos países de América del Sur no tiene costa en ningún océano?","why":"Bolivia no tiene costa; está rodeada de otros países. Chile, Perú y Ecuador tienen costa en el océano Pacífico.","hint":"Piensa en un país rodeado de montañas y vecinos.","tags":["maps"],"opts":["Ecuador","Bolivia","Perú","Chile"],"a":1},{"id":"munB-5-011","topic":"world","level":5,"type":"choice","q":"Se han hallado fósiles de los mismos dinosaurios en América del Sur y en África. ¿Qué lo explica mejor?","why":"Hace mucho, los continentes formaban una gran masa de tierra y los dinosaurios caminaban entre lugares hoy muy distantes.","hint":"Mira cómo encajan las costas de ambos continentes.","tags":["dinosaurs","maps"],"opts":["Hoy ambos lugares tienen el mismo clima","Los cazadores de fósiles llevaron los huesos","Los continentes estuvieron unidos","Los dinosaurios cruzaban nadando el Atlántico"],"a":2,"fun":true},{"id":"munB-5-012","topic":"world","level":5,"type":"number","q":"La Tierra mide unos 40 000 kilómetros alrededor del ecuador. Un avión vuela a 800 kilómetros por hora. ¿Cuántas horas tardaría en dar la vuelta completa?","why":"Divide 40 000 entre 800 y obtienes 50 horas, es decir, más de dos días enteros de vuelo.","hint":"Divide la distancia entre la velocidad.","tags":["maps","machines"],"a":50},{"id":"munB-5-013","topic":"world","level":5,"type":"choice","q":"¿Cuál de estas cosas suele pagarse con impuestos?","why":"Los impuestos pagan servicios compartidos, como bibliotecas, caminos y estaciones de bomberos. Las tiendas cobran a sus clientes.","hint":"Piensa en servicios que usa todo el pueblo.","tags":["money"],"opts":["Una pelota en una tienda","Una comida en un restaurante","Una entrada al cine","Una biblioteca pública"],"a":3},{"id":"munB-5-014","topic":"world","level":5,"type":"choice","q":"Casi todo lo que cruza el océano viaja en contenedores metálicos del mismo tamaño. ¿Por qué sirve que sean iguales?","why":"Los contenedores iguales se apilan bien y pasan del barco al tren y al camión sin desempacar, y así se ahorra tiempo y dinero.","hint":"Piensa en apilar bloques idénticos.","tags":["ocean","machines","money"],"opts":["Hacen que los barcos sean más veloces","Hacen que la carga pese menos","Caben en barcos, trenes y camiones","Mantienen frías las mercancías"],"a":2},{"id":"munB-5-015","topic":"world","level":5,"type":"order","q":"Ordena los pasos para mostrar cómo llega un pescado del mar a la mesa.","why":"El pescado viaja del productor al consumidor: se pesca, llega al puerto, va a la tienda y luego se cocina.","hint":"Sigue al pescado del mar al plato.","tags":["ocean","food"],"opts":["La tripulación pesca el pescado","El barco descarga en el puerto","Un camión lo lleva a la tienda","Una familia lo cocina en casa"]},{"id":"munB-5-016","topic":"world","level":5,"type":"choice","q":"¿Por qué los pilotos escuchan a los controladores aéreos desde tierra?","why":"Los controladores vigilan el cielo y dicen a los pilotos cuándo despegar, aterrizar o cambiar de rumbo, para que no se acerquen demasiado.","hint":"Piensa en un cielo con muchos aviones.","tags":["machines"],"opts":["Para saber qué botanas hay a bordo","Para mantener separados los aviones","Para saber cuántos pasajeros viajan","Para cargar gasolina en el aeropuerto"],"a":1},{"id":"munB-5-017","topic":"world","level":5,"type":"choice","q":"Muchas plataformas de lanzamiento de cohetes están cerca del océano. ¿Cuál es una buena razón?","why":"Los cohetes sueltan piezas usadas mientras suben. Lanzar sobre el mar mantiene esas piezas lejos de las personas.","hint":"Piensa en dónde caen las piezas sobrantes.","tags":["space","ocean"],"opts":["Las piezas caen al agua, no en pueblos","Las olas ayudan al cohete a subir","Los cohetes queman agua salada como combustible","El aire marino aligera los cohetes"],"a":0},{"id":"munB-5-018","topic":"world","level":5,"type":"choice","q":"Una isla solo puede pertenecer a un país, nunca a dos.","why":"Tierra del Fuego se reparte entre Chile y Argentina. Una isla también puede tener fronteras, igual que un continente.","hint":"Piensa en fronteras sobre una isla.","tags":["ocean","maps"],"opts":["Verdadero","Falso"],"a":1},{"id":"munB-5-019","topic":"world","level":5,"type":"choice","q":"Un tiburón con etiqueta nada por las aguas de muchos países. ¿Qué muestra esto sobre cómo protegerlos?","why":"Los tiburones no respetan fronteras. Uno protegido en un país puede estar en peligro en el siguiente, y por eso los países deben cooperar.","hint":"Los tiburones no se detienen en las fronteras.","tags":["sharks","ocean"],"opts":["Las reglas importan solo cerca de la costa","Las reglas de un país bastan siempre","Un tiburón está a salvo lejos de tierra","Los países deben cooperar para protegerlos"],"a":3},{"id":"munB-5-020","topic":"world","level":5,"type":"choice","q":"En los Andes y en Asia, los agricultores construyen escalones planos en las laderas de las montañas. ¿Para qué?","why":"Se llaman terrazas, o andenes en los Andes. Evitan que la tierra y el agua rueden cuesta abajo y permiten sembrar en pendientes.","hint":"Piensa en la lluvia bajando por una cuesta.","tags":["food"],"opts":["Para retener la tierra y el agua","Para que no suban los animales","Para frenar el viento frío del pueblo","Para que la montaña parezca más alta"],"a":0},{"id":"munB-6-001","topic":"world","level":6,"type":"choice","q":"Gran Bretaña está muy al norte, pero sus inviernos son bastante suaves. ¿Qué ayuda más?","why":"La corriente del Atlántico Norte lleva agua cálida desde el trópico hacia Europa y suaviza los inviernos.","hint":"Piensa en el agua que toca sus costas.","tags":["ocean","weather"],"opts":["Los volcanes calientan la isla","Está cerca del ecuador","Hay desiertos calurosos a su lado","Una corriente cálida del océano"],"a":3},{"id":"munB-6-002","topic":"world","level":6,"type":"choice","q":"Con los años, casi todos los precios suben poco a poco y un dólar compra menos que antes. ¿Cómo se llama esto?","why":"La inflación es un aumento general de los precios. El interés es el dinero que se paga por prestar o ahorrar.","hint":"Piensa en un globo que se llena de aire.","tags":["money"],"opts":["Escasez","Interés","Exportación","Inflación"],"a":3},{"id":"munB-6-003","topic":"world","level":6,"type":"choice","q":"El lugar más profundo del océano es más profundo de lo que mide de alto el monte Everest.","why":"La fosa de las Marianas tiene casi 11 kilómetros de profundidad y el Everest mide unos 9. El Everest quedaría sumergido.","hint":"Compara cuánto baja con cuánto sube.","tags":["ocean"],"opts":["Verdadero","Falso"],"a":0,"fun":true},{"id":"munB-6-004","topic":"world","level":6,"type":"choice","q":"Un barco está donde el ecuador cruza el meridiano de Greenwich, a 0° de latitud y 0° de longitud. ¿En qué océano está?","why":"Ese punto está en el golfo de Guinea, frente a África occidental. Allí flota una boya meteorológica.","hint":"Imagina dónde se cruzan esas dos líneas en un mapamundi.","tags":["ocean","maps"],"opts":["El Ártico","El Pacífico","El Atlántico","El Índico"],"a":2,"fun":true},{"id":"munB-6-005","topic":"world","level":6,"type":"choice","q":"Se han hallado fósiles de animales marinos en lo alto de los Andes. ¿Qué indica esto?","why":"Al chocar, las placas de la Tierra levantaron el antiguo fondo marino hasta formar montañas. El océano nunca subió tanto.","hint":"¿Qué puede levantar roca durante millones de años?","tags":["ocean"],"opts":["Las aves llevaron las conchas hasta allá","Los animales marinos subían las montañas","El océano llegó a cubrir todos los Andes","El fondo marino se elevó y formó montañas"],"a":3},{"id":"munB-6-006","topic":"world","level":6,"type":"number","q":"Un banco paga 10 % de interés cada año sobre todo tu saldo. Depositas 100 dólares. Después de 2 años, con el interés sumado cada año, ¿cuántos dólares tienes?","why":"El primer año suma 10 dólares y quedan 110. El segundo año suma el 10 % de 110, que es 11, y quedan 121.","hint":"Primero calcula el total del primer año.","tags":["money"],"a":121},{"id":"munB-6-007","topic":"world","level":6,"type":"choice","q":"El español, el francés, el italiano y el portugués se llaman lenguas romances. ¿De qué idioma antiguo vienen?","why":"Estas lenguas nacieron del latín que se hablaba en el Imperio romano, y por eso muchas de sus palabras se parecen.","hint":"Lo hablaban los antiguos romanos.","tags":[],"opts":["Latín","Árabe","Hebreo","Griego"],"a":0},{"id":"munB-6-008","topic":"world","level":6,"type":"choice","q":"¿Cuál de estos países está cruzado por el ecuador y por eso queda en los dos hemisferios?","why":"El ecuador cruza el norte de Brasil. Perú queda al sur de él, y México y Argentina están lejos.","hint":"Piensa en el país donde desemboca el Amazonas.","tags":["maps"],"opts":["Perú","Brasil","Argentina","México"],"a":1},{"id":"munB-6-009","topic":"world","level":6,"type":"order","q":"Ordena en el orden correcto los pasos de un préstamo.","why":"Un préstamo sigue este orden: pedir, recibir, gastar y devolver con un poco más, que se llama interés.","hint":"No puedes gastar dinero antes de tenerlo.","tags":["money"],"opts":["Pides un préstamo al banco","El banco te presta el dinero","Usas el dinero para comprar lo que necesitas","Devuelves el dinero con intereses"]},{"id":"munB-6-010","topic":"world","level":6,"type":"choice","q":"Un acueducto romano baja con una pendiente suave hasta la ciudad. ¿Por qué?","why":"Los romanos no tenían bombas. Una bajada constante dejaba que la gravedad llevara el agua muchos kilómetros.","hint":"¿Hacia dónde fluye el agua por sí sola?","tags":["machines"],"opts":["Animales cargaban el agua en cubetas","Unas bombas empujaban el agua","La gravedad empuja el agua","El viento movía ruedas con el agua"],"a":2},{"id":"munB-6-011","topic":"world","level":6,"type":"choice","q":"En un mapa plano, los vuelos de Los Ángeles a Tokio se curvan hacia el norte. ¿Por qué vuelan así los pilotos?","why":"El camino más corto entre lugares lejanos sobre una esfera se ve curvo en un mapa plano. Se llama círculo máximo.","hint":"Imagina un hilo estirado sobre un globo terráqueo.","tags":["maps","space"],"opts":["Es la ruta más corta sobre una esfera","Los aviones deben volar cerca de tierra","Los cartógrafos dibujaron mal las rutas","Las corrientes del mar guían los aviones"],"a":0},{"id":"munB-6-012","topic":"world","level":6,"type":"choice","q":"El Ártico es un continente rodeado de océano, y la Antártida es un océano rodeado de tierra.","why":"Es al revés. El océano Ártico tiene tierras alrededor, y la Antártida es un continente rodeado por el océano Austral.","hint":"Compara los dos extremos de la Tierra.","tags":["ocean","maps"],"opts":["Verdadero","Falso"],"a":1},{"id":"munB-6-013","topic":"world","level":6,"type":"choice","q":"En el lago de Nicaragua, que es de agua dulce, viven tiburones. ¿Qué tiburón es?","why":"Los tiburones toro toleran el agua dulce y suben por ríos como el San Juan, que llega al lago de Nicaragua.","hint":"Aguanta el agua dulce y la salada.","tags":["sharks"],"opts":["El tiburón ballena","El tiburón martillo","El tiburón toro","El tiburón blanco"],"a":2,"fun":true},{"id":"munB-6-014","topic":"world","level":6,"type":"choice","q":"El mar Muerto es mucho más salado que el océano. ¿Por qué se acumula tanta sal allí?","why":"Los ríos aportan algo de sal, pero el agua solo sale por evaporación. Con el tiempo, la sal se acumula.","hint":"¿Qué queda cuando el agua se seca?","tags":[],"opts":["El agua se evapora y la sal queda","Volcanes submarinos echan más sal","Viven peces que fabrican sal","El viento trae sal desde el océano"],"a":0},{"id":"munB-6-015","topic":"world","level":6,"type":"number","q":"Imagina que 1 dólar se cambia por 20 pesos. Una entrada a un juego de béisbol cuesta 100 pesos. ¿Cuántos dólares son?","why":"Cada 20 pesos equivalen a 1 dólar, y en 100 pesos caben cinco grupos de 20. La entrada cuesta 5 dólares.","hint":"¿Cuántos 20 caben en 100?","tags":["baseball","money"],"a":5},{"id":"munB-6-016","topic":"world","level":6,"type":"choice","q":"Una de las primeras escrituras, hecha con marcas sobre arcilla, se usaba sobre todo para…","why":"En Mesopotamia, los escribas marcaban arcilla para anotar granos, animales e intercambios. Los cuentos y poemas vinieron después.","hint":"Piensa en lo que necesitaban recordar los comerciantes.","tags":["money"],"opts":["Escribir canciones y poemas","Dibujar mapas de las estrellas","Enseñar a leer a los niños","Contar y anotar mercancías"],"a":3},{"id":"munB-6-017","topic":"world","level":6,"type":"choice","q":"Chile es un país muy largo y angosto, de norte a sur. ¿Por qué tiene desierto en el norte y zonas nevadas en el sur?","why":"Chile cruza muchas latitudes, desde desiertos cálidos en el norte hasta tierras frías cerca de la Antártida.","hint":"Piensa en la distancia entre sus dos extremos.","tags":["maps"],"opts":["El mar lleva nieve y arena hasta allí","Todo el país está sobre el ecuador","El sur está mucho más cerca del Sol","Se extiende por muchas latitudes"],"a":3},{"id":"munB-6-018","topic":"world","level":6,"type":"order","q":"Ordena los pasos de un estudio que marca tiburones.","why":"Primero hay que capturar al tiburón, ponerle la etiqueta y soltarlo. Después, las señales permiten dibujar su ruta.","hint":"¿Qué debe pasar antes de colocar algo?","tags":["sharks","maps"],"opts":["Los científicos capturan al tiburón","Le colocan una etiqueta","Lo liberan","Dibujan su ruta con las señales"]},{"id":"munB-6-019","topic":"world","level":6,"type":"choice","q":"Muchos cohetes se lanzan hacia el este desde lugares cercanos al ecuador. ¿Cómo ayuda eso?","why":"La Tierra gira hacia el este, y más rápido en el ecuador, así que un lanzamiento hacia el este parte con un impulso gratis.","hint":"Piensa en qué tan rápido se mueve el suelo mismo.","tags":["space"],"opts":["En el ecuador nunca hay nubes ni tormentas","La rotación de la Tierra les da impulso","La Luna siempre está hacia el este","El aire cálido hace que pesen menos"],"a":1},{"id":"munB-6-020","topic":"world","level":6,"type":"choice","q":"Cuando dos países comercian, uno de ellos siempre pierde.","why":"Los dos comercian porque cada uno espera recibir algo que valora más de lo que entrega.","hint":"¿Alguien comerciaría si siempre perdiera?","tags":["money"],"opts":["Verdadero","Falso"],"a":1}];
